  ui_story_5020_50200202_2_dialog_content = "呀！不要過來！",
  ui_story_5020_50200202_3_dialog_content = "<color=#e8d9bb>颯——</color>",
  ui_story_5020_50200202_4_dialog_content = "有沒有受傷？",
  ui_story_5020_50200202_5_dialog_content = "嗚嗚嗚……我沒事，謝謝姐姐。",
