  ui_story_5020_50200202_7_dialog_content = "該死，真是沒完沒了。",
  ui_story_5020_50200202_8_dialog_content = "姐姐，我們該怎麼辦？",
  ui_story_5020_50200202_9_dialog_content = "往那邊跑，不要回頭。",
  ui_story_5020_50200202_10_dialog_content = "<anim type=Shake>呃啊——</anim>",
  ui_story_5020_50200202_11_dialog_content = "PlayerName，你這是在做什麼？",
