  ui_story_5020_50200202_17_option_content = "鬼出去！福進來！！",
  ui_story_5020_50200202_18_dialog_content = "<color=#e8d9bb>啪唰——</color>",
  ui_story_5020_50200202_19_option_content = "鬼粗去！福進乃！！！",
  ui_story_5020_50200202_20_dialog_content = "嘶……喊了太多遍，都咬到舌頭了。",
