  ui_story_5020_50200202_22_dialog_content = "嗯……如妳所見，可能還是妳們的戰鬥力更能派上用場。",
  ui_story_5020_50200202_23_dialog_content = "<size=45>啊啊啊——</size>",
  ui_story_5020_50200202_24_dialog_content = "別過來，都退回去！",
  ui_story_5020_50200202_25_dialog_content = "速射感知！",
