  ui_story_5020_50200202_30_dialog_content = "PlayerName，你先帶著平民往後撤。",
  ui_story_5020_50200202_31_dialog_content = "都跟我來，往這邊走！",
  ui_story_5020_50200202_32_dialog_content = "哎……是巫女？",
  ui_story_5020_50200202_33_dialog_content = "還有幾個陌生的異鄉人。",
