  ui_story_5020_50200202_35_dialog_content = "怎麼辦……他們好像不是很相信我們。",
  ui_story_5020_50200202_36_dialog_content = "生死關頭，這時候還要猶豫嗎？",
  ui_story_5020_50200202_37_dialog_content = "<size=45>哇啊！怎麼這麼多鬼！</size>",
  ui_story_5020_50200202_38_dialog_content = "咦，PlayerName大人，你們怎麼還沒跑？",
  ui_story_5020_50200202_39_dialog_content = "撤退，撤退，攤子都要被掀翻了！",
  ui_story_5020_50200202_40_dialog_content = "等等，先別走！",
  ui_story_5020_50200202_41_dialog_content = "阿桃、阿杏，我們現在需要妳們幫忙。",
  ui_story_5020_50200202_42_dialog_content = "PlayerName大人啊，有什麼事情，晚點再說！",
  ui_story_5020_50200202_43_dialog_content = "是呀！現在逃命要緊呀！",
  ui_story_5020_50200202_44_dialog_content = "妳們先冷靜，冷靜下來！",
  ui_story_5020_50200202_45_dialog_content = "妳們想不想金字招牌上又添一筆！",
  ui_story_5020_50200202_46_dialog_content = "<size=45>想！</size>",
  ui_story_5020_50200202_47_dialog_content = "想不想成為雲島最優秀的美食舖老闆！",
  ui_story_5020_50200202_48_dialog_content = "<size=45>想！</size>",
  ui_story_5020_50200202_49_dialog_content = "所以，拿出妳們......咳，平時叫賣的力氣，帶著居民先撤離到安全的地方。",
  ui_story_5020_50200202_50_dialog_content = "<anim type=Shake><size=50>跟我來！往這邊走！！！</size></anim>",
  ui_story_5020_50200202_51_dialog_content = "哇，我的耳朵……",
  ui_story_5020_50200301_1_dialog_content = "公方大人，現在主城外有幾個平時往來的商賈，說想要見您。",
  ui_story_5020_50200301_2_dialog_content = "這個時候他們居然沒有在提燈夜遊大賺一筆，來找我幹什麼？",
  ui_story_5020_50200301_3_dialog_content = "走，去見見他們。",
  ui_story_5020_50200301_4_dialog_content = "公方大人啊，請您救救我們！",
  ui_story_5020_50200301_5_dialog_content = "倒也不必行如此大禮，起來說，發生了什麼事情？",
  ui_story_5020_50200301_6_dialog_content = "哎呀，看來您還不知道，剛剛界町突然遭到鬼的襲擊。",
  ui_story_5020_50200301_7_dialog_content = "是的呀，是的呀！",
  ui_story_5020_50200301_8_dialog_content = "我們幾個攤子都被掀翻了，估計要虧損不少錢……",
  ui_story_5020_50200301_9_dialog_content = "看來今年春日祭又要白忙活囉。",
  ui_story_5020_50200301_10_dialog_content = "咳咳，都給我閉嘴，現在是說這個的時候嗎？",
  ui_story_5020_50200301_11_dialog_content = "公方大人，界町出事，我們第一時間就來向您匯報。",
  ui_story_5020_50200301_12_dialog_content = "竟有此事？",
  ui_story_5020_50200301_13_dialog_content = "是屬下失職了，衛隊此時都在城——",
  ui_story_5020_50200301_14_dialog_content = "立即派衛隊前往！",
  ui_story_5020_50200301_15_dialog_content = "要是有什麼閃失，你們幾個也別想活了。",
  ui_story_5020_50200301_16_dialog_content = "是！",
  ui_story_5020_50200301_17_dialog_content = "真是太謝謝您了！",
  ui_story_5020_50200301_18_dialog_content = "屬下的失職便是我的失職，我才應該說一聲抱歉。",
  ui_story_5020_50200301_19_dialog_content = "怎麼會呢！",
  ui_story_5020_50200301_20_dialog_content = "方才已經看見凜音大人在城中支援，疏散民眾。",
  ui_story_5020_50200301_21_dialog_content = "嗯？凜音在城中？",
  ui_story_5020_50200301_22_dialog_content = "是的呀，凜音大人應當是在籌備提燈夜遊，才能在第一時間保護我們。",
  ui_story_5020_50200301_23_dialog_content = "那颯爽英姿，令我等甚是感慨。",
  ui_story_5020_50200301_24_dialog_content = "覺得我們也應該做點什麼才對。",
  ui_story_5020_50200301_25_dialog_content = "現在想來是凜音大人還沒有來得及通知公方大人，我等就擅自前來匯報了。",
  ui_story_5020_50200301_26_dialog_content = "嗯，你們做得對。",
  ui_story_5020_50200301_27_dialog_content = "我想應當是反叛軍將鬼引至街上，想要趁機反抗，甚至不顧及黎民百姓。",
  ui_story_5020_50200301_28_dialog_content = "不必惶恐，衛隊已經出發，一定能保證大家的安全。",
  ui_story_5020_50200301_29_dialog_content = "雲島有您，真是何其幸運！",
  ui_story_5020_50200301_30_dialog_content = "那我們就不打攪您了。",
  ui_story_5020_50200301_31_dialog_content = "雲島的人民從不理解什麼是和平，他們只知道不斷索取。",
  ui_story_5020_50200301_32_dialog_content = "想要實現「她」的願望，就必須要做出一些犧牲。",
  ui_story_5020_50200301_33_dialog_content = "倒是<color=#FFB400>燭幽軍</color>還沒有動作，頗令我意外。",
  ui_story_5020_50200301_34_dialog_content = "找到薙了嗎？",
  ui_story_5020_50200301_35_dialog_content = "還沒有。",
  ui_story_5020_50200301_36_dialog_content = "<size=45>一群廢物！</size>",
  ui_story_5020_50200301_37_dialog_content = "將軍息怒。",
  ui_story_5020_50200301_38_dialog_content = "你帶鬼隊前往界町，把他們引出來。",
  ui_story_5020_50200301_39_dialog_content = "今日必須斬草除根。",
  ui_story_5020_50200301_40_dialog_content = "春日祭，也必須照常進行。",
  ui_story_5020_50200301_41_dialog_content = "沒錯。",
  ui_story_5020_50200301_42_dialog_content = "凜音有時確實和妳很像。",
  ui_story_5020_50200301_43_dialog_content = "倘若妳在，應該會很喜歡她吧。",
  ui_story_5020_50200301_44_dialog_content = "自妳走後，我把希望寄於培養新的巫女。",
  ui_story_5020_50200301_45_dialog_content = "但現在看來，毫無疑問，還是失敗了。",
  ui_story_5020_50200301_46_dialog_content = "妳終究是不一樣的。",
  ui_story_5020_50200301_47_dialog_content = "不過妳放心，答應妳的事情，我一定會做到。",
  ui_story_5020_50200301_48_dialog_content = "這是妳的願望，亦是我們的願望。",
  ui_story_5020_50200301_49_dialog_content = "<anim type=Shake><size=45>嘎——</size></anim>",
  ui_story_5020_50200301_50_dialog_content = "這也太多了！",
  ui_story_5020_50200301_51_dialog_content = "藤雲將軍這是真的打算見死不救了？",
  ui_story_5020_50200301_52_dialog_content = "速射感知——",
  ui_story_5020_50200301_53_dialog_content = "這些鬼似乎比剛剛還要棘手。",
  ui_story_5020_50200301_54_dialog_content = "集中注意力，眼下最重要的是掩護平民撤離。",
  ui_story_5020_50200301_55_dialog_content = "凜音、薇絲，再堅持一下！",
  ui_story_5020_50200302_1_dialog_content = "也不知道阿桃和阿杏那邊怎麼樣了。",
  ui_story_5020_50200302_2_dialog_content = "<size=33>PlayerName大人！</size>",
  ui_story_5020_50200302_3_dialog_content = "我好像聽見有人在叫我？",
  ui_story_5020_50200302_4_dialog_content = "嗯？我沒有聽到呀。",
  ui_story_5020_50200302_5_dialog_content = "PlayerName大人！",
  ui_story_5020_50200302_6_dialog_content = "哎，我好像也聽到了。",
  ui_story_5020_50200302_7_dialog_content = "那邊是不是有個衝過來的人影？",
  ui_story_5020_50200302_8_dialog_content = "<size=50>PlayerName大人！！！</size>",
  ui_story_5020_50200302_9_option_content = "阿桃？！",
  ui_story_5020_50200302_10_dialog_content = "妳和阿杏不是帶著平民撤離了嗎？",
  ui_story_5020_50200302_11_option_content = "阿杏？！",
  ui_story_5020_50200302_12_dialog_content = "妳和阿桃不是帶著平民撤離了嗎？",
  ui_story_5020_50200302_13_dialog_content = "PlayerName大人，我是阿桃啊！",
  ui_story_5020_50200302_14_dialog_content = "呃，真的對不起……妳們兩個長得實在是太像了。",
  ui_story_5020_50200302_15_dialog_content = "妳們怎麼回來了？阿杏和平民呢？",
  ui_story_5020_50200302_16_dialog_content = "我在這裡！",
  ui_story_5020_50200302_17_dialog_content = "妳們怎麼又帶著平民回來了？！",
  ui_story_5020_50200302_18_dialog_content = "不是的呀，你們光顧著斷後了，可是前面，前面還有鬼呀！",
  ui_story_5020_50200302_19_dialog_content = "我們被包圍了！",
  ui_story_5020_50200302_20_dialog_content = "「事到如今，唯有殺出一條道路來了！」",
  ui_story_5020_50200302_21_dialog_content = "這句話怎麼聽起來這麼耳熟？",
  ui_story_5020_50200302_22_dialog_content = "耳熟嗎？",
  ui_story_5020_50200302_23_dialog_content = "我之前翻了翻小瑤那本「雲島旅遊手冊」。",
  ui_story_5020_50200302_24_dialog_content = "這句話是裡面「當季服飾」的宣傳語。",
  ui_story_5020_50200302_25_dialog_content = "凜音，說真的，這句話不太適合妳……",
  ui_story_5020_50200302_26_dialog_content = "我覺得還滿帥氣的呀！",
  ui_story_5020_50200302_27_dialog_content = "主要是不知道為什麼……",
  ui_story_5020_50200302_28_dialog_content = "我腦子裡會出現醒山穿著雲島的武士服，一副放浪不羈的模樣。",
  ui_story_5020_50200302_29_dialog_content = "嗯……好像有畫面了。",
  ui_story_5020_50200302_30_dialog_content = "來吧，讓我們殺出一條路！",
  ui_story_5020_50200302_31_dialog_content = "兄弟們，上！",
  ui_story_5020_50200302_32_dialog_content = "衝啊！！！",
  ui_story_5020_50200302_33_dialog_content = "這......這是？",
  ui_story_5020_50200302_34_dialog_content = "這是藤雲將軍良心發現，決定來支援了？",
  ui_story_5020_50200302_35_dialog_content = "看這穿著倒是像平民。",
  ui_story_5020_50200302_36_dialog_content = "是反叛軍。",
  ui_story_5020_50200302_37_dialog_content = "我們是<color=#FFB400>燭幽軍</color>！",
  ui_story_5020_50200302_38_dialog_content = "你們是什麼人？",
  ui_story_5020_50200302_39_dialog_content = "我們是……",
  ui_story_5020_50200302_40_dialog_content = "巫女和兩個異鄉人在一起？",
  ui_story_5020_50200302_41_dialog_content = "把他們給我抓起來！",
  ui_story_5020_50200401_1_dialog_content = "<anim type=Shake>阿嚏——</anim>",
  ui_story_5020_50200401_2_dialog_content = "哼……是哪個壞傢伙在說本大俠的壞話！",
  ui_story_5020_50200401_3_dialog_content = "腿都已經蹲到麻木了，現在出去外面應該沒人了吧？",
  ui_story_5020_50200401_4_dialog_content = "嘿嘿，活動活動筋骨，好多了！",
  ui_story_5020_50200401_5_dialog_content = "<anim type=Shake>咕——</anim>",
  ui_story_5020_50200401_6_dialog_content = "這主城裡怎麼還混進鬼了？",
  ui_story_5020_50200401_7_dialog_content = "<size=45>呵哈——！</size>",
  ui_story_5020_50200401_8_dialog_content = "這臭老頭連自己的主城都守不住嗎？不會吧？",
  ui_story_5020_50200401_9_dialog_content = "害得我頭髮都亂掉了，可惡，包子頭可是很難扎的啊！",
  ui_story_5020_50200401_10_dialog_content = "不過話說回來，我現在這是在哪裡？",
  ui_story_5020_50200401_11_dialog_content = "這主城也太大了吧？而且怎麼感覺每一層都是一個樣子。",
  ui_story_5020_50200401_12_dialog_content = "這條迴廊我是不是剛剛走過？",
  ui_story_5020_50200401_13_dialog_content = "不行，我要做個標記。",
  ui_story_5020_50200401_14_dialog_content = "呼，這隻鬼還滿重的，看來伙食不錯？",
  ui_story_5020_50200401_15_dialog_content = "姿勢這樣做……手勢這樣……手指指向那邊……",
  ui_story_5020_50200401_16_dialog_content = "呼，這樣我就有方向了！",
  ui_story_5020_50200401_17_dialog_content = "噫——這個味道。",
  ui_story_5020_50200401_18_dialog_content = "出口到底在哪裡啊啊啊！我真的不想再多摸幾隻鬼了。",
  ui_story_5020_50200401_19_dialog_content = "晦氣，晦氣！回去之後一定要先洗十次澡！",
  ui_story_5020_50200401_20_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5020_50200401_21_dialog_content = "<color=#e8d9bb>咚——咚——</color>",
  ui_story_5020_50200401_22_dialog_content = "糟糕，這個聲音是不是凜音說的酉時鳴鼓？",
  ui_story_5020_50200401_23_dialog_content = "天啊！我已經在這裡繞了這麼久嗎？",
  ui_story_5020_50200401_24_dialog_content = "聰明的瑤呀，妳的腦子可要爭點氣啊！",
  ui_story_5020_50200401_25_dialog_content = "PlayerName說，可以依靠直覺。",
  ui_story_5020_50200401_26_dialog_content = "直覺，往這邊走……",
  ui_story_5020_50200401_27_dialog_content = "直覺，前面左轉……",
  ui_story_5020_50200401_28_dialog_content = "保佑保佑，下一個轉角，我一定沒走過——",
  ui_story_5020_50200401_29_dialog_content = "……",
  ui_story_5020_50200401_30_dialog_content = "PlayerName騙人，直覺根本沒有用！",
  ui_story_5020_50200401_31_dialog_content = "算了。",
  ui_story_5020_50200401_32_dialog_content = "一不做二不休，不如我也學師父從「雲守閣」跳下去算了。",
  ui_story_5020_50200401_33_dialog_content = "好，就這麼定了！",
  ui_story_5020_50200401_34_dialog_content = "唔，從這裡往下看……",
  ui_story_5020_50200401_35_dialog_content = "好像也不是很高嘛。",
  ui_story_5020_50200401_36_dialog_content = "師父應該是靠下面的櫻花樹接了一下？",
  ui_story_5020_50200401_37_dialog_content = "拜託了，櫻花樹！請接住我！",
  ui_story_5020_50200401_38_dialog_content = "……",
  ui_story_5020_50200401_39_dialog_content = "不！不行……！",
  ui_story_5020_50200401_40_dialog_content = "還是師父厲害，我做不到啊！",
  ui_story_5020_50200401_41_dialog_content = "這也太高了吧？嗚……",
  ui_story_5020_50200401_41X1_dialog_content = "一個合格的大俠從來不做沒有把握之事！",
  ui_story_5020_50200401_41X2_dialog_content = "我……我來找找有沒有什麼繩子一類的東西，能讓我順着爬下去……",
  ui_story_5020_50200401_41X3_dialog_content = "啊……房間裡唯一能藏著什麼東西的地方，大概就是……",
  ui_story_5020_50200401_41X4_dialog_content = "這個衣櫥！",
  ui_story_5020_50200401_41X5_dialog_content = "唔？",
  ui_story_5020_50200401_41X6_dialog_content = "好奇怪……剛才的感覺是……",
  ui_story_5020_50200401_41X7_dialog_content = "怎麼會莫名有一種<color=#FFB400>熟悉</color>的感覺……？",
  ui_story_5020_50200401_41X8_dialog_content = "算了不管了！先打開櫃門找到繩子再說！",
  ui_story_5020_50200401_42_dialog_content = "<color=#e8d9bb>叮鈴——</color>",
  ui_story_5020_50200401_43_dialog_content = "<color=#e8d9bb>叮鈴、叮鈴——</color>",
  ui_story_5020_50200401_44_dialog_content = "咦？！",
  ui_story_5020_50200401_45_dialog_content = "神樂鈴的聲音？",
  ui_story_5020_50200401_46_dialog_content = "<color=#e8d9bb>叮鈴——叮鈴——叮鈴、叮鈴！</color>",
  ui_story_5020_50200401_47_dialog_content = "啊，原來是掛在衣櫥中的<color=#FFB400>風鈴</color>？",
  ui_story_5020_50200401_48_dialog_content = "好奇怪，為什麼用的是神樂鈴的鈴鐺？",
  ui_story_5020_50200401_49_dialog_content = "等等，這個是……",
  ui_story_5020_50200401_50_dialog_content = "<color=#e8d9bb>十年前。</color>",
  ui_story_5020_50200401_51_dialog_content = "<color=#e8d9bb>叮鈴、叮鈴——</color>",
  ui_story_5020_50200401_52_dialog_content = "噓，小瑤乖，呆在裡面不要出聲。",
  ui_story_5020_50200401_53_dialog_content = "外面到底怎麼了？月姐姐，我好怕……",
  ui_story_5020_50200401_54_dialog_content = "可不可以不要把我一個人關起來？",
  ui_story_5020_50200401_55_dialog_content = "求求妳……",
  ui_story_5020_50200401_56_dialog_content = "在<color=#FFB400>衣櫥</color>中睡一覺，等妳醒來，一切都會結束的。",
  ui_story_5020_50200401_57_dialog_content = "月姐姐……",
  ui_story_5020_50200401_58_dialog_content = "<size=45>開門！</size>",
  ui_story_5020_50200401_58X1_dialog_content = "（有人要闖進來！）",
  ui_story_5020_50200401_58X2_dialog_content = "來人，守好大門，不能把任何不淨之物放進來！",
  ui_story_5020_50200401_58X3_dialog_content = "「即誦陰陽。此一曲，伴汝魂歸彼岸。」",
  ui_story_5020_50200401_58X4_dialog_content = "<color=#e8d9bb>叮鈴、叮鈴——</color>",
  ui_story_5020_50200401_58X5_dialog_content = "（是驅鬼的神樂鈴聲……！）",
  ui_story_5020_50200401_58X6_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_5020_50200401_59_dialog_content = "站住！你是什麼人！你不可以……",
  ui_story_5020_50200401_60_dialog_content = "<size=45>滾開！</size>",
  ui_story_5020_50200401_61_dialog_content = "（這個聲音......是師父？）",
  ui_story_5020_50200401_62_dialog_content = "阿薙？",
  ui_story_5020_50200401_63_dialog_content = "別這麼叫我，<color=#FFB400>巫· 女· 大· 人</color>。",
  ui_story_5020_50200401_64_dialog_content = "妳不配。",
  ui_story_5020_50200401_65_dialog_content = "告訴我，你為什麼勸降燭幽軍？",
  ui_story_5020_50200401_66_dialog_content = "妳承諾過我，當巫女是為了站在雲島人民這邊，為大家謀求更多利益。",
  ui_story_5020_50200401_67_dialog_content = "……",
  ui_story_5020_50200401_68_dialog_content = "我問妳為什麼！",
  ui_story_5020_50200401_69_dialog_content = "？！",
  ui_story_5020_50200401_70_dialog_content = "月！",
  ui_story_5020_50200401_71_dialog_content = "薙，妳瘋了嗎？！",
  ui_story_5020_50200401_72_dialog_content = "她可是妳親姐姐！",
  ui_story_5020_50200401_73_dialog_content = "來人，給我把薙殺了！",
  ui_story_5020_50200401_74_dialog_content = "不……！",
  ui_story_5020_50200401_75_dialog_content = "公方大人，不要這樣做……",
  ui_story_5020_50200401_76_dialog_content = "我們腳下的這條河，是順著稻田村流向城西的吧……",
  ui_story_5020_50200401_77_dialog_content = "城西山麓的園子裡……那些白色櫻花，現在一定已經開了……",
  ui_story_5020_50200401_78_dialog_content = "請不要讓血汙沾染它們的花瓣……",
  ui_story_5020_50200401_79_dialog_content = "我離開後……就讓我和那些白色櫻花睡在一起吧……",
  ui_story_5020_50200401_80_dialog_content = "請您答應我，好嗎……",
  ui_story_5020_50200401_81_dialog_content = "月，妳撐住，我現在就帶妳……",
  ui_story_5020_50200401_82_dialog_content = "「即誦……陰陽。」",
  ui_story_5020_50200401_83_dialog_content = "妳……妳要做什麼？！",
  ui_story_5020_50200401_84_dialog_content = "月！！！妳現在的身體支撐不住的！",
  ui_story_5020_50200401_85_dialog_content = "「此一曲……」",
  ui_story_5020_50200401_86_dialog_content = "「伴吾魂歸彼岸。」",
  ui_story_5020_50200401_87_dialog_content = "呃——！",
  ui_story_5020_50200401_88_dialog_content = "……",
  ui_story_5020_50200401_89_dialog_content = "…………",
  ui_story_5020_50200401_90_dialog_content = "即使是這樣，妳也要保護她嗎？",
  ui_story_5020_50200401_91_dialog_content = "來人……",
  ui_story_5020_50200401_92_dialog_content = "從今以後，在此地嚴布妖兵鬼將！",
  ui_story_5020_50200401_93_dialog_content = "把這個女人囚禁至死，絕不再給她重見天日的機會！",
  ui_story_5020_50200401_94_dialog_content = "是！",
  ui_story_5020_50200401_95_dialog_content = "剩下的……就按月說的做吧。",
  ui_story_5020_50200401_96_dialog_content = "遵命。",
  ui_story_5020_50200401_97_dialog_content = "至於妳……",
  ui_story_5020_50200401_98_dialog_content = "妳殺了她，她卻想要保護妳，妳不覺得可笑嗎？！！",
  ui_story_5020_50200401_99_dialog_content = "我不需要她的保護，我一樣能殺了你。",
  ui_story_5020_50200401_100_dialog_content = "薙，想來妳一直都沒有參透吧……",
  ui_story_5020_50200401_101_dialog_content = "參透她當年選擇站在我這邊的原因。",
  ui_story_5020_50200401_102_dialog_content = "正是因為我當年默許了她，讓她知道了一些本不該知曉的東西。",
  ui_story_5020_50200401_103_dialog_content = "「驅鬼」與「馭鬼」，僅一字之差，就能窺破雲島積年存在的法度常理。",
  ui_story_5020_50200401_104_dialog_content = "她便能理解我的處境，把雲島的和平作為畢生追求，乖乖向我交付信任。",
  ui_story_5020_50200401_105_dialog_content = "她對妳的保護，來自一個全知者對無知者的憐憫。",
  ui_story_5020_50200401_106_dialog_content = "不，絕不是這樣！",
  ui_story_5020_50200401_107_dialog_content = "不然還能是什麼呢？",
  ui_story_5020_50200401_108_dialog_content = "是妳早已與她反目的姐妹情嗎？！",
  ui_story_5020_50200401_109_dialog_content = "她明明與妳一樣大，眼神中卻總是滿含對妳的諒解……",
  ui_story_5020_50200401_110_dialog_content = "……而妳，卻殺了她！！！",
  ui_story_5020_50200401_111_dialog_content = "妳把她對雲島的所有期待，連同她的性命一起斷送了！！！",
  ui_story_5020_50200401_112_dialog_content = "妳又憑什麼活在這個世界上？！！！",
  ui_story_5020_50200401_113_dialog_content = "……",
  ui_story_5020_50200401_114_dialog_content = "<size=33>她憑什麼直到最後還要保護妳……</size>",
  ui_story_5020_50200401_115_dialog_content = "好啊，好一個冠冕堂皇的說辭！",
  ui_story_5020_50200401_116_dialog_content = "把居心叵測的「利用」美化成並不對等的「信任」與「理解」……",
  ui_story_5020_50200401_117_dialog_content = "你就是這樣騙她的嗎？！",
  ui_story_5020_50200401_118_dialog_content = "她是個聰明人。",
  ui_story_5020_50200401_119_dialog_content = "在她的心中，我們的目的一樣，都是保護這裡，所以我們之間不存在利用的關係。",
  ui_story_5020_50200401_120_dialog_content = "……也好，她給妳下的這道封印，也未嘗不是一種處刑。",
  ui_story_5020_50200401_121_dialog_content = "妳就永遠沉浸在憤怒與仇恨之中，以此度日吧。",
  ui_story_5020_50200401_122_dialog_content = "我一定會殺了你！！！",
  ui_story_5020_50200401_123_dialog_content = "妳最好還有這樣的機會。",
  ui_story_5020_50200401_124_dialog_content = "……月？",
  ui_story_5020_50200401_125_dialog_content = "是師父……<size=45>殺了巫女姐姐？！</size>",
  ui_story_5020_50200401_126_dialog_content = "師父應該不是那樣的人……",
  ui_story_5020_50200401_127_dialog_content = "你當年也是這樣利用她嗎？",
  ui_story_5020_50200401_128_dialog_content = "小姑娘，妳只不過是被遴選出來的代替品罷了。",
  ui_story_5020_50200401_129_dialog_content = "妳知道上一任巫女的下場嗎？",
  ui_story_5020_50200401_130_dialog_content = "妳閉嘴！",
  ui_story_5020_50200401_131_dialog_content = "來人，把她拿下！",
  ui_story_5020_50200401_132_dialog_content = "不……這裡面一定有什麼誤會。",
  ui_story_5020_50200401_133_dialog_content = "嘶，頭好痛。",
  ui_story_5020_50200401_134_dialog_content = "我得盡快和PlayerName會合，把這件事情告訴他們！",
  ui_story_5020_50200501_1_dialog_content = "喂！放開我們啊！有話不能好好說嗎？",
  ui_story_5020_50200501_2_dialog_content = "就是啊！一定有什麼誤會！",
  ui_story_5020_50200501_3_dialog_content = "……",
  ui_story_5020_50200501_4_dialog_content = "到這裡就暫時安全了。",
  ui_story_5020_50200501_5_dialog_content = "去把平民安置好。",
  ui_story_5020_50200501_6_dialog_content = "是！",
  ui_story_5020_50200501_7_dialog_content = "至於那幾個吵鬧了一路的傢伙……",
  ui_story_5020_50200501_8_dialog_content = "綁到柱子上去吧。",
  ui_story_5020_50200501_9_dialog_content = "什麼？！",
  ui_story_5020_50200501_10_dialog_content = "是！",
  ui_story_5020_50200501_11_dialog_content = "別亂動！老實點！",
  ui_story_5020_50200501_12_dialog_content = "嘁……這些傢伙……",
  ui_story_5020_50200501_13_dialog_content = "等一下，我不明白！",
  ui_story_5020_50200501_14_dialog_content = "你們在保護平民，我們也在保護平民！大家的立場不是一致的嗎？",
  ui_story_5020_50200501_15_dialog_content = "當然不是。",
  ui_story_5020_50200501_16_dialog_content = "你們站在巫女身邊，勢必與吾等形同水火。",
  ui_story_5020_50200501_17_dialog_content = "巫女？巫女又怎麼……",
  ui_story_5020_50200501_18_dialog_content = "我知道了。",
  ui_story_5020_50200501_19_dialog_content = "沒猜錯的話，雨森也是你們之中的一員，對吧？",
  ui_story_5020_50200501_20_dialog_content = "巫女，搞清楚狀況。",
  ui_story_5020_50200501_21_dialog_content = "現在還輪不到妳來審問我們。",
  ui_story_5020_50200501_22_dialog_content = "呵呵，我確實沒有搞清楚狀況。",
  ui_story_5020_50200501_23_dialog_content = "或許你們應該自我介紹一下？",
  ui_story_5020_50200501_24_dialog_content = "所謂的燭幽軍，究竟是什麼……",
  ui_story_5020_50200501_25_dialog_content = "哈哈哈哈，真有意思。",
  ui_story_5020_50200501_26_dialog_content = "沒想到會有一天，雲島的巫女連「燭幽軍」都沒聽說過。",
  ui_story_5020_50200501_27_dialog_content = "再過幾代乾脆把「雲島」也給忘了吧。",
  ui_story_5020_50200501_28_dialog_content = "反正對妳們來說，這些無足輕重。",
  ui_story_5020_50200501_29_dialog_content = "巫女只要舒舒服服地躲在主城裡，討好妳們的「公方大人」就夠了。",
  ui_story_5020_50200501_30_dialog_content = "……",
  ui_story_5020_50200501_31_dialog_content = "幹嘛要說得那麼過分？",
  ui_story_5020_50200501_32_dialog_content = "凜音一直在保護江富城的大家，你們也看見了吧！",
  ui_story_5020_50200501_33_dialog_content = "保護？收起那些冠冕堂皇的漂亮話吧。",
  ui_story_5020_50200501_34_dialog_content = "不過是家養的貓咬死了家養的耗子而已。",
  ui_story_5020_50200501_35_dialog_content = "這不叫「保護」，叫「表演」。",
  ui_story_5020_50200501_36_dialog_content = "「表演」？什麼意思……",
  ui_story_5020_50200501_37_dialog_content = "我問你們，這滿城的惡鬼是怎麼來的？",
  ui_story_5020_50200501_38_dialog_content = "<color=#e8d9bb>………………</color>",
  ui_story_5020_50200501_39_dialog_content = "巫女，妳最懂陰陽衍變的道理，來給大家講講。",
  ui_story_5020_50200501_40_dialog_content = "……極陰時，冤魂不渡，鬼形現出。",
  ui_story_5020_50200501_41_dialog_content = "那妳說，「極陰」是怎麼出現的？平白無故嗎？",
  ui_story_5020_50200501_42_dialog_content = "……",
  ui_story_5020_50200501_43_dialog_content = "我來告訴妳，是<color=#FFB400>人為</color>的。",
  ui_story_5020_50200501_44_dialog_content = "這雲島上自古有三件<color=#FFB400>靈器</color>。",
  ui_story_5020_50200501_45_dialog_content = "極陽者，斬鬼劍「<color=#FFB400>天雲斬</color>」，如今下落不明。",
  ui_story_5020_50200501_46_dialog_content = "陰陽調和者，勾玉「<color=#FFB400>斥鬼凌人</color>」，在我們燭幽軍手裡。",
  ui_story_5020_50200501_47_dialog_content = "而極陰者「<color=#FFB400>雲照鏡</color>」，始終為將軍所控。",
  ui_story_5020_50200501_48_dialog_content = "是當時將軍從凜音手裡搶回去的鏡子……",
  ui_story_5020_50200501_49_dialog_content = "「陰雲蔽日，照地府入人間。」",
  ui_story_5020_50200501_50_dialog_content = "造成如今這惡鬼橫行的局面，唯有「<color=#FFB400>雲照鏡</color>」可以做到。",
  ui_story_5020_50200501_51_dialog_content = "這幕後的主使是誰，哼，你們心知肚明！",
  ui_story_5020_50200501_52_dialog_content = "……其實，我們也有同樣的猜測。",
  ui_story_5020_50200501_53_dialog_content = "但有件事我沒想明白。",
  ui_story_5020_50200501_54_dialog_content = "如果藤雲將軍在操控鬼，那他為什麼要培養祓除鬼怪的巫女？",
  ui_story_5020_50200501_55_dialog_content = "我說了，不過是一場「表演」。",
  ui_story_5020_50200501_56_dialog_content = "鬼來幫他實現征服。而巫女，幫他籠絡人心。",
  ui_story_5020_50200501_57_dialog_content = "籠絡人心？",
  ui_story_5020_50200501_58_dialog_content = "將軍馭鬼，讓鬼一步步成為雲島人心中最深切的恐懼。",
  ui_story_5020_50200501_59_dialog_content = "但只靠恐懼無法統治雲島，那些善施統御的傢伙最清楚這一點。",
  ui_story_5020_50200501_60_dialog_content = "於是他培養了巫女，站在民眾面前對抗這股恐懼。",
  ui_story_5020_50200501_61_dialog_content = "民眾依賴於巫女，巫女聽命於將軍，這就是他想像中的統御之道。",
  ui_story_5020_50200501_62_dialog_content = "只可惜他想的太簡單了。",
  ui_story_5020_50200501_63_dialog_content = "雲島人不是傻子，不會被一齣雙簧的戲碼給騙住。",
  ui_story_5020_50200501_64_dialog_content = "你們巫女號稱能夠調和陰陽、祓除鬼怪，這麼多代過去了，鬼災可曾見絲毫緩解？",
  ui_story_5020_50200501_65_dialog_content = "……",
  ui_story_5020_50200501_66_dialog_content = "我們沒忘記，這地方從來不叫作「江富」。",
  ui_story_5020_50200501_67_dialog_content = "無論他們修建了多高的城堡，無論他們帶來了多少的金銀。",
  ui_story_5020_50200501_68_dialog_content = "入侵者永遠是入侵者。",
  ui_story_5020_50200501_69_dialog_content = "真正守護雲島的，只有燭幽軍。",
  ui_story_5020_50200501_70_dialog_content = "因為只有我們生長於這片土地。",
  ui_story_5020_50200501_71_dialog_content = "入侵者？本島的人在你們眼中是這樣的嗎……",
  ui_story_5020_50200501_72_dialog_content = "當然，你們沒聽過雲島的歷史嗎？",
  ui_story_5020_50200501_73_dialog_content = "也對，你們去哪裡聽呢。",
  ui_story_5020_50200501_74_dialog_content = "（之前倒是聽阿杏阿桃講過一點……）",
  ui_story_5020_50200501_75_dialog_content = "（但燭幽軍口中的歷史，也許有所不同。）",
  ui_story_5020_50200501_76_dialog_content = "對不起，我們是外鄉人，沒有聽過。",
  ui_story_5020_50200501_77_dialog_content = "我講給你們聽吧，就當是突發的一點善心。",
  ui_story_5020_50200501_78_dialog_content = "很多年前，在本島武士還沒踏足雲島的時候，這裡是個比現在更美的地方。",
  ui_story_5020_50200501_79_dialog_content = "島上資源富足，沒有任何爭端，唯一的威脅來自偶爾出現於世的鬼怪。",
  ui_story_5020_50200501_80_dialog_content = "燭幽軍自那時誕生，為守護雲島的和平與鬼對抗。",
  ui_story_5020_50200501_81_dialog_content = "然而最終毀滅和平的不是鬼，是人。",
  ui_story_5020_50200501_82_dialog_content = "本島派來了第一位將軍，那些貪婪的人早就想吞下嘴邊的肥肉。",
  ui_story_5020_50200501_83_dialog_content = "燭幽軍沒有經歷過戰爭，但也拼死抵抗。",
  ui_story_5020_50200501_84_dialog_content = "將軍連戰連捷，卻遲遲無法將雲島徹底吞併。",
  ui_story_5020_50200501_85_dialog_content = "然後他們想出了最惡毒的戰術。將軍設法馭鬼，把那些非人的怪物攪入戰局。",
  ui_story_5020_50200501_86_dialog_content = "在戰爭年代，孤魂野鬼是雲島上最不缺的東西。",
  ui_story_5020_50200501_87_dialog_content = "惡鬼徹底擊潰了燭幽軍的抵抗，雲島就此淪陷。將軍在海岸邊建立江富城來宣告統治。",
  ui_story_5020_50200501_88_dialog_content = "燭幽軍的殘部只能隱於地下，把這份仇記在心裡，世代傳承下去。",
  ui_story_5020_50200501_89_dialog_content = "我們在戰爭中學習，等待一個機會，取回雲島失去的一切。",
  ui_story_5020_50200501_90_dialog_content = "（原來雲島爭端的原貌是這樣嗎……）",
  ui_story_5020_50200501_91_dialog_content = "（隱藏在人與鬼的對抗背後，其實是人與人的戰爭……）",
  ui_story_5020_50200501_92_dialog_content = "這個機會……",
  ui_story_5020_50200501_93_dialog_content = "也許就快來了。",
  ui_story_5020_50200501_94_dialog_content = "老大，平民安置好了。",
  ui_story_5020_50200501_95_dialog_content = "我們接下來……",
  ui_story_5020_50200501_96_dialog_content = "好。去那邊說。",
  ui_story_5020_50200501_97_dialog_content = "……",
  ui_story_5020_50200501_98_dialog_content = "你們覺得，他說的事情是真的嗎？",
  ui_story_5020_50200501_99_dialog_content = "我也不知道……他說了好多，我還沒消化掉……",
  ui_story_5020_50200501_100_dialog_content = "我一直以為，我在遵照一個簡單的宗旨行事。",
  ui_story_5020_50200501_101_dialog_content = "聽養父的話，守護江富城百姓。",
  ui_story_5020_50200501_102_dialog_content = "但現在看來……",
  ui_story_5020_50200501_103_dialog_content = "也許這兩點是矛盾的。",
  ui_story_5020_50200501_104_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5020_50200501_105_dialog_content = "我所做的，只不過是「表演」嗎？",
  ui_story_5020_50200501_106_dialog_content = "他......他們說的話也未必可信吧？",
  ui_story_5020_50200501_107_dialog_content = "畢竟是不分青紅皂白把我們綁起來的傢伙。",
  ui_story_5020_50200501_108_dialog_content = "PlayerName，你說呢？",
  ui_story_5020_50200501_109_dialog_content = "你怎麼心不在焉的樣子？",
  ui_story_5020_50200501_110_dialog_content = "噓——",
  ui_story_5020_50200501_111_dialog_content = "我在偷聽他們說話……",
  ui_story_5020_50200501_112_dialog_content = "偷聽？！",
  ui_story_5020_50200501_113_dialog_content = "好有意思！我也想聽我也想聽！",
  ui_story_5020_50200501_114_dialog_content = "好，妳靠近一點。",
  ui_story_5020_50200501_115_dialog_content = "嗯嗯。",
  ui_story_5020_50200501_116_dialog_content = "老大，現在我們沒地方可去了。",
  ui_story_5020_50200501_117_dialog_content = "滿城都是鬼，聯絡不上其他地方的兄弟……",
  ui_story_5020_50200501_118_dialog_content = "知道了。我們哪都不去，就守在這裡。",
  ui_story_5020_50200501_119_dialog_content = "您說雨森大人救出了統領。",
  ui_story_5020_50200501_120_dialog_content = "她們……會來支援我們的吧？",
  ui_story_5020_50200501_121_dialog_content = "有「冥土幽刀」在，再多的鬼也沒什麼可怕！",
  ui_story_5020_50200501_122_dialog_content = "（果然，他們和雨森是一夥的！）",
  ui_story_5020_50200501_123_dialog_content = "（嗯，而且雨森的地位聽起來還滿高。）",
  ui_story_5020_50200501_124_dialog_content = "你小子聽好了，燭幽軍作戰，可從來不仰仗支援。",
  ui_story_5020_50200501_125_dialog_content = "哪怕只剩你一個人，你也要戰鬥下去。",
  ui_story_5020_50200501_126_dialog_content = "您的意思是，她們……",
  ui_story_5020_50200501_127_dialog_content = "統領和雨森大人有她們的事情要做。",
  ui_story_5020_50200501_128_dialog_content = "我操心不著，你更操心不著。",
  ui_story_5020_50200501_129_dialog_content = "（對喔，也不知道雨森怎麼樣了……）",
  ui_story_5020_50200501_130_dialog_content = "（放心吧，她那麼厲害，肯定沒事的。）",
  ui_story_5020_50200501_131_dialog_content = "……",
  ui_story_5020_50200501_132_dialog_content = "老大，大家聽說統領獲救了都很興奮。",
  ui_story_5020_50200501_133_dialog_content = "但是……統領到現在都沒露面。",
  ui_story_5020_50200501_134_dialog_content = "不少兄弟在嘀咕，這件事說不定是假的。",
  ui_story_5020_50200501_135_dialog_content = "或者說……",
  ui_story_5020_50200501_136_dialog_content = "十年過去了，統領已經把燭幽軍忘了……",
  ui_story_5020_50200501_137_dialog_content = "……",
  ui_story_5020_50200501_138_dialog_content = "夠了。",
  ui_story_5020_50200501_139_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_5020_50200501_140_dialog_content = "（？！！）",
  ui_story_5020_50200501_141_dialog_content = "怎麼了？",
  ui_story_5020_50200501_142_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_5020_50200501_143_dialog_content = "（是牆壁背後的聲音！好近！）",
  ui_story_5020_50200501_144_dialog_content = "做好戰鬥準備！",
  ui_story_5020_50200501_145_dialog_content = "<color=#e8d9bb>砰！！！</color>",
  ui_story_5020_50200501_146_dialog_content = "<anim type=Shake><size=45>嘎——！</size></anim>",
  ui_story_5020_50200501_147_dialog_content = "這麼快就找上門來了……",
  ui_story_5020_50200501_148_dialog_content = "也是，遲早的事情。",
  ui_story_5020_50200501_149_dialog_content = "燭幽軍的兄弟們！",
  ui_story_5020_50200501_150_dialog_content = "在！！！",
  ui_story_5020_50200501_151_dialog_content = "給我打起精神！",
  ui_story_5020_50200501_152_dialog_content = "把這幫妖魔鬼怪送回地府！",
  ui_story_5020_50200501_153_dialog_content = "糟了，鬼找過來了！",
  ui_story_5020_50200501_154_dialog_content = "是啊！怎麼辦！",
  ui_story_5020_50200501_155_dialog_content = "我們被綁在這什麼都做不了啊！",
  ui_story_5020_50200501_156_dialog_content = "<size=45>喂！！！放開我們！！！</size>",
  ui_story_5020_50200501_157_dialog_content = "<size=45>我們可以幫上忙的！！！</size>",
  ui_story_5020_50200501_158_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5020_50200501_159_dialog_content = "呃，聽不到嗎？",
  ui_story_5020_50200501_160_dialog_content = "用你的感應能力試試呢？",
  ui_story_5020_50200501_161_dialog_content = "說得對！我……",
  ui_story_5020_50200501_162_dialog_content = "<color=#e8d9bb>砰！！！</color>",
  ui_story_5020_50200501_163_dialog_content = "<anim type=Shake>咕——</anim>",
  ui_story_5020_50200501_164_dialog_content = "糟了！偏偏這個時候……",
  ui_story_5020_50200501_165_dialog_content = "它越來越近了！",
  ui_story_5020_50200501_166_dialog_content = "我現在叫燭幽軍的人還……來得及嗎？",
  ui_story_5020_50200501_167_dialog_content = "你說呢？？？",
  ui_story_5020_50200501_168_dialog_content = "呵呵，不過是找人幫我們鬆綁而已。",
  ui_story_5020_50200501_169_dialog_content = "燭幽軍不願意，就請它代勞吧。",
  ui_story_5020_50200501_170_dialog_content = "它？你說的該不會是……",
  ui_story_5020_50200501_170X1_dialog_content = "<anim type=Shake>咕——</anim>",
  ui_story_5020_50200501_170X2_dialog_content = "讓鬼來斬斷繩索嗎？它會先把我斬成兩段的吧！！！",
  ui_story_5020_50200501_170X3_dialog_content = "所以你最好稍微躲一下。",
  ui_story_5020_50200501_171_dialog_content = "<color=#e8d9bb>啪——！</color>",
  ui_story_5020_50200501_172_dialog_content = "<anim type=Shake>呃啊——</anim>",
  ui_story_5020_50200501_173_dialog_content = "你看。",
  ui_story_5020_50200501_174_dialog_content = "有的時候，鬼比人要聽話。",
  ui_story_5020_50200502_1_dialog_content = "老大！所有通路都有敵人！",
  ui_story_5020_50200502_2_dialog_content = "我們被包圍了！",
  ui_story_5020_50200502_3_dialog_content = "剛發起襲擊就形成了包圍……",
  ui_story_5020_50200502_4_dialog_content = "如此乾淨利落的佈局，背後肯定有問題。",
  ui_story_5020_50200502_5_dialog_content = "老大，你的意思是……",
  ui_story_5020_50200502_6_dialog_content = "我們燭幽軍和鬼戰鬥了這麼多年，哪次有被逼進角落？",
  ui_story_5020_50200502_7_dialog_content = "鬼的感知能力不強。它們會被戰鬥吸引，但絕對沒有這麼快。",
  ui_story_5020_50200502_8_dialog_content = "要想形成現在的局面，需要先知曉位置、再組織包圍，最後發動突襲。",
  ui_story_5020_50200502_9_dialog_content = "有人在背後指揮它們。",
  ui_story_5020_50200502_10_dialog_content = "恐怕……是那位將軍坐不住了。",
  ui_story_5020_50200502_11_dialog_content = "老大，那我們怎麼辦？",
  ui_story_5020_50200502_12_dialog_content = "先穩住局面，看看有沒有方向可以突破。",
  ui_story_5020_50200502_13_dialog_content = "至少，要把平民送出江富城……",
  ui_story_5020_50200502_14_dialog_content = "（喂，你們幾個，小心背後！）",
  ui_story_5020_50200502_15_dialog_content = "？ ！ ！",
  ui_story_5020_50200502_16_dialog_content = "什麼人在說話？！",
  ui_story_5020_50200502_17_dialog_content = "（是我，剛才被你綁在柱子上的外鄉人。）",
  ui_story_5020_50200502_18_dialog_content = "你脫身了？",
  ui_story_5020_50200502_19_dialog_content = "既然要說話就別鬼鬼祟祟的！給老子現身！",
  ui_story_5020_50200502_20_dialog_content = "（呃……其實我並不在你旁邊。）",
  ui_story_5020_50200502_21_dialog_content = "（這是一種叫做「心靈感應」的溝通方式。）",
  ui_story_5020_50200502_22_dialog_content = "什麼意思？",
  ui_story_5020_50200502_23_dialog_content = "（就是說……哎算了，這個不重要。）",
  ui_story_5020_50200502_24_dialog_content = "（重要的是，我們可以幫忙。）",
  ui_story_5020_50200502_25_dialog_content = "幫忙？哼，燭幽軍還不至於讓幾個階下囚幫忙。",
  ui_story_5020_50200502_26_dialog_content = "（你們現在狀況這麼糟，就不要再嘴硬了吧。）",
  ui_story_5020_50200502_27_dialog_content = "你……",
  ui_story_5020_50200502_28_dialog_content = "（鬼馬上會從你們右側的街道出現。）",
  ui_story_5020_50200502_29_dialog_content = "右邊？",
  ui_story_5020_50200502_30_dialog_content = "<anim type=Shake>咕——</anim>",
  ui_story_5020_50200502_31_dialog_content = "還真是這樣……",
  ui_story_5020_50200502_32_dialog_content = "兄弟們，右邊，上！",
  ui_story_5020_50200502_33_dialog_content = "（喔，其實左邊也有。）",
  ui_story_5020_50200502_34_dialog_content = "<anim type=Shake>咕——</anim>",
  ui_story_5020_50200502_35_dialog_content = "你……剛才幹嘛不說？！",
  ui_story_5020_50200502_36_dialog_content = "（因為這邊交給我們就行了。）",
  ui_story_5020_50200502_37_dialog_content = "不用謝不用謝～",
  ui_story_5020_50200502_38_dialog_content = "為什麼要幫忙？",
  ui_story_5020_50200502_39_dialog_content = "有巫女在，將軍不會為難你們。",
  ui_story_5020_50200502_40_dialog_content = "（說來話長，其實我們和將軍之間也有點「小矛盾」……）",
  ui_story_5020_50200502_41_dialog_content = "矛盾？",
  ui_story_5020_50200502_42_dialog_content = "（就是打過一架吧……其他的我也說不清楚。）",
  ui_story_5020_50200502_43_dialog_content = "（聽了你的故事我才發現，雲島的紛爭比想像中更複雜。）",
  ui_story_5020_50200502_44_dialog_content = "（我們身為局外人沒法找到自己的立場。）",
  ui_story_5020_50200502_45_dialog_content = "（但無論怎麼說，人與鬼對抗肯定是沒錯的。）",
  ui_story_5020_50200502_46_dialog_content = "（至少現在，我們必須並肩作戰！）",
  ui_story_5020_50200502_47_dialog_content = "……",
  ui_story_5020_50200502_48_dialog_content = "好。",
  ui_story_5020_50200502_49_dialog_content = "我暫時相信，你也是與鬼為敵的戰士。",
  ui_story_5020_50200502_50_dialog_content = "凜音！妳沒事吧？",
  ui_story_5020_50200502_51_dialog_content = "……嗯，謝謝。",
  ui_story_5020_50200502_52_dialog_content = "妳有哪裡不舒服嗎？",
  ui_story_5020_50200502_53_dialog_content = "往常的話，這些鬼早就被妳消滅了。",
  ui_story_5020_50200502_54_dialog_content = "……",
  ui_story_5020_50200502_55_dialog_content = "對不起，讓妳擔心了。",
  ui_story_5020_50200502_56_dialog_content = "我只是有點不在狀態。",
  ui_story_5020_50200502_57_dialog_content = "是因為燭幽軍的話嗎？",
  ui_story_5020_50200502_58_dialog_content = "……嗯。",
  ui_story_5020_50200502_59_dialog_content = "我忘不了「表演」這個詞。",
  ui_story_5020_50200502_60_dialog_content = "只要它還在腦海中打轉，我的手就使不上力氣。",
  ui_story_5020_50200502_61_dialog_content = "我……也許失去了戰鬥的理由。",
  ui_story_5020_50200502_62_dialog_content = "我還以為，在主城裡面對將軍的時候妳已經想清楚了……",
  ui_story_5020_50200502_63_dialog_content = "當時只是憤怒和不理解。",
  ui_story_5020_50200502_64_dialog_content = "現在，我好像理解了。",
  ui_story_5020_50200502_65_dialog_content = "理解了什麼？",
  ui_story_5020_50200502_66_dialog_content = "他從沒想要我驅鬼。",
  ui_story_5020_50200502_67_dialog_content = "他要的只是我穿上巫女的衣服，在百姓面前跳一支美麗的「舞」。",
  ui_story_5020_50200502_68_dialog_content = "我一直活在那樣的「表演」裡，以巫女的身分自居。",
  ui_story_5020_50200502_69_dialog_content = "但現在，我突然被置於舞台之外，從別人口中聽聞了自己的故事。",
  ui_story_5020_50200502_70_dialog_content = "我……不知道自己該扮演哪個身分。",
  ui_story_5020_50200502_71_dialog_content = "做我應該做的那個人，還是做我自以為的那個人……",
  ui_story_5020_50200601_1_dialog_content = "所有平民，跟我來。",
  ui_story_5020_50200601_2_dialog_content = "怎麼又要走了，這是準備去哪裡？",
  ui_story_5020_50200601_3_dialog_content = "離界町越來越遠了哦！",
  ui_story_5020_50200601_4_dialog_content = "我們要離開江富城。",
  ui_story_5020_50200601_5_dialog_content = "欸？？？為什麼？",
  ui_story_5020_50200601_6_dialog_content = "荒郊野嶺的怎麼做生意啊！",
  ui_story_5020_50200601_7_dialog_content = "惡鬼在「他」的命令下湧入城裡，現在城外反而更安全。",
  ui_story_5020_50200601_8_dialog_content = "喔……",
  ui_story_5020_50200601_9_dialog_content = "阿桃，他是在說將軍招來了這些鬼嗎？",
  ui_story_5020_50200601_10_dialog_content = "好像是的。但是為什麼呢？",
  ui_story_5020_50200601_11_dialog_content = "將軍要殺掉所有人嗎……",
  ui_story_5020_50200601_12_dialog_content = "我覺得不至於……他可是江富城的統治者啊。",
  ui_story_5020_50200601_13_dialog_content = "如果把大家都殺掉了，他該去統治誰呢？",
  ui_story_5020_50200601_14_dialog_content = "說不定……統治鬼？",
  ui_story_5020_50200601_15_dialog_content = "不要說這種嚇人的話啊！",
  ui_story_5020_50200601_16_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_5020_50200601_17_dialog_content = "？！",
  ui_story_5020_50200601_18_dialog_content = "<size=45>前面那支隊伍，給我停下！</size>",
  ui_story_5020_50200601_19_dialog_content = "！！！",
  ui_story_5020_50200601_20_dialog_content = "糟了……",
  ui_story_5020_50200601_21_dialog_content = "深更半夜的，你們要去哪裡？",
  ui_story_5020_50200601_21X1_dialog_content = "<color=#e8d9bb>江富城街道，屋頂</color>",
  ui_story_5020_50200601_21X2_dialog_content = "好......好高！妳們慢一點！",
  ui_story_5020_50200601_21X3_dialog_content = "忍耐一下，目前只有屋頂才有快捷又安全的路了。",
  ui_story_5020_50200601_22_dialog_content = "PlayerName，前面沒路了！",
  ui_story_5020_50200601_23_dialog_content = "現在怎麼辦？",
  ui_story_5020_50200601_24_dialog_content = "看來只能那樣了……",
  ui_story_5020_50200601_25_dialog_content = "往下跳嗎？",
  ui_story_5020_50200601_26_dialog_content = "嗯……",
  ui_story_5020_50200601_27_dialog_content = "成交！",
  ui_story_5020_50200601_28_dialog_content = "喂！妳們就這樣跳下去了？",
  ui_story_5020_50200601_29_dialog_content = "沒……沒有人準備幫我一下嗎……",
  ui_story_5020_50200601_30_dialog_content = "快點啊，PlayerName！",
  ui_story_5020_50200601_31_dialog_content = "等到被鬼抓住就不能跳了喔！",
  ui_story_5020_50200601_32_dialog_content = "我知道了！",
  ui_story_5020_50200601_33_dialog_content = "呼……",
  ui_story_5020_50200601_34_dialog_content = "來吧！！！",
  ui_story_5020_50200601_35_dialog_content = "<anim type=Shake><size=45>啊——啊——啊——！</size></anim>",
  ui_story_5020_50200601_36_dialog_content = "<color=#e8d9bb>砰。</color>",
  ui_story_5020_50200601_37_dialog_content = "我……好像還活著？",
  ui_story_5020_50200601_38_dialog_content = "閉著眼睛跳可沒法安全落地喔。",
  ui_story_5020_50200601_39_dialog_content = "還好我接住你了。",
  ui_story_5020_50200601_40_dialog_content = "薇絲，有妳真是太……",
  ui_story_5020_50200601_41_dialog_content = "麻煩你先站在地上再說話。",
  ui_story_5020_50200601_42_dialog_content = "喔……",
  ui_story_5020_50200601_43_dialog_content = "那接下來……",
  ui_story_5020_50200601_44_dialog_content = "我們總算又見面了，異鄉人。",
  ui_story_5020_50200601_45_dialog_content = "原來你們一直躲在房頂上。",
  ui_story_5020_50200601_46_dialog_content = "嗯……",
  ui_story_5020_50200601_47_dialog_content = "我也知道我們之間最好保持一點距離。",
  ui_story_5020_50200601_48_dialog_content = "但現在已經沒有留出這段距離的餘地了……",
  ui_story_5020_50200601_49_dialog_content = "所以你是在向我們求援？",
  ui_story_5020_50200601_50_dialog_content = "求援？都這種時候了還要說些傲慢的話……",
  ui_story_5020_50200601_51_dialog_content = "當然沒有麻煩各位的意思。",
  ui_story_5020_50200601_52_dialog_content = "我只是要提醒一下，馬上會有鬼從這個屋頂追過來。",
  ui_story_5020_50200601_53_dialog_content = "你們要是不想抵抗，我們就接著逃跑了。",
  ui_story_5020_50200601_54_dialog_content = "你們要是還有點鬥志，想繼續與鬼戰鬥，我們也願意幫忙。",
  ui_story_5020_50200601_55_dialog_content = "哼，伶牙俐齒的傢伙。",
  ui_story_5020_50200601_56_dialog_content = "希望你在戰場上也能有這樣的氣勢。",
  ui_story_5020_50200601_57_dialog_content = "你馬上就會見識到的！",
  ui_story_5020_50200601_58_dialog_content = "不過我事先說好，讓那傢伙離遠點。",
  ui_story_5020_50200601_59_dialog_content = "我們不想與巫女並肩戰鬥。",
  ui_story_5020_50200601_60_dialog_content = "……",
  ui_story_5020_50200601_61_dialog_content = "呃……其實凜音她……",
  ui_story_5020_50200601_62_dialog_content = "那好啊。",
  ui_story_5020_50200601_63_dialog_content = "既然諸位大人願意挺身而出。",
  ui_story_5020_50200601_64_dialog_content = "凜音感激不盡。",
  ui_story_5020_50200601_65_dialog_content = "妳……",
  ui_story_5020_50200601_66_dialog_content = "<color=#e8d9bb>轟——————！</color>",
  ui_story_5020_50200601_67_dialog_content = "<anim type=Shake>咕——</anim>",
  ui_story_5020_50200601_68_dialog_content = "嘁……算了。",
  ui_story_5020_50200601_69_dialog_content = "燭幽軍！準備戰鬥！",
  ui_story_5020_50200602_1_dialog_content = "還有多少？",
  ui_story_5020_50200602_2_dialog_content = "快了……周圍的能量在減弱……",
  ui_story_5020_50200602_3_dialog_content = "薇絲！",
  ui_story_5020_50200602_4_dialog_content = "明白！",
  ui_story_5020_50200602_5_dialog_content = "怎麼樣，你們還撐得住嗎？",
  ui_story_5020_50200602_6_dialog_content = "在跟誰說話呢小鬼。",
  ui_story_5020_50200602_7_dialog_content = "先管好你自己吧。",
  ui_story_5020_50200602_8_dialog_content = "你的身體狀況很差，我能感知到。",
  ui_story_5020_50200602_9_dialog_content = "如果你真有那麼厲害，應該能感知到我的精神狀況很好。",
  ui_story_5020_50200602_10_dialog_content = "要是身體倒下了，精神還有什麼用？",
  ui_story_5020_50200602_11_dialog_content = "你看我們正面對的這些傢伙，身體都沒有了也仍在戰鬥。",
  ui_story_5020_50200602_12_dialog_content = "只因它們還留有一絲魂魄。",
  ui_story_5020_50200602_13_dialog_content = "在我們雲島的觀念裡，精神永遠比肉體重要。",
  ui_story_5020_50200602_14_dialog_content = "燭幽軍可以失敗，可以戰死，但絕不能放棄抵抗。",
  ui_story_5020_50200602_15_dialog_content = "你們的覺悟真的有點可怕……",
  ui_story_5020_50200602_16_dialog_content = "不過這次還用不著。",
  ui_story_5020_50200602_17_dialog_content = "馬上就結束了。",
  ui_story_5020_50200602_18_dialog_content = "哼……",
  ui_story_5020_50200602_19_dialog_content = "這是最後一個。",
  ui_story_5020_50200602_20_dialog_content = "呼——好累！",
  ui_story_5020_50200602_21_dialog_content = "小鬼，我們接下來往哪邊走？",
  ui_story_5020_50200602_22_dialog_content = "得趕緊出城跟平民隊伍會合。",
  ui_story_5020_50200602_23_dialog_content = "等一下，先不要放鬆！",
  ui_story_5020_50200602_24_dialog_content = "有一隊人正在靠近……",
  ui_story_5020_50200602_25_dialog_content = "人？什麼人？",
  ui_story_5020_50200602_26_dialog_content = "<color=#e8d9bb>噔……噔……</color>",
  ui_story_5020_50200602_27_dialog_content = "沒猜錯的話應該與你們有些矛盾……",
  ui_story_5020_50200602_28_dialog_content = "<color=#e8d9bb>噔……噔……噔……</color>",
  ui_story_5020_50200602_29_dialog_content = "叛軍餘黨。",
  ui_story_5020_50200602_30_dialog_content = "禍亂江富。",
  ui_story_5020_50200602_31_dialog_content = "今日……",
  ui_story_5020_50200602_32_dialog_content = "<size=40>必將爾等一網成擒。</size>",
  ui_story_5020_50200602_33_dialog_content = "武士？這麼多？！",
  ui_story_5020_50200602_34_dialog_content = "哼，家犬總喜歡結隊而行。",
  ui_story_5020_50200602_35_dialog_content = "只會讓吠叫聲更大而已，根本沒什麼可怕的。",
  ui_story_5020_50200602_36_dialog_content = "兄弟們，拿起武器！",
  ui_story_5020_50200602_37_dialog_content = "等一下！",
  ui_story_5020_50200602_38_dialog_content = "他們後面……還有其他人……",
  ui_story_5020_50200602_39_dialog_content = "其他人？",
  ui_story_5020_50200602_40_dialog_content = "哇，薇絲！PlayerName！",
  ui_story_5020_50200602_41_dialog_content = "你們沒事吧！",
  ui_story_5020_50200602_42_dialog_content = "阿杏和阿桃？",
  ui_story_5020_50200602_43_dialog_content = "妳們不是和平民一起……",
  ui_story_5020_50200602_44_dialog_content = "爸爸……",
  ui_story_5020_50200602_45_dialog_content = "噓。",
  ui_story_5020_50200602_46_dialog_content = "你們……你們這些卑鄙之徒！",
  ui_story_5020_50200602_47_dialog_content = "連平民都不放過嗎！",
  ui_story_5020_50200602_48_dialog_content = "這是我要說的。",
  ui_story_5020_50200602_49_dialog_content = "燭幽軍惡徒，劫持庶民去往城外。",
  ui_story_5020_50200602_50_dialog_content = "這是爾等的第一樁罪。",
  ui_story_5020_50200602_51_dialog_content = "劫持？哼，好一個劫持！",
  ui_story_5020_50200602_52_dialog_content = "惡鬼襲街的時候不見你們露面，現在假惺惺地裝什麼英雄！",
  ui_story_5020_50200602_53_dialog_content = "忤逆將軍、私自結黨。",
  ui_story_5020_50200602_54_dialog_content = "這是爾等的第二樁罪。",
  ui_story_5020_50200602_55_dialog_content = "你……",
  ui_story_5020_50200602_56_dialog_content = "而妄圖傾覆綱紀，無所不用其極。",
  ui_story_5020_50200602_57_dialog_content = "為此觸碰禁忌，招致這滿城惡鬼。",
  ui_story_5020_50200602_58_dialog_content = "這是爾等的第三樁罪。",
  ui_story_5020_50200602_59_dialog_content = "他說什麼？！",
  ui_story_5020_50200602_60_dialog_content = "燭幽軍不是一直在與鬼對抗嗎？",
  ui_story_5020_50200602_61_dialog_content = "嗯……",
  ui_story_5020_50200602_62_dialog_content = "我想，他是說給平民們聽的。",
  ui_story_5020_50200602_63_dialog_content = "武士大人，這些話是真的嗎？",
  ui_story_5020_50200602_64_dialog_content = "燭幽軍招來的惡鬼？",
  ui_story_5020_50200602_65_dialog_content = "但剛才他們救了大家……",
  ui_story_5020_50200602_66_dialog_content = "誰知道真相是什麼樣的！",
  ui_story_5020_50200602_67_dialog_content = "是啊，我們這種無權無勢的普通人，哪裡管得了那麼多……",
  ui_story_5020_50200602_68_dialog_content = "誰護我們周全，我們就信誰好了……",
  ui_story_5020_50200602_69_dialog_content = "……",
  ui_story_5020_50200602_70_dialog_content = "我以為武士至少會有道德底線。",
  ui_story_5020_50200602_71_dialog_content = "但現在看來，是我高看你們了。",
  ui_story_5020_50200602_72_dialog_content = "用這種卑劣的方式顛倒黑白，你以為能騙過所有人嗎？",
  ui_story_5020_50200602_73_dialog_content = "都睜大眼睛看看吧！總有人會看見！",
  ui_story_5020_50200602_74_dialog_content = "是誰為對抗惡鬼戰死。",
  ui_story_5020_50200602_75_dialog_content = "又是誰躲在圍牆之後，終日高枕無憂！",
  ui_story_5020_50200602_76_dialog_content = "大家只會看到叛賊於今日伏法。",
  ui_story_5020_50200602_77_dialog_content = "送庶民回主城。接下來的戰鬥，不能傷及無辜。",
  ui_story_5020_50200602_78_dialog_content = "哎唷又要打起來了……",
  ui_story_5020_50200602_79_dialog_content = "快走，我們快走……",
  ui_story_5020_50200602_80_dialog_content = "這是什麼世道啊。",
  ui_story_5020_50200602_81_dialog_content = "喂！那邊還有我們兩個朋友，不要傷害到他們啊！",
  ui_story_5020_50200602_82_dialog_content = "薇絲！PlayerName！快跟我們一起走吧……",
  ui_story_5020_50200602_83_dialog_content = "接下來好像是雲島人內部的爭端了，我們該怎麼辦？",
  ui_story_5020_50200602_84_dialog_content = "等一下，沒有這麼簡單。",
  ui_story_5020_50200602_85_dialog_content = "我們先靜觀其變……",
  ui_story_5020_50200602_86_dialog_content = "行，不傷及平民這點上，我算你還有點良心。",
  ui_story_5020_50200602_87_dialog_content = "守護江富城和平本就是吾等的職責。",
  ui_story_5020_50200602_88_dialog_content = "是嗎？我還以為是我們燭幽軍的職責。",
  ui_story_5020_50200602_89_dialog_content = "如果爾等果真心向和平，就該放棄負嵎頑抗，依法領罪。",
  ui_story_5020_50200602_90_dialog_content = "<size=45>哈哈哈哈哈哈！</size>",
  ui_story_5020_50200602_91_dialog_content = "將軍的法律可管不著老子！",
  ui_story_5020_50200602_92_dialog_content = "冥頑不化。爾等自食惡果吧。",
  ui_story_5020_50200602_93_dialog_content = "哼，正有此意！",
  ui_story_5020_50200602_94_dialog_content = "<color=#e8d9bb>叮鈴——</color>",
  ui_story_5020_50200602_95_dialog_content = "？ ！ ！",
  ui_story_5020_50200602_96_dialog_content = "！！！",
  ui_story_5020_50200602_97_dialog_content = "抱歉打攪了你們的興致。",
  ui_story_5020_50200602_98_dialog_content = "但我有幾句話想問。",
  ui_story_5020_50200602_99_dialog_content = "巫女大人？！",
  ui_story_5020_50200602_100_dialog_content = "原來您也被叛軍劫持了！",
  ui_story_5020_50200602_101_dialog_content = "恕吾等怠慢，屬下這就……",
  ui_story_5020_50200602_102_dialog_content = "你們說，燭幽軍招來了惡鬼。",
  ui_story_5020_50200602_103_dialog_content = "證據是什麼？",
  ui_story_5020_50200602_104_dialog_content = "……證據？",
  ui_story_5020_50200602_105_dialog_content = "何時、何地，憑藉什麼東西？",
  ui_story_5020_50200602_106_dialog_content = "……",
  ui_story_5020_50200602_107_dialog_content = "巫女大人，屬下地位卑微，無權知曉來龍去脈。",
  ui_story_5020_50200602_108_dialog_content = "但請您放心，一切皆是將軍大人所言。",
  ui_story_5020_50200602_109_dialog_content = "哦？",
  ui_story_5020_50200602_110_dialog_content = "你們保證，是出自將軍之口，而非他人刻意編造？",
  ui_story_5020_50200602_111_dialog_content = "是。屬下保證。",
  ui_story_5020_50200602_112_dialog_content = "……",
  ui_story_5020_50200602_113_dialog_content = "呵呵，我知道了。",
  ui_story_5020_50200602_114_dialog_content = "多謝將軍，幫我明確了自己的立場。",
  ui_story_5020_50200602_115_dialog_content = "您理解就好。",
  ui_story_5020_50200602_116_dialog_content = "請站在吾等身後，不要被接下來的戰鬥所傷。",
  ui_story_5020_50200602_117_dialog_content = "<color=#e8d9bb>叮鈴——</color>",
  ui_story_5020_50200602_118_dialog_content = "不必了。",
  ui_story_5020_50200602_119_dialog_content = "這就是我的立場。",
  ui_story_5020_50200602_120_dialog_content = "……",
  ui_story_5020_50200602_121_dialog_content = "巫女大人，攔在吾等面前是何含義，您清楚吧。",
  ui_story_5020_50200602_122_dialog_content = "不清楚。",
  ui_story_5020_50200602_123_dialog_content = "我只是原地不動而已。你要去哪裡、要做什麼，與我無關。",
  ui_story_5020_50200602_124_dialog_content = "您站在戰場中央，即是與吾等為敵。",
  ui_story_5020_50200602_125_dialog_content = "或者說，與將軍為敵。",
  ui_story_5020_50200602_126_dialog_content = "我是巫女，巫女從不與任何人為敵。",
  ui_story_5020_50200602_127_dialog_content = "只有可能是別人與我為敵。",
  ui_story_5020_50200602_128_dialog_content = "您此言是在怪罪將軍？",
  ui_story_5020_50200602_129_dialog_content = "沒有怪罪，而是我終於理解了他。",
  ui_story_5020_50200602_130_dialog_content = "多虧你們替他傳達的那句——「燭幽軍招來了惡鬼」。",
  ui_story_5020_50200602_131_dialog_content = "……",
  ui_story_5020_50200602_132_dialog_content = "在「雲守閣」裡見到鬼的時候，我不理解。",
  ui_story_5020_50200602_133_dialog_content = "「雲照鏡」意外令鬼重生的時候，我不理解。",
  ui_story_5020_50200602_134_dialog_content = "將軍的言行不一讓我混亂，但我不知道他為什麼要這樣做。",
  ui_story_5020_50200602_135_dialog_content = "直到你們出現，我終於得到了答案。",
  ui_story_5020_50200602_136_dialog_content = "巫女與鬼，世代為敵的兩者，對將軍而言其實是一樣的。",
  ui_story_5020_50200602_137_dialog_content = "沒有敵我之分，只不過是互為陰陽的一對武器。",
  ui_story_5020_50200602_138_dialog_content = "當需要武力的時候，他用鬼來鎮壓敵人。",
  ui_story_5020_50200602_139_dialog_content = "當籠絡民心的時候，他再搬出巫女，將矛頭對向鬼。",
  ui_story_5020_50200602_140_dialog_content = "巫女大人，很多事情您還無法理解。",
  ui_story_5020_50200602_141_dialog_content = "嗯……所以我選擇相信我能理解的東西。",
  ui_story_5020_50200602_142_dialog_content = "相信我時至今日所學的一切，相信我身為巫女的信條。",
  ui_story_5020_50200602_143_dialog_content = "我，只與鬼為敵。",
  ui_story_5020_50200602_144_dialog_content = "……",
  ui_story_5020_50200602_145_dialog_content = "同樣，這也是我站在此地的理由。",
  ui_story_5020_50200602_146_dialog_content = "你身後的那些武士。",
  ui_story_5020_50200602_147_dialog_content = "<color=#FFB400>他們並非生者</color>，對吧？",
  ui_story_5020_50200602_148_dialog_content = "……",
  ui_story_5020_50200602_149_dialog_content = "既然如此，那便無需多言了。",
  ui_story_5020_50200602_150_dialog_content = "……",
  ui_story_5020_50200602_151_dialog_content = "<color=#e8d9bb>叮鈴——</color>",
  ui_story_5020_50200602_152_dialog_content = "「即誦陰陽。此一曲，伴汝魂歸彼岸。」",
  ui_story_5020_50200701_1_dialog_content = "（我們看著黑壓壓的鬼武士靠近，壓迫感令每個人麻木。）",
  ui_story_5020_50200701_2_dialog_content = "（就像是一個浪頭掀起，正待在最高處劈頭落下。）",
  ui_story_5020_50200701_3_dialog_content = "（而凜音站在街道中間，單薄的身影一橫，竟獨自將這股浪潮截斷。）",
  ui_story_5020_50200701_4_dialog_content = "（她面前是陰曹地府，背後卻是人間。）",
  ui_story_5020_50200701_5_dialog_content = "哎呀……",
  ui_story_5020_50200701_6_dialog_content = "燭幽軍的各位，不是厭惡與巫女共同作戰嗎？",
  ui_story_5020_50200701_7_dialog_content = "……",
  ui_story_5020_50200701_8_dialog_content = "我們更厭惡被巫女保護。",
  ui_story_5020_50200701_9_dialog_content = "呵呵，真是可惜了。",
  ui_story_5020_50200701_10_dialog_content = "你們都參與戰鬥，誰來欣賞我的「表演」呢。",
  ui_story_5020_50200701_11_dialog_content = "「表演」這個詞我怎麼聽著有點刺耳。",
  ui_story_5020_50200701_12_dialog_content = "這個詞是你教給我的。",
  ui_story_5020_50200701_13_dialog_content = "能讓妳記恨這麼久，看來我那句話說得很精闢。",
  ui_story_5020_50200701_14_dialog_content = "嗯，沒錯。",
  ui_story_5020_50200701_15_dialog_content = "身為巫女的敵人，你比我自己更懂巫女。",
  ui_story_5020_50200701_16_dialog_content = "等妳像我一樣懂的時候，妳也該厭惡自己的身分了。",
  ui_story_5020_50200701_17_dialog_content = "呵呵，不要妄下推斷。",
  ui_story_5020_50200701_18_dialog_content = "「表演」這個詞很尖銳，但我並不討厭。",
  ui_story_5020_50200701_19_dialog_content = "妳甘願做一個提線木偶？",
  ui_story_5020_50200701_20_dialog_content = "你們在乎是誰提著木偶頭上的線。",
  ui_story_5020_50200701_21_dialog_content = "而我只在乎木偶有沒有演好它的戲。",
  ui_story_5020_50200701_22_dialog_content = "在妳之前的木偶，從沒有演好過。",
  ui_story_5020_50200701_23_dialog_content = "是嗎，那你覺得我能不能演好呢？",
  ui_story_5020_50200701_24_dialog_content = "……",
  ui_story_5020_50200701_25_dialog_content = "所以，這就是你們執著於刺殺巫女的理由嗎？",
  ui_story_5020_50200701_26_dialog_content = "小雨森可給我添過不少麻煩。",
  ui_story_5020_50200701_27_dialog_content = "小……",
  ui_story_5020_50200701_28_dialog_content = "妳最好對雨森大人放尊敬點。",
  ui_story_5020_50200701_29_dialog_content = "哦？",
  ui_story_5020_50200701_30_dialog_content = "我看小雨森刺殺總是失敗，還以為她早就顏面掃地了呢。",
  ui_story_5020_50200701_31_dialog_content = "妳……",
  ui_story_5020_50200701_32_dialog_content = "她在燭幽軍裡是什麼身分？",
  ui_story_5020_50200701_33_dialog_content = "雨森大人是我們統領的徒弟。",
  ui_story_5020_50200701_34_dialog_content = "統領被困的這些年裡，燭幽軍奉她為首。",
  ui_story_5020_50200701_35_dialog_content = "原來是這樣。小雨森話太少了，問她什麼都不說。",
  ui_story_5020_50200701_36_dialog_content = "對了，你們的統領就是「冥土幽刀」吧？",
  ui_story_5020_50200701_37_dialog_content = "妳見過統領了？",
  ui_story_5020_50200701_38_dialog_content = "嗯，還和她交了一次手。",
  ui_story_5020_50200701_39_dialog_content = "能與將軍對抗的人……果然強得可怕。",
  ui_story_5020_50200701_40_dialog_content = "接替她的位置，小雨森也太辛苦了。",
  ui_story_5020_50200701_41_dialog_content = "雨森大人和統領很像。統領要做的事情，她都做得很好。",
  ui_story_5020_50200701_42_dialog_content = "甚至……比統領更好。",
  ui_story_5020_50200701_43_dialog_content = "是嗎？",
  ui_story_5020_50200701_44_dialog_content = "刺殺巫女這件事上，她好像做得一般。",
  ui_story_5020_50200701_45_dialog_content = "難道你們統領做得更差？",
  ui_story_5020_50200701_46_dialog_content = "……",
  ui_story_5020_50200701_47_dialog_content = "答案妳自己知道。",
  ui_story_5020_50200701_48_dialog_content = "想想妳為什麼會成為巫女。",
  ui_story_5020_50200701_49_dialog_content = "……",
  ui_story_5020_50200701_50_dialog_content = "呵呵，原來如此。",
  ui_story_5020_50200701_51_dialog_content = "這麼說來，刺殺巫女對你們來說也是場「表演」吧。",
  ui_story_5020_50200701_52_dialog_content = "別拿我們和妳相提並論。",
  ui_story_5020_50200701_53_dialog_content = "但此刻我們正在並肩作戰，不是嗎？",
  ui_story_5020_50200701_54_dialog_content = "你已經自己走上了舞台。",
  ui_story_5020_50200702_1_dialog_content = "背後又有鬼武士來了！",
  ui_story_5020_50200702_2_dialog_content = "這些傢伙還有援軍！",
  ui_story_5020_50200702_3_dialog_content = "……知道了。",
  ui_story_5020_50200702_4_dialog_content = "再這麼打下去燭幽軍要撐不住了。",
  ui_story_5020_50200702_5_dialog_content = "老大，我們該怎麼辦？",
  ui_story_5020_50200702_6_dialog_content = "……",
  ui_story_5020_50200702_7_dialog_content = "這一仗我們恐怕贏不了。",
  ui_story_5020_50200702_8_dialog_content = "老大……",
  ui_story_5020_50200702_9_dialog_content = "難道真的已經……",
  ui_story_5020_50200702_10_dialog_content = "但還沒到束手就擒的時候。",
  ui_story_5020_50200702_11_dialog_content = "我們……也許能打贏<color=#FFB400>下一仗</color>。",
  ui_story_5020_50200702_12_dialog_content = "下一仗？",
  ui_story_5020_50200702_13_dialog_content = "這一仗要是輸了，哪還有下一仗……",
  ui_story_5020_50200702_14_dialog_content = "我想試試，我們從沒試過的方法。",
  ui_story_5020_50200702_15_dialog_content = "異鄉人小鬼！！！給我過來！！！",
  ui_story_5020_50200702_16_dialog_content = "欸？我就在你旁邊，不用喊那麼大聲……",
  ui_story_5020_50200702_17_dialog_content = "我問你，現在這種局面，你有信心逃走嗎？",
  ui_story_5020_50200702_18_dialog_content = "逃走？",
  ui_story_5020_50200702_19_dialog_content = "這麼多鬼武士在糾纏，脫不開身啊……",
  ui_story_5020_50200702_20_dialog_content = "如果燭幽軍幫你們殿後的話，逃得掉嗎？",
  ui_story_5020_50200702_21_dialog_content = "欸？",
  ui_story_5020_50200702_22_dialog_content = "聽好了。現在，你們兩個異鄉人立刻帶著巫女逃走。",
  ui_story_5020_50200702_23_dialog_content = "燭幽軍會掩護你們，但堅持不了太久。",
  ui_story_5020_50200702_24_dialog_content = "最好把你那點奇怪本領全拿出來。",
  ui_story_5020_50200702_25_dialog_content = "聽懂了嗎？",
  ui_story_5020_50200702_26_dialog_content = "聽是聽懂了，但為什麼……",
  ui_story_5020_50200702_27_dialog_content = "為什麼要這樣做？",
  ui_story_5020_50200702_28_dialog_content = "……",
  ui_story_5020_50200702_29_dialog_content = "巫女，妳的「表演」應該給更多人看看。",
  ui_story_5020_50200702_30_dialog_content = "……",
  ui_story_5020_50200702_31_dialog_content = "憑現在的燭幽軍不足以跟將軍抗衡。",
  ui_story_5020_50200702_32_dialog_content = "但如果是你們，也許還有一線希望。",
  ui_story_5020_50200702_33_dialog_content = "既然敗局已定，比起哭著認命，老子更願意豪賭一把。",
  ui_story_5020_50200702_34_dialog_content = "兄弟們！給我把戰線頂住！一步都不許退！",
  ui_story_5020_50200702_35_dialog_content = "我們走了，那你們怎麼辦？",
  ui_story_5020_50200702_36_dialog_content = "<size=45>趕緊給老子滾！</size>",
  ui_story_5020_50200702_37_dialog_content = "……",
  ui_story_5020_50200702_38_dialog_content = "走吧，PlayerName。",
  ui_story_5020_50200702_39_dialog_content = "他們已經做出了選擇。",
  ui_story_5020_50200702_40_dialog_content = "你欠燭幽軍一個人情，小鬼。",
  ui_story_5020_50200702_41_dialog_content = "要記著還。",
  ui_story_5020_50200702_42_dialog_content = "哇！！！",
  ui_story_5020_50200702_43_dialog_content = "好大的一面鼓啊！",
  ui_story_5020_50200702_44_dialog_content = "好大！",
  ui_story_5020_50200702_45_dialog_content = "爸爸，這是做什麼用的？",
  ui_story_5020_50200702_46_dialog_content = "是為春日祭開幕準備的。",
  ui_story_5020_50200702_47_dialog_content = "鼓手把它敲響，整個江富城都能聽見，大家也就知道春日祭正式開始了。",
  ui_story_5020_50200702_48_dialog_content = "喔！",
  ui_story_5020_50200702_49_dialog_content = "那它為什麼被丟在這裡，鼓手呢？",
  ui_story_5020_50200702_50_dialog_content = "鬼來了，鼓手當然跑了。",
  ui_story_5020_50200702_51_dialog_content = "好可惜……",
  ui_story_5020_50200702_52_dialog_content = "那我可以玩玩它嗎？",
  ui_story_5020_50200702_53_dialog_content = "現在就算了，先跟著隊伍走吧。",
  ui_story_5020_50200702_54_dialog_content = "等明天，爸爸再帶妳來玩。",
  ui_story_5020_50200702_55_dialog_content = "喂，阿桃。",
  ui_story_5020_50200702_56_dialog_content = "嗯。",
  ui_story_5020_50200702_57_dialog_content = "這面鼓，現在沒有主人對吧？",
  ui_story_5020_50200702_58_dialog_content = "很明顯是無主的物件。",
  ui_story_5020_50200702_59_dialog_content = "如果把它搬回去……",
  ui_story_5020_50200702_60_dialog_content = "放在攤子旁邊……",
  ui_story_5020_50200702_61_dialog_content = "一定能招攬到更多客人吧！",
  ui_story_5020_50200702_62_dialog_content = "<size=40>抓住那幾個人！</size>",
  ui_story_5020_50200702_63_dialog_content = "<size=40>快！快！</size>",
  ui_story_5020_50200702_64_dialog_content = "嗯？怎麼了？",
  ui_story_5020_50200702_65_dialog_content = "好像……",
  ui_story_5020_50200702_66_dialog_content = "有什麼人在朝着我們衝過來！",
  ui_story_5020_50200702_67_dialog_content = "阿杏！阿桃！快幫幫忙！",
  ui_story_5020_50200702_68_dialog_content = "哎唷……",
  ui_story_5020_50200702_69_dialog_content = "啊呀……",
  ui_story_5020_50200702_70_dialog_content = "啊，對不起，沒剎住車。",
  ui_story_5020_50200702_71_dialog_content = "不過現在狀況真的很糟糕，有一隊武士在追殺我們！",
  ui_story_5020_50200702_72_dialog_content = "武士？追殺？",
  ui_story_5020_50200702_73_dialog_content = "PlayerName大人你做了什麼？",
  ui_story_5020_50200702_74_dialog_content = "沒時間解釋了，有沒有地方可以讓我們躲一下？",
  ui_story_5020_50200702_75_dialog_content = "快！他們馬上就追上來了！",
  ui_story_5020_50200702_76_dialog_content = "躲一下？太突然了吧！",
  ui_story_5020_50200702_77_dialog_content = "就算你這麼說也……",
  ui_story_5020_50200702_78_dialog_content = "<color=#e8d9bb>………………</color>",
  ui_story_5020_50200702_79_dialog_content = "<size=40>欸——</size>",
  ui_story_5020_50200702_80_dialog_content = "PlayerName，稍微過去一點……",
  ui_story_5020_50200702_81_dialog_content = "好擠！",
  ui_story_5020_50200702_82_dialog_content = "我也想，但是……這裡面是圓的啊！",
  ui_story_5020_50200702_83_dialog_content = "身體會一直往下滑！",
  ui_story_5020_50200702_84_dialog_content = "哎……真虧你能想出躲在太鼓裡這種點子……",
  ui_story_5020_50200702_85_dialog_content = "是阿杏和阿桃的主意！與我無關！",
  ui_story_5020_50200702_86_dialog_content = "呵呵，倒是也沒有更好的選擇。",
  ui_story_5020_50200702_87_dialog_content = "先忍一忍吧。",
  ui_story_5020_50200702_88_dialog_content = "嗯……",
  ui_story_5020_50200702_89_dialog_content = "噓，他們來了。",
  ui_story_5020_50200702_90_dialog_content = "妳們，有沒有見過三個神色慌張的人。",
  ui_story_5020_50200702_91_dialog_content = "其中一個穿著紅色的巫女服，很顯眼。",
  ui_story_5020_50200702_92_dialog_content = "嗯？為什麼一定要是三個人？",
  ui_story_5020_50200702_93_dialog_content = "穿著藍色的衣服可以嗎？",
  ui_story_5020_50200702_94_dialog_content = "……妳們只要回答我「見過」還是「沒見過」就夠了。",
  ui_story_5020_50200702_95_dialog_content = "沒見過！",
  ui_story_5020_50200702_96_dialog_content = "行，我知道了。",
  ui_story_5020_50200702_97_dialog_content = "（呼……這下應該……）",
  ui_story_5020_50200702_98_dialog_content = "不過，妳們兩個站在這幹嘛？",
  ui_story_5020_50200702_99_dialog_content = "為什麼不跟上隊伍？",
  ui_story_5020_50200702_100_dialog_content = "啊，我們是……那個……",
  ui_story_5020_50200702_101_dialog_content = "因為這個鼓……",
  ui_story_5020_50200702_102_dialog_content = "鼓？",
  ui_story_5020_50200702_103_dialog_content = "（！！！）",
  ui_story_5020_50200702_104_dialog_content = "鼓有什麼問題嗎？",
  ui_story_5020_50200702_105_dialog_content = "（糟了……）",
  ui_story_5020_50200702_106_dialog_content = "對！因為這個鼓！",
  ui_story_5020_50200702_107_dialog_content = "我們是敲鼓的鼓手！",
  ui_story_5020_50200702_108_dialog_content = "沒……沒錯！為春日祭開幕做準備！",
  ui_story_5020_50200702_109_dialog_content = "鼓手？",
  ui_story_5020_50200702_110_dialog_content = "這麼小的個子也能敲鼓嗎？",
  ui_story_5020_50200702_111_dialog_content = "雖然個子小，但是……",
  ui_story_5020_50200702_112_dialog_content = "我們可以兩個人一起敲！",
  ui_story_5020_50200702_113_dialog_content = "兩個人一起？",
  ui_story_5020_50200702_114_dialog_content = "有點意思，妳們敲給我看看。",
  ui_story_5020_50200702_115_dialog_content = "真……真的要敲？",
  ui_story_5020_50200702_116_dialog_content = "不然算了，武士大人，要追不上隊伍了……",
  ui_story_5020_50200702_117_dialog_content = "沒事，後面還有其他武士，路上沒有危險。",
  ui_story_5020_50200702_118_dialog_content = "來吧，敲兩下看看。",
  ui_story_5020_50200702_119_dialog_content = "（……）",
  ui_story_5020_50200702_120_dialog_content = "（阿杏阿桃，你們不會真的要……）",
  ui_story_5020_50200702_121_dialog_content = "<size=30>對不起了，PlayerName大人……</size>",
  ui_story_5020_50200702_122_dialog_content = "<size=30>忍一下哦……</size>",
  ui_story_5020_50200702_123_dialog_content = "（等等！難道就沒有……）",
  ui_story_5020_50200702_124_dialog_content = "嘿！",
  ui_story_5020_50200702_125_dialog_content = "<color=#e8d9bb><size=50>咚！！！</size></color>",
  ui_story_5020_50200702_126_dialog_content = "嘿！",
  ui_story_5020_50200702_127_dialog_content = "<color=#e8d9bb><size=50>咚！！！</size></color>",
  ui_story_5020_50200702_128_dialog_content = "可以啊，妳們兩個。有點本事！",
  ui_story_5020_50200702_129_dialog_content = "<anim type=Shake>哈……哈哈……</anim>",
  ui_story_5020_50200702_130_dialog_content = "武士大人謬讚了……",
  ui_story_5020_50200702_131_dialog_content = "挺好的。將軍大人說春日祭照常舉辦，你們正好把太鼓搬去主城吧。",
  ui_story_5020_50200702_132_dialog_content = "路上如果看到我說的那三個人，大聲呼喊就行。",
  ui_story_5020_50200702_133_dialog_content = "成交！",
  ui_story_5020_50200702_134_dialog_content = "呃……",
  ui_story_5020_50200702_135_dialog_content = "PlayerName大人……",
  ui_story_5020_50200702_136_dialog_content = "你們還好嗎……",
  ui_story_5020_50200702_137_dialog_content = "<size=45>怎麼可能好啊！！！</size>",
  ui_story_5020_50200702_138_dialog_content = "<size=45>耳朵都快聽不見了好嗎！！！</size>",
  ui_story_5020_50200702_139_dialog_content = "這不是聽見了……",
  ui_story_5020_50200702_140_dialog_content = "這是靠著感應能力啊！耳朵並沒有工作！",
  ui_story_5020_50200702_141_dialog_content = "PlayerName，我看到你張嘴了。你在說話嗎？",
  ui_story_5020_50200702_142_dialog_content = "抱歉！真的非常抱歉！",
  ui_story_5020_50200702_143_dialog_content = "呼……",
  ui_story_5020_50200702_144_dialog_content = "算了，也是沒辦法的事情。",
  ui_story_5020_50200702_145_dialog_content = "噓！",
  ui_story_5020_50200702_146_dialog_content = "又有武士過來了！",
  ui_story_5020_50200702_147_dialog_content = "怎麼沒完沒了的……",
  ui_story_5020_50200702_148_dialog_content = "那現在怎麼辦？",
  ui_story_5020_50200702_149_dialog_content = "只能繼續躲在太鼓裡了！",
  ui_story_5020_50200702_150_dialog_content = "我和阿杏把你們運到人少的地方，到時候再脫身就容易得多。",
  ui_story_5020_50200702_151_dialog_content = "好像……是一種方法……",
  ui_story_5020_50200702_152_dialog_content = "對吧！",
  ui_story_5020_50200702_153_dialog_content = "我們總能想到好方法！",
  ui_story_5020_50200702_154_dialog_content = "不過我先說好。",
  ui_story_5020_50200702_155_dialog_content = "鼓，妳們不許再敲了！",
  ui_story_5020_50200702_156_dialog_content = "不敲了！絕對不敲了！",
  ui_story_5020_50200702_157_dialog_content = "（燭幽軍掩護我們逃走，是期待我們去做什麼呢？）",
  ui_story_5020_50200702_158_dialog_content = "（他們……不知道怎麼樣了……）",
  ui_story_5020_50200702_159_dialog_content = "投降！我們投降！",
  ui_story_5020_50200702_160_dialog_content = "喂！聽到沒有！不打了！投降！",
  ui_story_5020_50200702_161_dialog_content = "我們想通了！將軍大人說得對！",
  ui_story_5020_50200702_162_dialog_content = "燭幽軍有罪！得伏法！",
  ui_story_5020_50200702_163_dialog_content = "……",
  ui_story_5020_50200702_164_dialog_content = "武士大人，您身為將軍的爪牙……哦不，利刃！",
  ui_story_5020_50200702_165_dialog_content = "應該會依法辦事吧？",
  ui_story_5020_50200702_166_dialog_content = "你們，為什麼要捨身放走巫女。",
  ui_story_5020_50200702_167_dialog_content = "她自己逃走的，關我們什麼事。",
  ui_story_5020_50200702_168_dialog_content = "……敵人的敵人未必是朋友。",
  ui_story_5020_50200702_169_dialog_content = "她是將軍大人的養女，翻不起什麼波瀾。",
  ui_story_5020_50200702_170_dialog_content = "那最好。趕緊讓事情結束吧，和平的日子要來囉！",
  ui_story_5020_50200702_171_dialog_content = "……",
  ui_story_5020_50200702_172_dialog_content = "把他們綁起來，押去主城。",
  ui_story_5020_50200801_1_dialog_content = "手·折·紅·花·贈·伊·人——",
  ui_story_5020_50200801_2_dialog_content = "眉·前·花·落·玉·上·雪。",
  ui_story_5020_50200801_3_dialog_content = "師父，您接下來準備做什麼？",
  ui_story_5020_50200801_4_dialog_content = "呀，還跟著我呢？",
  ui_story_5020_50200801_5_dialog_content = "都這麼久了，累不累啊。",
  ui_story_5020_50200801_6_dialog_content = "我可以幫上師父的忙。",
  ui_story_5020_50200801_7_dialog_content = "幫什麼忙啊，用不著。",
  ui_story_5020_50200801_8_dialog_content = "我就是去做點私人的事情。",
  ui_story_5020_50200801_9_dialog_content = "等忙完了會來找妳的，乖。",
  ui_story_5020_50200801_10_dialog_content = "……",
  ui_story_5020_50200801_11_dialog_content = "師父，當年是您孤身離開，自己……",
  ui_story_5020_50200801_12_dialog_content = "那種事不會再發生了。",
  ui_story_5020_50200801_13_dialog_content = "我長大了，我可以替您分擔。",
  ui_story_5020_50200801_14_dialog_content = "而且……不止是我，還有整個燭幽軍。",
  ui_story_5020_50200801_15_dialog_content = "當年啊，這是過去了多少年……",
  ui_story_5020_50200801_16_dialog_content = "十年。",
  ui_story_5020_50200801_17_dialog_content = "十年！哈哈哈，真是夠久的。",
  ui_story_5020_50200801_18_dialog_content = "我記憶裡的妳還沒有打刀高，總怕一陣風吹過來妳就不見了。",
  ui_story_5020_50200801_19_dialog_content = "現在長大了，本事厲害了，想甩都甩不掉妳。",
  ui_story_5020_50200801_20_dialog_content = "師父……",
  ui_story_5020_50200801_21_dialog_content = "但是啊，妳的腦袋好像沒有變聰明。",
  ui_story_5020_50200801_22_dialog_content = "「替我分擔」，妳想分擔什麼？",
  ui_story_5020_50200801_23_dialog_content = "分擔您一直想做的事情。",
  ui_story_5020_50200801_24_dialog_content = "讓江富城回到它真正的主人手裡。",
  ui_story_5020_50200801_25_dialog_content = "哈哈哈哈，我明白了。",
  ui_story_5020_50200801_26_dialog_content = "這就是妳一定要救我出來的理由。",
  ui_story_5020_50200801_27_dialog_content = "妳期待我來解決一切。",
  ui_story_5020_50200801_28_dialog_content = "期待我站在城樓下大刀一揮，就能帶著妳們把將軍老頭擺平，是嗎？",
  ui_story_5020_50200801_29_dialog_content = "師父，您一定可以……",
  ui_story_5020_50200801_30_dialog_content = "夠了。",
  ui_story_5020_50200801_31_dialog_content = "小徒弟，妳對我抱有太多不切實際的幻想。",
  ui_story_5020_50200801_32_dialog_content = "我不是什麼聖人，而且差得很遠。",
  ui_story_5020_50200801_33_dialog_content = "別拿妳們的期許來綁架我，讓我扮演所謂的「正義」。",
  ui_story_5020_50200801_34_dialog_content = "……",
  ui_story_5020_50200801_35_dialog_content = "但是，您一直做的事情不就是……",
  ui_story_5020_50200801_36_dialog_content = "對，我一直在與將軍對抗。",
  ui_story_5020_50200801_37_dialog_content = "但那是因為我想這麼做，而不是為了什麼天下蒼生、黎民百姓。",
  ui_story_5020_50200801_38_dialog_content = "我背負不起那麼多東西。",
  ui_story_5020_50200801_39_dialog_content = "……",
  ui_story_5020_50200801_40_dialog_content = "其實我一直覺得，我不適合當燭幽軍的統領。",
  ui_story_5020_50200801_41_dialog_content = "那時候只是沒人打得過我，稀里糊塗地把我捧了上去。",
  ui_story_5020_50200801_42_dialog_content = "這個統領讓我當得很煩，也當得很累。",
  ui_story_5020_50200801_43_dialog_content = "我還是喜歡自己一個人衝進主城的感覺。",
  ui_story_5020_50200801_44_dialog_content = "看著滿城武士層層戒備，但是沒人能攔得住我。",
  ui_story_5020_50200801_45_dialog_content = "對，我就該這樣，想做什麼就做什麼。",
  ui_story_5020_50200801_46_dialog_content = "妳呢，徒弟。",
  ui_story_5020_50200801_47_dialog_content = "妳到底想做什麼？",
  ui_story_5020_50200801_48_dialog_content = "我……",
  ui_story_5020_50200801_49_dialog_content = "沒想過嗎？",
  ui_story_5020_50200801_50_dialog_content = "……",
  ui_story_5020_50200801_51_dialog_content = "我一直想成為師父的樣子。",
  ui_story_5020_50200801_52_dialog_content = "哦？",
  ui_story_5020_50200801_53_dialog_content = "燭幽軍的大家把我當作您的接班人。",
  ui_story_5020_50200801_54_dialog_content = "我……一直按照大家的期望去做，試著填補您不在的空缺。",
  ui_story_5020_50200801_55_dialog_content = "不過那個空缺對我來說太大，無論怎麼努力都無法做到完美。",
  ui_story_5020_50200801_56_dialog_content = "……",
  ui_story_5020_50200801_57_dialog_content = "所以……師父從封印之地出來的時候，我終於鬆了口氣。",
  ui_story_5020_50200801_58_dialog_content = "我以為我的使命完成了。",
  ui_story_5020_50200801_59_dialog_content = "傻徒弟，妳並不是我的代替。",
  ui_story_5020_50200801_60_dialog_content = "燭幽軍在我手下進退維谷，但它靠著妳度過了十年。",
  ui_story_5020_50200801_61_dialog_content = "妳已經做得比我好了。",
  ui_story_5020_50200801_62_dialog_content = "怎麼可能……",
  ui_story_5020_50200801_63_dialog_content = "接下來妳該找到自己想做的事。",
  ui_story_5020_50200801_64_dialog_content = "這個我教不了妳。",
  ui_story_5020_50200801_65_dialog_content = "……",
  ui_story_5020_50200801_66_dialog_content = "好了，有點我徒弟的樣子，別傻乎乎的。",
  ui_story_5020_50200801_67_dialog_content = "忙妳自己的事去吧。",
  ui_story_5020_50200801_68_dialog_content = "<color=#e8d9bb>咔嗒……咔嗒……咔嗒……</color>",
  ui_story_5020_50200801_69_dialog_content = "……",
  ui_story_5020_50200801_70_dialog_content = "妳怎麼還跟著？",
  ui_story_5020_50200801_71_dialog_content = "我還沒想清楚自己要做的事，所以先跟著師父。",
  ui_story_5020_50200801_72_dialog_content = "妳……",
  ui_story_5020_50200801_73_dialog_content = "唉，那妳就跟著吧。",
  ui_story_5020_50200801_74_dialog_content = "<color=#e8d9bb>咔嗒……咔嗒……咔嗒……</color>",
  ui_story_5020_50200801_75_dialog_content = "手·折·紅·花·贈·伊·人——",
  ui_story_5020_50200801_76_dialog_content = "眉……",
  ui_story_5020_50200801_77_dialog_content = "眉·前·花·落·玉·上·雪。",
  ui_story_5020_50200801_78_dialog_content = "……",
  ui_story_5020_50200801_79_dialog_content = "我想起來了，妳小時候唱歌就很好聽。",
  ui_story_5020_50200801_80_dialog_content = "現在唱得更好了。",
  ui_story_5020_50200801_81_dialog_content = "多謝師父誇獎。",
  ui_story_5020_50200801_82_dialog_content = "另一個徒弟就笨得不行，連歌詞都記不住。",
  ui_story_5020_50200801_83_dialog_content = "……她現在忘掉的事情更多了。",
  ui_story_5020_50200801_84_dialog_content = "我就知道。她是靠身體記事的，學打架的本領比誰都快。",
  ui_story_5020_50200801_85_dialog_content = "小時候妳老是打不過她，現在怎麼樣？",
  ui_story_5020_50200801_86_dialog_content = "……",
  ui_story_5020_50200801_87_dialog_content = "正好。既然妳非要跟著，就幫我個忙吧。",
  ui_story_5020_50200801_88_dialog_content = "把這根麻繩扯下來。",
  ui_story_5020_50200801_89_dialog_content = "師父，這是人家店裡的東西……",
  ui_story_5020_50200801_90_dialog_content = "我知道，借來用用，又不是不還。",
  ui_story_5020_50200801_91_dialog_content = "來，我們一起使勁。",
  ui_story_5020_50200801_92_dialog_content = "<color=#e8d9bb>嗤——啪！</color>",
  ui_story_5020_50200801_93_dialog_content = "好了，幫我把這捆麻繩背著。",
  ui_story_5020_50200801_94_dialog_content = "……是。",
  ui_story_5020_50200801_95_dialog_content = "<color=#e8d9bb>咔嗒……咔嗒……咔嗒……</color>",
  ui_story_5020_50200801_96_dialog_content = "對了。",
  ui_story_5020_50200801_97_dialog_content = "當年我出事之後……",
  ui_story_5020_50200801_98_dialog_content = "將軍有沒有辦過一場葬禮？",
  ui_story_5020_50200801_99_dialog_content = "葬禮？",
  ui_story_5020_50200801_100_dialog_content = "我沒有印象。",
  ui_story_5020_50200801_101_dialog_content = "喔，這樣。",
  ui_story_5020_50200801_102_dialog_content = "誰的葬禮？",
  ui_story_5020_50200801_103_dialog_content = "……",
  ui_story_5020_50200801_104_dialog_content = "她叫月，妳還記得她嗎？",
  ui_story_5020_50200801_105_dialog_content = "當初，是她把妳們倆託付給我的。",
  ui_story_5020_50200801_106_dialog_content = "嗯，記得。",
  ui_story_5020_50200801_107_dialog_content = "是師父的姐姐對吧？",
  ui_story_5020_50200801_108_dialog_content = "很小的時候一直受到她照顧。",
  ui_story_5020_50200801_109_dialog_content = "印象裡是一個很溫柔的人。",
  ui_story_5020_50200801_110_dialog_content = "對，很溫柔。",
  ui_story_5020_50200801_111_dialog_content = "她是怎麼去世的？",
  ui_story_5020_50200801_112_dialog_content = "……",
  ui_story_5020_50200801_113_dialog_content = "我殺了她。",
  ui_story_5020_50200801_114_dialog_content = "！",
  ui_story_5020_50200801_115_dialog_content = "因為她是「巫女」。",
  ui_story_5020_50200801_116_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5020_50200801_117_dialog_content = "<color=#e8d9bb>…………</color>",
  ui_story_5020_50200801_118_dialog_content = "她不該去當巫女的，我一開始就這麼說。",
  ui_story_5020_50200801_119_dialog_content = "但是月不聽我的。她是姐姐，總覺得自己比妹妹聰明。",
  ui_story_5020_50200801_120_dialog_content = "她說巫女可以給雲島帶來和平。",
  ui_story_5020_50200801_121_dialog_content = "我就嘲笑她，巫女只能給將軍帶去和平，刀劍才能給雲島帶來和平。",
  ui_story_5020_50200801_122_dialog_content = "最後誰都沒法說服誰，所以我們各自選擇了自己想走的路。",
  ui_story_5020_50200801_123_dialog_content = "她去本島修行，我四處殺鬼練手。",
  ui_story_5020_50200801_124_dialog_content = "幾年之後，她成了將軍的巫女，我成了「冥土幽刀」。",
  ui_story_5020_50200801_125_dialog_content = "……",
  ui_story_5020_50200801_126_dialog_content = "再見面的時候，她還沒與我敘舊，就說要比試殺鬼。",
  ui_story_5020_50200801_127_dialog_content = "我笑得合不攏嘴，欣然接受。",
  ui_story_5020_50200801_128_dialog_content = "沒想到她自信滿滿地拔出一把劍。",
  ui_story_5020_50200801_129_dialog_content = "我從沒見過那麼好的劍，通體散發出至陽之力，就像為斬鬼而生的。",
  ui_story_5020_50200801_130_dialog_content = "那場比試我輸了。月興高采烈地在我面前跳舞，一遍遍地說——",
  ui_story_5020_50200801_131_dialog_content = "「我說過的吧，巫女可以帶來和平。」",
  ui_story_5020_50200801_132_dialog_content = "那時候，我真的相信她能做到。",
  ui_story_5020_50200801_133_dialog_content = "竟然能贏過師父……",
  ui_story_5020_50200801_134_dialog_content = "要不是那把劍，她可贏不了我！",
  ui_story_5020_50200801_135_dialog_content = "斬鬼劍「天雲斬」，放在三歲小孩手中都能驅鬼辟邪，何況是她。",
  ui_story_5020_50200801_136_dialog_content = "可惜，那是我最後一次見「天雲斬」。",
  ui_story_5020_50200801_137_dialog_content = "從那之後，驅鬼就不再是她的目標了，只是手段。",
  ui_story_5020_50200801_138_dialog_content = "……",
  ui_story_5020_50200801_139_dialog_content = "她開始使用雲照鏡，在大家面前做出驅鬼的樣子。",
  ui_story_5020_50200801_140_dialog_content = "但我能看出來，那是在演戲。",
  ui_story_5020_50200801_141_dialog_content = "十年前的那場祭典上，她用雲照鏡把鬼招來，再將鬼祓除，演得樂此不疲。",
  ui_story_5020_50200801_142_dialog_content = "我能看懂，可惜其他人看不懂，他們信了。",
  ui_story_5020_50200801_143_dialog_content = "他們相信巫女能給江富城帶來和平，相信培養巫女的將軍是合格的統治者。",
  ui_story_5020_50200801_144_dialog_content = "那時候我明白了，阻礙我和月達成和平的敵人，變成了我們彼此。",
  ui_story_5020_50200801_145_dialog_content = "燭幽軍開始人心渙散，不少人失去了抵抗意志，決定歸附將軍做個順民。",
  ui_story_5020_50200801_146_dialog_content = "比起武力鎮壓，這才是最可怕的事情。",
  ui_story_5020_50200801_147_dialog_content = "為什麼？",
  ui_story_5020_50200801_148_dialog_content = "將軍殺死我們十個人，這十個人的孩子會把仇恨牢牢記住，在未來接替前人成為反抗者。",
  ui_story_5020_50200801_149_dialog_content = "而被巫女誆騙的人，他們會淡忘這份仇恨，淡忘自己的歸屬，淪為將軍的家畜。",
  ui_story_5020_50200801_150_dialog_content = "燭幽軍不怕戰敗。我們從沒真正打贏過，但我們的反抗也從未被撲滅。",
  ui_story_5020_50200801_151_dialog_content = "真正可怕的是妥協、是同化、是演變。",
  ui_story_5020_50200801_152_dialog_content = "是戰士們紛紛忘記自己戰鬥的理由。",
  ui_story_5020_50200801_153_dialog_content = "那時候沒有人會記得我們從何而來。",
  ui_story_5020_50200801_154_dialog_content = "這座島還叫雲島，但早已失去了所有屬於雲島的東西。",
  ui_story_5020_50200801_155_dialog_content = "……",
  ui_story_5020_50200801_156_dialog_content = "所以我才告訴妳，告訴燭幽軍所有人，必須殺死巫女。",
  ui_story_5020_50200801_157_dialog_content = "將軍無法打倒燭幽軍，但巫女可以。",
  ui_story_5020_50200801_158_dialog_content = "<color=#e8d9bb>咔嗒……咔嗒……咔嗒……</color>",
  ui_story_5020_50200801_159_dialog_content = "好了，我們到了。",
  ui_story_5020_50200801_160_dialog_content = "過來幫忙，把這裡所有<color=#FFB400>酒</color>都搬出來。",
  ui_story_5020_50200801_161_dialog_content = "用妳背上的麻繩，把它們全部綁在一起。",
  ui_story_5020_50200801_162_dialog_content = "……師父，這是……",
  ui_story_5020_50200801_163_dialog_content = "哎呀沒事，這家店的老闆我認識，老熟人了！",
  ui_story_5020_50200801_164_dialog_content = "我在桌上留一張欠條，錢之後再算。",
  ui_story_5020_50200801_165_dialog_content = "快動手吧。",
  ui_story_5020_50200801_166_dialog_content = "……",
  ui_story_5020_50200801_167_dialog_content = "<color=#e8d9bb>吭哧……吭哧……</color>",
  ui_story_5020_50200801_168_dialog_content = "呼——",
  ui_story_5020_50200801_169_dialog_content = "不錯，綁的滿結實！",
  ui_story_5020_50200801_170_dialog_content = "把這些酒背上，然後跟我來吧。",
  ui_story_5020_50200801_171_dialog_content = "背不動了叫我，我幫妳背著。",
  ui_story_5020_50200801_172_dialog_content = "……沒事，我可以。",
  ui_story_5020_50200801_173_dialog_content = "真的沒問題嗎？後面這段路有點累。",
  ui_story_5020_50200801_174_dialog_content = "要去哪裡？",
  ui_story_5020_50200801_175_dialog_content = "去<color=#FFB400>主城</color>。",
  ui_story_5020_50200801_176_dialog_content = "主城？！",
  ui_story_5020_50200801_177_dialog_content = "嗯。",
  ui_story_5020_50200801_178_dialog_content = "妳去過主城城樓頂上嗎？那裡風景最美了，是喝酒的好地方。",
  ui_story_5020_50200801_179_dialog_content = "妳可是我的徒弟，闖主城不是難事吧？",
  ui_story_5020_50200801_180_dialog_content = "……嗯。",
  ui_story_5020_50200801_181_dialog_content = "師父能去的地方，我也能去。",
  ui_story_5020_50200801_182_dialog_content = "<color=#e8d9bb>咔嗒……咔嗒……咔嗒……</color>",
  ui_story_5020_50200801_183_dialog_content = "又走上這條路了。",
  ui_story_5020_50200801_184_dialog_content = "十年前我也走在這條路上，看著主城在我眼中越來越大。",
  ui_story_5020_50200801_185_dialog_content = "它把日月都遮住了，大到讓人覺得，一旦進去就再也走不出來。",
  ui_story_5020_50200801_186_dialog_content = "但師父根本就沒想著出來，對吧？",
  ui_story_5020_50200801_187_dialog_content = "您把「斥鬼凌人」留給了我們。",
  ui_story_5020_50200801_188_dialog_content = "哈哈，對啊。",
  ui_story_5020_50200801_189_dialog_content = "「斥鬼凌人」可是一對好寶貝，絕不能落到將軍手裡。",
  ui_story_5020_50200801_190_dialog_content = "冒著這麼大的風險，您也要殺死她？",
  ui_story_5020_50200801_191_dialog_content = "殺死您的親姐姐……",
  ui_story_5020_50200801_192_dialog_content = "是啊，我的親姐姐。",
  ui_story_5020_50200801_193_dialog_content = "算是心有靈犀嗎？我們兩個都知道會是那一天。",
  ui_story_5020_50200801_194_dialog_content = "我做好了有死無生的打算，她做好了被我殺死的覺悟。",
  ui_story_5020_50200801_195_dialog_content = "我以為我們都會死在「雲守閣」，共同為雲島的和平而死。",
  ui_story_5020_50200801_196_dialog_content = "沒想到……",
  ui_story_5020_50200801_197_dialog_content = "她不想讓我死。",
  ui_story_5020_50200801_198_dialog_content = "我也不想去死了。",
  ui_story_5020_50200801_199_dialog_content = "？！",
  ui_story_5020_50200801_200_dialog_content = "我必須，再拉一個人去地獄。",
  ui_story_5020_50200801_201_dialog_content = "……",
  ui_story_5020_50200801_202_dialog_content = "是……藤雲將軍？",
  ui_story_5020_50200801_203_dialog_content = "對，就是他。當然是他。",
  ui_story_5020_50200801_204_dialog_content = "直到月死前我才知道，是什麼讓她發生了改變。",
  ui_story_5020_50200801_205_dialog_content = "她相信了一個人，到死都還相信著。",
  ui_story_5020_50200801_206_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5020_50200801_207_dialog_content = "我寧願她是自甘墮落，或者受人擺佈。",
  ui_story_5020_50200801_208_dialog_content = "但……她是心甘情願被藤雲騙的。",
  ui_story_5020_50200801_209_dialog_content = "哪怕她明知道事情是錯的，但她相信藤雲是對的。",
  ui_story_5020_50200801_210_dialog_content = "一個人，凌駕於了她的是非判斷之上。",
  ui_story_5020_50200801_211_dialog_content = "我恨透了那樣的情感。",
  ui_story_5020_50200801_212_dialog_content = "我恨透了那個用情感來歪曲月的將軍。",
  ui_story_5020_50200801_213_dialog_content = "我說過吧，我這個人，想到什麼就做什麼。",
  ui_story_5020_50200801_214_dialog_content = "我和他，至少有一個要去死。",
  ui_story_5020_50200801_215_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5020_50200801_216_dialog_content = "總算到了。",
  ui_story_5020_50200801_217_dialog_content = "爬樓應該是妳擅長的吧？",
  ui_story_5020_50200801_218_dialog_content = "嗯。",
  ui_story_5020_50200801_219_dialog_content = "來，比比誰先爬上去！",
  ui_story_5020_50200801_220_dialog_content = "……師父，我背著很多酒呢。",
  ui_story_5020_50200801_221_dialog_content = "怎麼？妳還真想比過師父？",
  ui_story_5020_50200801_222_dialog_content = "……",
  ui_story_5020_50200801_223_dialog_content = "<color=#e8d9bb>噔……噔……噔……</color>",
  ui_story_5020_50200801_224_dialog_content = "師父，您後悔殺死月嗎？",
  ui_story_5020_50200801_225_dialog_content = "當然不。我什麼時候後悔過。",
  ui_story_5020_50200801_226_dialog_content = "那您為什麼要問起她的葬禮？",
  ui_story_5020_50200801_227_dialog_content = "……",
  ui_story_5020_50200801_228_dialog_content = "我不後悔殺死她，但我也……",
  ui_story_5020_50200801_229_dialog_content = "她是我姐姐，應該由我來為她下葬。",
  ui_story_5020_50200801_230_dialog_content = "這樣……",
  ui_story_5020_50200801_231_dialog_content = "而且，還有一件小事。",
  ui_story_5020_50200801_232_dialog_content = "「天雲斬」是她的佩劍。我猜，這把劍也與她葬在了一起。",
  ui_story_5020_50200801_233_dialog_content = "畢竟，斬鬼的劍，將軍可用不上。",
  ui_story_5020_50200801_234_dialog_content = "您想找到「天雲斬」？",
  ui_story_5020_50200801_235_dialog_content = "是啊。",
  ui_story_5020_50200801_236_dialog_content = "要是看到那種寶貝被埋在土裡，她會氣得哭出來吧。",
  ui_story_5020_50200801_237_dialog_content = "<color=#e8d9bb>噔……噔！</color>",
  ui_story_5020_50200801_238_dialog_content = "咻——好久都沒有爬上來了！",
  ui_story_5020_50200801_239_dialog_content = "徒弟，把麻繩解開。",
  ui_story_5020_50200801_240_dialog_content = "讓我嚐嚐老闆的酒過了十年有沒有長進！",
  ui_story_5020_50200801_241_dialog_content = "沒錯。",
  ui_story_5020_50200801_242_dialog_content = "妳到能喝酒的年紀了嗎？",
  ui_story_5020_50200801_243_dialog_content = "……我不會喝酒。",
  ui_story_5020_50200801_244_dialog_content = "沒意思。",
  ui_story_5020_50200801_245_dialog_content = "算了，妳遞一壺給我，其他都<color=#FFB400>打碎</color>了吧。",
  ui_story_5020_50200801_246_dialog_content = "打碎？這是為什麼……",
  ui_story_5020_50200801_247_dialog_content = "讓妳打碎妳就打，問那麼多為什麼幹嘛。",
  ui_story_5020_50200801_248_dialog_content = "……是。",
  ui_story_5020_50200801_249_dialog_content = "<color=#e8d9bb>啪！</color>",
  ui_story_5020_50200801_250_dialog_content = "<color=#e8d9bb>啪！</color>",
  ui_story_5020_50200801_251_dialog_content = "<color=#e8d9bb>啪！！</color>",
  ui_story_5020_50200801_252_dialog_content = "哈哈哈哈哈，好！",
  ui_story_5020_50200801_253_dialog_content = "<anim type=Shake>咕咚……咕咚……</anim>",
  ui_story_5020_50200801_254_dialog_content = "呵啊——！好喝！",
  ui_story_5020_50200801_255_dialog_content = "<color=#e8d9bb>噔……噔噔……</color>",
  ui_story_5020_50200801_256_dialog_content = "師父，您別摔下去了。",
  ui_story_5020_50200801_257_dialog_content = "怎麼會！妳以為我是誰啊！",
  ui_story_5020_50200801_258_dialog_content = "徒弟，你看城樓下面。",
  ui_story_5020_50200801_259_dialog_content = "那個正在往前走的人是誰？",
  ui_story_5020_50200801_260_dialog_content = "……",
  ui_story_5020_50200801_261_dialog_content = "是藤雲將軍。",
  ui_story_5020_50200801_262_dialog_content = "他在幹嘛？",
  ui_story_5020_50200801_263_dialog_content = "我跟妳講，敵人最瞭解彼此。",
  ui_story_5020_50200801_264_dialog_content = "哪怕隔了這麼遠，隔著一座城樓，我也能懂那個老傢伙的心思。",
  ui_story_5020_50200801_265_dialog_content = "他現在肯定在想，自己正一步步邁向「和平」。",
  ui_story_5020_50200801_266_dialog_content = "為什麼？",
  ui_story_5020_50200801_267_dialog_content = "因為我也是這麼想的。",
  ui_story_5020_50200801_268_dialog_content = "！！！",
  ui_story_5020_50200801_269_dialog_content = "師父，這是……",
  ui_story_5020_50200801_270_dialog_content = "一個人喝酒多沒意思啊。",
  ui_story_5020_50200801_271_dialog_content = "我徒弟不願意陪我喝，那就讓整座江富城來陪我！",
  ui_story_5020_50200901_1_dialog_content = "將軍，叛軍主力已經被我們拿下，正在押至主城。",
  ui_story_5020_50200901_2_dialog_content = "好。",
  ui_story_5020_50200901_3_dialog_content = "燭幽軍這杆歪歪斜斜的旗，今天終於要倒下了。",
  ui_story_5020_50200901_4_dialog_content = "昭告城內百姓，城樓之下即將進行罪人的審判。",
  ui_story_5020_50200901_5_dialog_content = "提心吊膽了一夜，得有人來為事情負責，給騷亂畫上句號。",
  ui_story_5020_50200901_6_dialog_content = "等天一亮，春日祭還要開幕呢。",
  ui_story_5020_50200901_7_dialog_content = "是，將軍大人。",
  ui_story_5020_50200901_8_dialog_content = "<color=#e8d9bb>咯噔……咯噔……</color>",
  ui_story_5020_50200901_9_dialog_content = "喂，我們真的在往人少的地方前進嗎？",
  ui_story_5020_50200901_10_dialog_content = "我怎麼感覺四周越來越嘈雜了。",
  ui_story_5020_50200901_11_dialog_content = "沒辦法啊，PlayerName大人。",
  ui_story_5020_50200901_12_dialog_content = "推著鼓太顯眼了，只能跟著人群走。",
  ui_story_5020_50200901_13_dialog_content = "……我們大概在什麼位置？",
  ui_story_5020_50200901_14_dialog_content = "現在好像……",
  ui_story_5020_50200901_15_dialog_content = "快到主城了。",
  ui_story_5020_50200901_16_dialog_content = "那不是自投羅網嗎？！",
  ui_story_5020_50200901_17_dialog_content = "哎呀，總會有辦法的！",
  ui_story_5020_50200901_18_dialog_content = "實在不行，藏到春日祭結束……",
  ui_story_5020_50200901_19_dialog_content = "妳想殺了我們嗎！！！",
  ui_story_5020_50200901_20_dialog_content = "<size=45>行人都讓開！</size>",
  ui_story_5020_50200901_21_dialog_content = "<size=45>別擋路！</size>",
  ui_story_5020_50200901_22_dialog_content = "又怎麼了？",
  ui_story_5020_50200901_23_dialog_content = "武士帶著好大一隊人過來了！",
  ui_story_5020_50200901_24_dialog_content = "欸？他們好像是……",
  ui_story_5020_50200901_25_dialog_content = "是燭幽軍！",
  ui_story_5020_50200901_26_dialog_content = "燭幽軍？！",
  ui_story_5020_50200901_27_dialog_content = "他們都被抓住了嗎……",
  ui_story_5020_50200901_28_dialog_content = "嗯，看起來是這樣……",
  ui_story_5020_50200901_29_dialog_content = "他們也在往主城走。",
  ui_story_5020_50200901_30_dialog_content = "主城……將軍會怎樣對待他們呢……",
  ui_story_5020_50200901_31_dialog_content = "會把他們稱為罪魁禍首，來平息今夜的民憤。",
  ui_story_5020_50200901_32_dialog_content = "怎麼會這樣，明明不是他們……",
  ui_story_5020_50200901_33_dialog_content = "大家會相信嗎？",
  ui_story_5020_50200901_34_dialog_content = "何時招來惡鬼全由將軍掌控。",
  ui_story_5020_50200901_35_dialog_content = "大家只會看到，燭幽軍被捕之後，鬼災就此平息。",
  ui_story_5020_50200901_36_dialog_content = "他們沒有選擇，只能相信。",
  ui_story_5020_50200901_37_dialog_content = "但是那樣的話……",
  ui_story_5020_50200901_38_dialog_content = "那樣的話……",
  ui_story_5020_50200901_39_dialog_content = "欸？",
  ui_story_5020_50200901_40_dialog_content = "那樣的話江富城就沒有鬼了……",
  ui_story_5020_50200901_41_dialog_content = "好像……真的是一件好事……",
  ui_story_5020_50200901_42_dialog_content = "……嗯，真的是這樣。",
  ui_story_5020_50200901_43_dialog_content = "這就是冷酷的統治者吧。",
  ui_story_5020_50200901_44_dialog_content = "他會毫不猶豫地犧牲、背叛一些東西。",
  ui_story_5020_50200901_45_dialog_content = "但最終……事情看起來會變得更好。",
  ui_story_5020_50200901_46_dialog_content = "……",
  ui_story_5020_50200901_47_dialog_content = "只是看起來，對吧？",
  ui_story_5020_50200901_48_dialog_content = "雲島人很注重靈魂，大家真心相信靈魂的存在。",
  ui_story_5020_50200901_49_dialog_content = "如果像我說的那樣發展下去，大家確實可以活在一個沒有憂患的假象裡。",
  ui_story_5020_50200901_50_dialog_content = "但是，靈魂背離真相的罪業，與死亡又有何異呢？",
  ui_story_5020_50200901_51_dialog_content = "我相信知曉真相的人絕不會安然接受。",
  ui_story_5020_50200901_52_dialog_content = "對啊！怎麼能讓一整座城市活在謊言裡呢！",
  ui_story_5020_50200901_53_dialog_content = "大家應該知道真相！",
  ui_story_5020_50200901_54_dialog_content = "……",
  ui_story_5020_50200901_55_dialog_content = "嗯。你們說的沒錯。",
  ui_story_5020_50200901_56_dialog_content = "背離真相的和平絕不算是和平。",
  ui_story_5020_50200901_57_dialog_content = "我們來讓所有人都知道真相。",
  ui_story_5020_50200901_58_dialog_content = "<color=#e8d9bb>砰……砰……</color>",
  ui_story_5020_50200901_59_dialog_content = "阿杏阿桃，可以跟上燭幽軍的隊伍嗎？",
  ui_story_5020_50200901_60_dialog_content = "跟著他們？",
  ui_story_5020_50200901_61_dialog_content = "那就真的沒有逃跑的機會了唷。",
  ui_story_5020_50200901_62_dialog_content = "不逃了，逃什麼逃。",
  ui_story_5020_50200901_63_dialog_content = "難得來一次，可不能錯過春日祭啊！",
  ui_story_5020_50200901_64_dialog_content = "聽說要審判罪人，是真的嗎？",
  ui_story_5020_50200901_65_dialog_content = "真的真的，是將軍的口諭！",
  ui_story_5020_50200901_66_dialog_content = "招來惡鬼的罪魁禍首伏法了！",
  ui_story_5020_50200901_67_dialog_content = "你們看那邊，正往廣場上押呢！",
  ui_story_5020_50200901_68_dialog_content = "等等，真的是他們嗎？裡面好多人我都認識！",
  ui_story_5020_50200901_69_dialog_content = "誰知道，說不定是被推出來的替死鬼。",
  ui_story_5020_50200901_70_dialog_content = "將軍大人的手腕可是不賴啊，嘖嘖。",
  ui_story_5020_50200901_71_dialog_content = "不管是誰，搞出這麼大亂子，是要千刀萬剮的啊……",
  ui_story_5020_50200901_72_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5020_50200901_73_dialog_content = "稟報將軍！",
  ui_story_5020_50200901_74_dialog_content = "叛黨燭幽軍，已盡數被擒。",
  ui_story_5020_50200901_75_dialog_content = "諸賊該當何罪，請將軍定奪！",
  ui_story_5020_50200901_76_dialog_content = "自我踏足江富，已有數十年。",
  ui_story_5020_50200901_77_dialog_content = "那些圍繞著我的醜惡爭鬥早就令我厭倦。",
  ui_story_5020_50200901_78_dialog_content = "終於，在今日、在此時。",
  ui_story_5020_50200901_79_dialog_content = "我看到了「和平」的曙光。",
  ui_story_5020_50200901_80_dialog_content = "「和平」……",
  ui_story_5020_50200901_81_dialog_content = "戰爭困擾江富的時候，我平息了戰爭。",
  ui_story_5020_50200901_82_dialog_content = "鬼災困擾江富的時候，我培養了巫女。",
  ui_story_5020_50200901_83_dialog_content = "我讓這座城度過了最安穩的年月。",
  ui_story_5020_50200901_84_dialog_content = "但，總有人無法知足。",
  ui_story_5020_50200901_85_dialog_content = "他們踐踏了我經營起的秩序，貪婪地索取更多！",
  ui_story_5020_50200901_86_dialog_content = "他們，正跪在所有人面前。",
  ui_story_5020_50200901_87_dialog_content = "……",
  ui_story_5020_50200901_88_dialog_content = "叛黨燭幽軍，你們知罪嗎？",
  ui_story_5020_50200901_89_dialog_content = "罪？",
  ui_story_5020_50200901_90_dialog_content = "說實話，真的不知道。",
  ui_story_5020_50200901_91_dialog_content = "將軍大人心里肯定最清楚，您來說？",
  ui_story_5020_50200901_92_dialog_content = "好啊，我來說。",
  ui_story_5020_50200901_93_dialog_content = "你們夥同惡鬼霍亂江富。",
  ui_story_5020_50200901_94_dialog_content = "此罪，當斬！",
  ui_story_5020_50200901_95_dialog_content = "嘁。",
  ui_story_5020_50200901_96_dialog_content = "藤雲老頭，你……",
  ui_story_5020_50200901_97_dialog_content = "（那個啊，打斷一下你激昂的情緒。）",
  ui_story_5020_50200901_98_dialog_content = "（能不能麻煩你服個軟，多爭取點時間？）",
  ui_story_5020_50200901_99_dialog_content = "（要是你們現在就被殺掉我會很困擾的。）",
  ui_story_5020_50200901_100_dialog_content = "……",
  ui_story_5020_50200901_101_dialog_content = "（等一下阿杏阿桃會去給你們鬆綁，機會只在一瞬間。）",
  ui_story_5020_50200901_102_dialog_content = "（你們必須立刻制伏所有武士，不然大家一起完蛋。）",
  ui_story_5020_50200901_103_dialog_content = "（聽明白了咳嗽一聲。）",
  ui_story_5020_50200901_104_dialog_content = "咳咳！",
  ui_story_5020_50200901_105_dialog_content = "（好，繼續你的表演吧。）",
  ui_story_5020_50200901_106_dialog_content = "哎那個……將軍大人啊，我還想商量一下。",
  ui_story_5020_50200901_107_dialog_content = "斬可以，能不能不斬頭啊？",
  ui_story_5020_50200901_108_dialog_content = "……",
  ui_story_5020_50200901_109_dialog_content = "身上這些胳膊腿什麼的，您挑個喜歡的。",
  ui_story_5020_50200901_110_dialog_content = "我腦袋聰明，頭留著還有大用。",
  ui_story_5020_50200901_111_dialog_content = "這邊有三個武士，那一排有五個武士，街對面還有兩個武士。",
  ui_story_5020_50200901_112_dialog_content = "薇絲，記住了嗎？",
  ui_story_5020_50200901_113_dialog_content = "三個……五個……兩個……",
  ui_story_5020_50200901_114_dialog_content = "一定要記住啊！機會只有一次！",
  ui_story_5020_50200901_115_dialog_content = "阿杏阿桃已經把鼓面拆下來了，稍後我們直接一頭撞上去就行。",
  ui_story_5020_50200901_116_dialog_content = "從鼓裡衝出去之後，必須把周圍的武士同時放倒！",
  ui_story_5020_50200901_117_dialog_content = "這樣阿杏阿桃才有時間給燭幽軍鬆綁。",
  ui_story_5020_50200901_118_dialog_content = "嗯！三個……五個……",
  ui_story_5020_50200901_119_dialog_content = "我需要做的就是攔住將軍，對嗎？",
  ui_story_5020_50200901_120_dialog_content = "對，盡量讓局面失控。",
  ui_story_5020_50200901_121_dialog_content = "只要將軍馭鬼來鎮壓我們，真相大白的目的就達到了！",
  ui_story_5020_50200901_122_dialog_content = "在那之後呢？我們該如何脫身？",
  ui_story_5020_50200901_123_dialog_content = "我可規劃不了那麼遠……走一步算一步吧！",
  ui_story_5020_50200901_124_dialog_content = "阿杏阿桃，妳們兩個準備好了嗎？",
  ui_story_5020_50200901_125_dialog_content = "嗯！",
  ui_story_5020_50200901_126_dialog_content = "剪完繩子之後，我們就跟著燭幽軍逃跑對嗎？",
  ui_story_5020_50200901_127_dialog_content = "對！",
  ui_story_5020_50200901_128_dialog_content = "他們看起來不是很厲害……",
  ui_story_5020_50200901_129_dialog_content = "會不會有危險啊？",
  ui_story_5020_50200901_130_dialog_content = "要是遇到危險，你們就想辦法讓我們知道。",
  ui_story_5020_50200901_131_dialog_content = "比如說……",
  ui_story_5020_50200901_132_dialog_content = "這不是有個鼓嘛。",
  ui_story_5020_50200901_133_dialog_content = "喔！！！我明白了！",
  ui_story_5020_50200901_134_dialog_content = "敲鼓我喜歡！",
  ui_story_5020_50200901_135_dialog_content = "接下來就等薇絲……",
  ui_story_5020_50200901_136_dialog_content = "我背下來了！",
  ui_story_5020_50200901_137_dialog_content = "好！",
  ui_story_5020_50200901_138_dialog_content = "大家做好準備，三……",
  ui_story_5020_50200901_139_dialog_content = "<size=40>二……</size>",
  ui_story_5020_50200901_140_dialog_content = "<size=45>一……</size>",
  ui_story_5020_50200901_141_dialog_content = "<size=50>行動！</size>",
  ui_story_5020_50200901_142_dialog_content = "<color=#e8d9bb><size=50>嘭——！！！</size></color>",
  ui_story_5020_50200901_143_dialog_content = "速射感知！！！",
  ui_story_5020_50200901_144_dialog_content = "快去救人！快！",
  ui_story_5020_50200901_145_dialog_content = "知道了知道了！",
  ui_story_5020_50200901_146_dialog_content = "救命啊！打起來了！",
  ui_story_5020_50200901_147_dialog_content = "兄弟們，抄傢伙！",
  ui_story_5020_50200901_148_dialog_content = "有歹人作亂！保護將軍！！！",
  ui_story_5020_50200901_149_dialog_content = "<color=#e8d9bb>叮鈴——</color>",
  ui_story_5020_50200901_150_dialog_content = "……",
  ui_story_5020_50200901_151_dialog_content = "……",
  ui_story_5020_50200901_152_dialog_content = "凜音，妳不該選擇這樣。",
  ui_story_5020_50200901_153_dialog_content = "為什麼？",
  ui_story_5020_50200901_154_dialog_content = "因為這是錯的。",
  ui_story_5020_50200901_155_dialog_content = "你教我的對錯，和你相信的對錯，似乎並不一樣。",
  ui_story_5020_50200901_156_dialog_content = "我沒法教給妳全部。你需要時間去理解。",
  ui_story_5020_50200901_157_dialog_content = "不需要了，我已經學會了自己的對錯。",
  ui_story_5020_50200901_158_dialog_content = "在我之前的巫女，那些你認為「對」的巫女，她們下場又如何呢？",
  ui_story_5020_50200901_159_dialog_content = "她們成就了你所見到的江富城。",
  ui_story_5020_50200901_160_dialog_content = "是嗎？",
  ui_story_5020_50200901_161_dialog_content = "那我想見見不一樣的江富城。",
  ui_story_5020_50200901_162_dialog_content = "靠現在這樣的胡作非為？",
  ui_story_5020_50200901_163_dialog_content = "暴亂我見過太多次。它能帶來的不是變革，是毀滅。",
  ui_story_5020_50200901_164_dialog_content = "也有你沒見過的東西吧。",
  ui_story_5020_50200901_165_dialog_content = "比如一個對你刀刃相向的巫女。",
  ui_story_5020_50200901_166_dialog_content = "妳的刀刃如何無所謂。",
  ui_story_5020_50200901_167_dialog_content = "我只希望妳想清楚了。",
  ui_story_5020_50200901_168_dialog_content = "我一直以為，我的敵人永遠只有鬼。",
  ui_story_5020_50200901_169_dialog_content = "但現在，站在這裡面對著你。",
  ui_story_5020_50200901_170_dialog_content = "我第一次對生者產生了敵意。",
  ui_story_5020_50200901_171_dialog_content = "你該對這份敵意感到恐懼。",
  ui_story_5020_50200901_172_dialog_content = "呵呵。",
  ui_story_5020_50200901_173_dialog_content = "比起恐懼，我好像更興奮。",
  ui_story_5020_50200902_1_dialog_content = "殺啊！！！",
  ui_story_5020_50200902_2_dialog_content = "大膽叛賊！",
  ui_story_5020_50200902_3_dialog_content = "啊！！！殺人了！！！",
  ui_story_5020_50200902_4_dialog_content = "不要慌亂！",
  ui_story_5020_50200902_5_dialog_content = "整理隊列，將叛黨合而圍之！",
  ui_story_5020_50200902_6_dialog_content = "合而圍之？哼。",
  ui_story_5020_50200902_7_dialog_content = "你好像還沒有搞清楚狀況，武士。",
  ui_story_5020_50200902_8_dialog_content = "沒了鬼的幫持，戰局可不由你們左右！",
  ui_story_5020_50200902_9_dialog_content = "可笑。",
  ui_story_5020_50200902_10_dialog_content = "無論是對人還是對鬼，你們燭幽軍這麼多年，有哪次贏過！",
  ui_story_5020_50200902_11_dialog_content = "這次。",
  ui_story_5020_50200902_12_dialog_content = "怎麼辦……我們要逃嗎？",
  ui_story_5020_50200902_13_dialog_content = "逃？往哪裡逃啊，離開這裡，說不定又會撞見鬼……",
  ui_story_5020_50200902_14_dialog_content = "鬼要殺人，人也要殺人，哎……",
  ui_story_5020_50200902_15_dialog_content = "今天……又要犧牲多少條人命呢？",
  ui_story_5020_50200902_16_dialog_content = "<color=#e8d9bb>轟——！</color>",
  ui_story_5020_50200902_17_dialog_content = "！！！",
  ui_story_5020_50200902_18_dialog_content = "！！！",
  ui_story_5020_50200902_19_dialog_content = "那是……",
  ui_story_5020_50200902_20_dialog_content = "糟了。",
  ui_story_5020_50200902_21_dialog_content = "「金雲既出，照見十方。鬼妖俯首，精怪拜王。」",
  ui_story_5020_50200902_22_dialog_content = "……",
  ui_story_5020_50200902_23_dialog_content = "將軍，你終於要教我用雲照鏡了。",
  ui_story_5020_50200902_24_dialog_content = "我所盼的從來都只是和平。",
  ui_story_5020_50200902_25_dialog_content = "而你們，身為和平的受益者，卻根本不理解和平。",
  ui_story_5020_50200902_26_dialog_content = "我沒有時間再去教會你們更多了。",
  ui_story_5020_50200902_27_dialog_content = "今天，江富城的和平必將實現。",
  ui_story_5020_50200902_28_dialog_content = "無論你們是否願意。",
  ui_story_5020_50200902_29_dialog_content = "……",
  ui_story_5020_50200902_30_dialog_content = "……",
  ui_story_5020_50200902_31_dialog_content = "鬼……鬼啊！鬼來了！",
  ui_story_5020_50200902_32_dialog_content = "你們別打了，先去把鬼趕走啊！",
  ui_story_5020_50200902_33_dialog_content = "別打了？哼。",
  ui_story_5020_50200902_34_dialog_content = "援軍到了，這幫武士現在才要開始發力呢，對吧？",
  ui_story_5020_50200902_35_dialog_content = "……",
  ui_story_5020_50200902_36_dialog_content = "眾將士。",
  ui_story_5020_50200902_37_dialog_content = "把所有街道封死。",
  ui_story_5020_50200902_38_dialog_content = "在將軍下令之前，不得有任何一人離開！",
  ui_story_5020_50200902_39_dialog_content = "什麼？！！",
  ui_story_5020_50200902_40_dialog_content = "喂，不許離開是什麼意思！鬼包圍過來了啊！",
  ui_story_5020_50200902_41_dialog_content = "難道你們……",
  ui_story_5020_50200902_42_dialog_content = "兄弟們！燭幽軍可不聽將軍的命令！",
  ui_story_5020_50200902_43_dialog_content = "給老子打開一道缺口，送平民離開！",
  ui_story_5020_50200902_44_dialog_content = "是！！！",
  ui_story_5020_50200902_45_dialog_content = "快！大家，跟著燭幽軍走！",
  ui_story_5020_50200902_46_dialog_content = "我就說嘛，只有我們雲島人是可靠的！",
  ui_story_5020_50200902_47_dialog_content = "這下再清楚不過了，是將軍跟鬼勾結在一起！",
  ui_story_5020_50200902_48_dialog_content = "呸！人面獸心的敗類！",
  ui_story_5020_50200902_49_dialog_content = "封鎖街道？！你要對平民出手？",
  ui_story_5020_50200902_50_dialog_content = "我是在為他們維持秩序。",
  ui_story_5020_50200902_51_dialog_content = "遵守秩序的人，享受和平。違抗秩序的人，接受懲罰。",
  ui_story_5020_50200902_52_dialog_content = "用鬼來維持秩序？",
  ui_story_5020_50200902_53_dialog_content = "你已經瘋了……",
  ui_story_5020_50200902_54_dialog_content = "活人與鬼，不過差了一副皮囊而已。",
  ui_story_5020_50200902_55_dialog_content = "凜音，妳變得膚淺了。",
  ui_story_5020_50200902_56_dialog_content = "妳……",
  ui_story_5020_50200902_57_dialog_content = "凜音，先別跟他爭了。",
  ui_story_5020_50200902_58_dialog_content = "燭幽軍在帶平民突圍，但是……",
  ui_story_5020_50200902_59_dialog_content = "敵人太多了，光靠他們突破不了。",
  ui_story_5020_50200902_60_dialog_content = "……想到辦法了嗎？",
  ui_story_5020_50200902_61_dialog_content = "想到了。",
  ui_story_5020_50200902_62_dialog_content = "妳去幫他們。",
  ui_story_5020_50200902_63_dialog_content = "我去？那這邊怎麼辦？",
  ui_story_5020_50200902_64_dialog_content = "我和薇絲幫妳拖住將軍。",
  ui_story_5020_50200902_65_dialog_content = "欸？我們倆？",
  ui_story_5020_50200902_66_dialog_content = "對。不知道能拖多久，所以要盡快幫他們突圍。",
  ui_story_5020_50200902_67_dialog_content = "凜音，妳最擅長對付鬼，只有妳能做到。",
  ui_story_5020_50200902_68_dialog_content = "我是擔心，你們能不能……",
  ui_story_5020_50200902_69_dialog_content = "放心就好了！沒問題的！",
  ui_story_5020_50200902_70_dialog_content = "時間緊迫，妳快去吧！",
  ui_story_5020_50200902_71_dialog_content = "……好。",
  ui_story_5020_50200902_72_dialog_content = "你們千萬，量力而行。",
  ui_story_5020_50200902_73_dialog_content = "……PlayerName，真的沒問題嗎？",
  ui_story_5020_50200902_74_dialog_content = "憑我們倆對付的了將軍？",
  ui_story_5020_50200902_75_dialog_content = "對付不了。",
  ui_story_5020_50200902_76_dialog_content = "<size=45>那不是完了嗎！！！</size>",
  ui_story_5020_50200902_77_dialog_content = "別慌啊，我們不只有兩個人。",
  ui_story_5020_50200902_78_dialog_content = "幫手馬上就到了。",
  ui_story_5020_50200902_79_dialog_content = "哎唷，又是死路！",
  ui_story_5020_50200902_80_dialog_content = "有必要把房子蓋得這麼複雜嗎？",
  ui_story_5020_50200902_81_dialog_content = "再走不出去的話，今晚就要住在這裡了……",
  ui_story_5020_50200902_82_dialog_content = "沒有水喝……沒有飯吃……",
  ui_story_5020_50200902_83_dialog_content = "而且還特別熱……",
  ui_story_5020_50200902_84_dialog_content = "嗯？之前有這麼熱嗎？",
  ui_story_5020_50200902_85_dialog_content = "哇！！！！！",
  ui_story_5020_50200902_86_dialog_content = "起......起火了！有沒有人啊！",
  ui_story_5020_50200902_87_dialog_content = "不行，這下不能住了，得快點逃出去！",
  ui_story_5020_50200902_88_dialog_content = "<color=#e8d9bb>噔、噔、噔、噔……</color>",
  ui_story_5020_50200902_89_dialog_content = "哇，又是死路！",
  ui_story_5020_50200902_90_dialog_content = "怎麼辦……不然從這個窗戶……",
  ui_story_5020_50200902_91_dialog_content = "好高！",
  ui_story_5020_50200902_92_dialog_content = "不行不行，從這裡跳下去的話……",
  ui_story_5020_50200902_93_dialog_content = "哇啊啊啊！！！",
  ui_story_5020_50200902_94_dialog_content = "好像也沒那麼高了！",
  ui_story_5020_50200902_95_dialog_content = "沒關係，只要不是頭先著地的話就沒問題！",
  ui_story_5020_50200902_96_dialog_content = "預備……",
  ui_story_5020_50200902_97_dialog_content = "一、二……",
  ui_story_5020_50200902_98_dialog_content = "三！！！",
  ui_story_5020_50200902_99_dialog_content = "<anim type=Shake><size=45>哇啊啊啊啊啊啊啊啊啊啊啊啊啊啊啊！！！</size></anim>",
  ui_story_5020_50200902_100_dialog_content = "<color=#e8d9bb>嘭——！！！</color>",
  ui_story_5020_50200902_101_dialog_content = "哎唷……屁股好痛……",
  ui_story_5020_50200902_102_dialog_content = "這是……瑤？！",
  ui_story_5020_50200902_103_dialog_content = "嗯！",
  ui_story_5020_50200902_104_dialog_content = "哇！薇絲！PlayerName！",
  ui_story_5020_50200902_105_dialog_content = "好久不見！",
  ui_story_5020_50200902_106_dialog_content = "那個……可以扶我一下嗎？",
  ui_story_5020_50200902_107_dialog_content = "……來，抓緊我。",
  ui_story_5020_50200902_108_dialog_content = "PlayerName，這就是你說的幫手嗎？",
  ui_story_5020_50200902_109_dialog_content = "好像是她更需要幫助啊。",
  ui_story_5020_50200902_110_dialog_content = "呃……也不光是她。",
  ui_story_5020_50200902_111_dialog_content = "閃開！",
  ui_story_5020_50200902_112_dialog_content = "藤雲將軍，今天該你來償還了。",
  ui_story_5020_50200902_113_dialog_content = "妳是誰？我不記得欠過妳什麼東西。",
  ui_story_5020_50200902_114_dialog_content = "你欠雲島一條命。",
  ui_story_5020_50200902_115_dialog_content = "雨森！你也來了！",
  ui_story_5020_50200902_116_dialog_content = "我一直在城樓之上。",
  ui_story_5020_50200902_117_dialog_content = "本來想袖手旁觀，但你們太不禁打了。",
  ui_story_5020_50200902_118_dialog_content = "真有意思。",
  ui_story_5020_50200902_119_dialog_content = "年輕人，你們以為多聚幾隻老鼠就能反抗我嗎？",
  ui_story_5020_50200902_120_dialog_content = "哈哈哈哈哈哈哈！",
  ui_story_5020_50200902_121_dialog_content = "老鼠怎麼了？老鼠就沒有牙齒嗎？",
  ui_story_5020_50200902_122_dialog_content = "讓牠們咬上十年、五十年、一百年。",
  ui_story_5020_50200902_123_dialog_content = "再高的城也要為之坍塌！",
  ui_story_5020_50200902_124_dialog_content = "整……整座城燒起來了！",
  ui_story_5020_50200902_125_dialog_content = "對，我就是因為這個才跳下來的！",
  ui_story_5020_50200902_126_dialog_content = "藤雲老頭，見過這麼美的城樓嗎？",
  ui_story_5020_50200902_127_dialog_content = "它豎在城裡，無非是擋住了一片天空。",
  ui_story_5020_50200902_128_dialog_content = "只有現在，伴著美酒的味道和火焰的溫度，它才第一次這麼美。",
  ui_story_5020_50200902_129_dialog_content = "我覺得所有東西都是為了達到最美的一刻而生。",
  ui_story_5020_50200902_130_dialog_content = "這就是它最好的結局。",
  ui_story_5020_50200902_131_dialog_content = "「冥土幽刀」……",
  ui_story_5020_50200902_132_dialog_content = "我就知道妳不會逃走，不會滿足於自由。",
  ui_story_5020_50200902_133_dialog_content = "妳還是那把從地獄刺向我的妖刀……",
  ui_story_5020_50200902_134_dialog_content = "藤雲，我想問問你，你覺得月在哪一刻最美？",
  ui_story_5020_50200902_135_dialog_content = "……妳不配提起她。",
  ui_story_5020_50200902_136_dialog_content = "小時候我覺得，她教我唱歌的時候最美。",
  ui_story_5020_50200902_137_dialog_content = "後來我覺得，她說著「巫女能帶來和平」的時候最美。",
  ui_story_5020_50200902_138_dialog_content = "現在，你猜我怎麼想的？",
  ui_story_5020_50200902_139_dialog_content = "妳別再說了！",
  ui_story_5020_50200902_140_dialog_content = "我覺得她死在我懷裡的時候最美。",
  ui_story_5020_50200902_141_dialog_content = "……",
  ui_story_5020_50200902_142_dialog_content = "她美得讓我憤怒，讓我仇恨。",
  ui_story_5020_50200902_143_dialog_content = "因為那份美是屬於你的。",
  ui_story_5020_50200902_144_dialog_content = "十年不見了，江富城的統治者。",
  ui_story_5020_50200902_145_dialog_content = "我們來比一下吧。",
  ui_story_5020_50200902_146_dialog_content = "是你更想殺死我，還是我更想殺死你。",
  ui_story_5020_50201001_1_dialog_content = "妳不配提起她。",
  ui_story_5020_50201001_2_dialog_content = "妳不配說那個名字。",
  ui_story_5020_50201001_3_dialog_content = "是妳，無知地毀掉了她編織的美好。",
  ui_story_5020_50201001_4_dialog_content = "是妳，該去地獄向她謝罪！",
  ui_story_5020_50201001_5_dialog_content = "！！！",
  ui_story_5020_50201001_6_dialog_content = "……藤雲，你果然是個瘋子。十足的瘋子。",
  ui_story_5020_50201001_7_dialog_content = "我沒有什麼不能失去的了。",
  ui_story_5020_50201001_8_dialog_content = "……",
  ui_story_5020_50201001_9_dialog_content = "別看戲了，我的兩個徒弟。",
  ui_story_5020_50201001_10_dialog_content = "是，師父！我來幫妳！",
  ui_story_5020_50201001_11_dialog_content = "不是讓妳幫忙。",
  ui_story_5020_50201001_12_dialog_content = "妳們兩個，快跑。",
  ui_story_5020_50201001_13_dialog_content = "師父，但是……",
  ui_story_5020_50201001_14_dialog_content = "快跑！！！",
  ui_story_5020_50201001_15_dialog_content = "我沒空救妳們兩個小崽子！",
  ui_story_5020_50201001_16_dialog_content = "別把我害死！",
  ui_story_5020_50201001_17_dialog_content = "師父……",
  ui_story_5020_50201001_18_dialog_content = "嗯！我知道了！",
  ui_story_5020_50201001_19_dialog_content = "走吧雨森，師父肯定會贏的！",
  ui_story_5020_50201001_20_dialog_content = "……",
  ui_story_5020_50201001_21_dialog_content = "是，師父。",
  ui_story_5020_50201001_22_dialog_content = "這就對了，聽話才是好徒弟。",
  ui_story_5020_50201001_23_dialog_content = "「冥土幽刀」，在妳身上看到捨己為人真令人驚奇。",
  ui_story_5020_50201001_24_dialog_content = "嘁，我只是想把「冥土幽刀」的傳說續寫下去。",
  ui_story_5020_50201001_25_dialog_content = "以斬鬼聞名的劍客，對戰捨棄為人的最強之鬼……",
  ui_story_5020_50201001_26_dialog_content = "並死在他手上。",
  ui_story_5020_50201001_27_dialog_content = "<color=#e8d9bb>轟——！！！</color>",
  ui_story_5020_50201001_28_dialog_content = "好可怕的聲音……",
  ui_story_5020_50201001_29_dialog_content = "這真的是……兩個人在對戰嗎？",
  ui_story_5020_50201001_30_dialog_content = "逃跑絕對是明智之舉……我們根本不是對手。",
  ui_story_5020_50201001_31_dialog_content = "現在城裡是什麼局勢？",
  ui_story_5020_50201001_32_dialog_content = "凜音呢？凜音怎麼沒有和你們在一起？",
  ui_story_5020_50201001_33_dialog_content = "呃……我慢慢說吧。",
  ui_story_5020_50201001_34_dialog_content = "將軍似乎想用鬼來執掌秩序，那些怪物和武士一起，意圖控制江富城所有人。",
  ui_story_5020_50201001_35_dialog_content = "好在平民大都聚集在一起。燭幽軍和凜音正在掩護他們突圍。",
  ui_story_5020_50201001_36_dialog_content = "豬油菌？",
  ui_story_5020_50201001_37_dialog_content = "是燭幽軍！",
  ui_story_5020_50201001_38_dialog_content = "雲島本地人的武裝軍，師父和我都是其中一員。",
  ui_story_5020_50201001_39_dialog_content = "喔！",
  ui_story_5020_50201001_40_dialog_content = "本來妳也應該是。",
  ui_story_5020_50201001_41_dialog_content = "那這麼說，燭幽軍是好人囉？",
  ui_story_5020_50201001_42_dialog_content = "……妳就這麼理解吧。",
  ui_story_5020_50201001_43_dialog_content = "不過，巫女怎麼會與燭幽軍在一起？",
  ui_story_5020_50201001_44_dialog_content = "她被挾持了？",
  ui_story_5020_50201001_45_dialog_content = "挾持凜音？！那燭幽軍是壞人啊！",
  ui_story_5020_50201001_46_dialog_content = "並沒有，之前因為一些陰差陽錯的關係，凜音和燭幽軍並肩作戰過。",
  ui_story_5020_50201001_47_dialog_content = "現在姑且算是同一立場吧。",
  ui_story_5020_50201001_48_dialog_content = "燭幽軍和巫女站在同一立場？",
  ui_story_5020_50201001_49_dialog_content = "真難以想像……",
  ui_story_5020_50201001_50_dialog_content = "嗯……就像凜音說的，巫女只與鬼為敵。",
  ui_story_5020_50201001_51_dialog_content = "這才是她應該做的。",
  ui_story_5020_50201001_52_dialog_content = "……好，我明白了。",
  ui_story_5020_50201001_53_dialog_content = "有她在，應該能暫時保平民安全。",
  ui_story_5020_50201001_54_dialog_content = "我想去找一樣東西。",
  ui_story_5020_50201001_55_dialog_content = "什麼東西？",
  ui_story_5020_50201001_56_dialog_content = "斬鬼劍「<color=#FFB400>天雲斬</color>」。",
  ui_story_5020_50201001_57_dialog_content = "如果真如師父所說……靠它也許能扭轉戰局。",
  ui_story_5020_50201001_58_dialog_content = "好像聽燭幽軍提起過！是傳說中的武器，對吧？",
  ui_story_5020_50201001_59_dialog_content = "但它不是下落不明……",
  ui_story_5020_50201001_60_dialog_content = "我知道它和上一任巫女葬在了一起。",
  ui_story_5020_50201001_61_dialog_content = "喔！有線索！",
  ui_story_5020_50201001_62_dialog_content = "但是只靠這些好像……還遠遠不夠吧？",
  ui_story_5020_50201001_63_dialog_content = "那就翻遍城外所有墳墓。",
  ui_story_5020_50201001_64_dialog_content = "等一下！有必要這麼極端嗎！",
  ui_story_5020_50201001_65_dialog_content = "不然怎麼辦？誰知道哪座墳是上一任巫女的……",
  ui_story_5020_50201001_66_dialog_content = "那個……",
  ui_story_5020_50201001_67_dialog_content = "上一任巫女，是不是月啊？",
  ui_story_5020_50201001_68_dialog_content = "對。",
  ui_story_5020_50201001_69_dialog_content = "妳記得她？",
  ui_story_5020_50201001_70_dialog_content = "嗯，記得。",
  ui_story_5020_50201001_71_dialog_content = "而且……我還記得她埋在了哪裡。",
  ui_story_5020_50201001_72_dialog_content = "什麼？！",
  ui_story_5020_50201001_73_dialog_content = "妳真的知道？",
  ui_story_5020_50201001_73X1_dialog_content = "什麼？！",
  ui_story_5020_50201001_73X2_dialog_content = "妳妳妳……妳記得這種事情是不是說明……",
  ui_story_5020_50201001_73X3_dialog_content = "妳的記憶恢復了？",
  ui_story_5020_50201001_73X4_dialog_content = "嗯，我全都想起來了。",
  ui_story_5020_50201001_73X5_dialog_content = "太好了！ ！ ！",
  ui_story_5020_50201001_73X6_dialog_content = "雖然沒想到是在這種狀況下，但是……",
  ui_story_5020_50201001_73X7_dialog_content = "來雲島的最初目的終於達成了！",
  ui_story_5020_50201001_73X8_dialog_content = "哈哈對啊，最初的目的達成了！",
  ui_story_5020_50201001_73X9_dialog_content = "但是好像……也沒有那麼開心……",
  ui_story_5020_50201001_73X10_dialog_content = "畢竟江富城裡現在是這副樣子……",
  ui_story_5020_50201001_73X11_dialog_content = "妳是怎麼恢復記憶的？",
  ui_story_5020_50201001_73X12_dialog_content = "我在封印師父的雲守閣裡找到了一間衣櫥。",
  ui_story_5020_50201001_73X13_dialog_content = "我想起來了。十年之前，我就是在那裡失憶的。",
  ui_story_5020_50201001_73X14_dialog_content = "我躲在衣櫥裡，目睹了師父殺死月姐姐的過程。",
  ui_story_5020_50201001_73X15_dialog_content = "我太害怕了，我理解不了，我……",
  ui_story_5020_50201001_73X16_dialog_content = "我就把所有事情都忘掉了。",
  ui_story_5020_50201001_73X17_dialog_content = "怪不得妳說沒有那麼開心……",
  ui_story_5020_50201001_73X18_dialog_content = "就是覺得，原來我一直在尋找的是我當初令我痛苦、被我捨棄的東西……",
  ui_story_5020_50201001_73X19_dialog_content = "我做的所有事情好像……都很無謂啊。",
  ui_story_5020_50201001_73X20_dialog_content = "不要這樣想。",
  ui_story_5020_50201001_73X21_dialog_content = "只是當初的妳，把記憶託付給了十年後的妳。",
  ui_story_5020_50201001_73X22_dialog_content = "這段記憶等待妳長大歸鄉，等待妳回來面對十年前避之不及的命運。",
  ui_story_5020_50201001_73X23_dialog_content = "欸？",
  ui_story_5020_50201001_73X24_dialog_content = "雨森妳原來……這麼會說話啊。",
  ui_story_5020_50201001_73X25_dialog_content = "……",
  ui_story_5020_50201001_73X26_dialog_content = "月的埋骨地，也是當時聽到的嗎？",
  ui_story_5020_50201001_74_dialog_content = "嗯……",
  ui_story_5020_50201001_75_dialog_content = "我記憶裡聽到過將軍的話，要將月葬在江富城<color=#FFB400>西邊山麓</color>的地方。",
  ui_story_5020_50201001_76_dialog_content = "江富城西邊山麓……",
  ui_story_5020_50201001_77_dialog_content = "我知道了。",
  ui_story_5020_50201001_78_dialog_content = "跟我來，我們去城外。",
  ui_story_5020_50201001_79_dialog_content = "城外？現在想出城可不容易……",
  ui_story_5020_50201001_80_dialog_content = "那些傢伙來了。",
  ui_story_5020_50201001_81_dialog_content = "！！！",
  ui_story_5020_50201001_82_dialog_content = "<color=#e8d9bb>砰——！！！</color>",
  ui_story_5020_50201001_83_dialog_content = "<anim type=Shake>……</anim>",
  ui_story_5020_50201001_84_dialog_content = "<anim type=Shake>任何人……不得……離開！</anim>",
  ui_story_5020_50201002_1_dialog_content = "爸爸，爸爸……",
  ui_story_5020_50201002_2_dialog_content = "<anim type=Shake>咕——</anim>",
  ui_story_5020_50201002_3_dialog_content = "欸……嗚……",
  ui_story_5020_50201002_4_dialog_content = "哈！",
  ui_story_5020_50201002_5_dialog_content = "我打！",
  ui_story_5020_50201002_6_dialog_content = "哇！！！",
  ui_story_5020_50201002_7_dialog_content = "小朋友不要亂跑喔，現在很危險的！",
  ui_story_5020_50201002_8_dialog_content = "快回隊伍裡去吧！",
  ui_story_5020_50201002_9_dialog_content = "嗯，好！",
  ui_story_5020_50201002_10_dialog_content = "那妳們呢？",
  ui_story_5020_50201002_11_dialog_content = "我們還有事情要做！",
  ui_story_5020_50201002_12_dialog_content = "別囉嗦了阿杏，快點快點！",
  ui_story_5020_50201002_13_dialog_content = "<color=#e8d9bb>咯噔……咯噔……咯噔……</color>",
  ui_story_5020_50201002_14_dialog_content = "喔——！",
  ui_story_5020_50201002_15_dialog_content = "好大的太鼓！",
  ui_story_5020_50201002_16_dialog_content = "嘿嘿，厲害吧？",
  ui_story_5020_50201002_17_dialog_content = "妳們為什麼要推著它走？",
  ui_story_5020_50201002_18_dialog_content = "因為這是我們的東西！",
  ui_story_5020_50201002_19_dialog_content = "但是……現在不是很危險嗎？",
  ui_story_5020_50201002_20_dialog_content = "它這麼大，好累贅哦……",
  ui_story_5020_50201002_21_dialog_content = "它可不是累贅！剛才全靠它才解救了燭幽軍！",
  ui_story_5020_50201002_22_dialog_content = "對啊，等下說不定還有機會救更多人呢！",
  ui_story_5020_50201002_23_dialog_content = "<color=#e8d9bb>咯噔……咯噔……咯噔……</color>",
  ui_story_5020_50201002_24_dialog_content = "老大，這邊好像沖不過去！",
  ui_story_5020_50201002_25_dialog_content = "兄弟們都很累，正面對抗不是他們的對手……",
  ui_story_5020_50201002_26_dialog_content = "要不再換個方向？",
  ui_story_5020_50201002_27_dialog_content = "不行，再這樣下去馬上就會被敵人合圍。",
  ui_story_5020_50201002_28_dialog_content = "必須找出一個突破口。",
  ui_story_5020_50201002_29_dialog_content = "可是……",
  ui_story_5020_50201002_30_dialog_content = "我知道，經歷了一晚上的戰鬥，大家狀態很差。",
  ui_story_5020_50201002_31_dialog_content = "但這次跟之前不一樣。",
  ui_story_5020_50201002_32_dialog_content = "不只關乎自己的性命，我們背後是整座雲島。",
  ui_story_5020_50201002_33_dialog_content = "所以我們沒有放棄的權力。",
  ui_story_5020_50201002_34_dialog_content = "哪怕是戰死，也要給我化身為鬼，繼續打下去！",
  ui_story_5020_50201002_35_dialog_content = "<color=#e8d9bb>叮鈴——</color>",
  ui_story_5020_50201002_36_dialog_content = "誰許你們化身為鬼的？",
  ui_story_5020_50201002_37_dialog_content = "不要給別人添麻煩，好嗎？",
  ui_story_5020_50201002_38_dialog_content = "巫女？！",
  ui_story_5020_50201002_39_dialog_content = "妳怎麼來了？",
  ui_story_5020_50201002_40_dialog_content = "PlayerName欠你的人情……",
  ui_story_5020_50201002_41_dialog_content = "我來替他還了。",
  ui_story_5020_50201002_42_dialog_content = "……",
  ui_story_5020_50201002_43_dialog_content = "好。",
  ui_story_5020_50201002_44_dialog_content = "在驅鬼這件事上，我願意相信巫女。",
  ui_story_5020_50201002_45_dialog_content = "那戰術安排上，我就相信你們囉～",
  ui_story_5020_50201002_46_dialog_content = "妳會發現燭幽軍比將軍更可信。",
  ui_story_5020_50201002_47_dialog_content = "所有人！！！全力進攻，把敵人的包圍衝破！！！",
  ui_story_5020_50201002_48_dialog_content = "帶上平民，我們往「<color=#FFB400>港口</color>」進發！！！",
  ui_story_5020_50201002_49_dialog_content = "<anim type=Shake>咳……</anim>",
  ui_story_5020_50201002_50_dialog_content = "妳後悔嗎，薙。",
  ui_story_5020_50201002_51_dialog_content = "後悔？真是個陌生的詞啊。",
  ui_story_5020_50201002_52_dialog_content = "妳這樣強大的戰士，會想像自己如何戰死呢？",
  ui_story_5020_50201002_53_dialog_content = "我只在十年前想像過一次。",
  ui_story_5020_50201002_54_dialog_content = "我和月，死在一起。",
  ui_story_5020_50201002_55_dialog_content = "但是，月想讓妳活。",
  ui_story_5020_50201002_56_dialog_content = "妳虧欠月太多了。",
  ui_story_5020_50201002_57_dialog_content = "來世，別再做她的妹妹。",
  ui_story_5020_50201002_58_dialog_content = "咳……哈哈……",
  ui_story_5020_50201002_59_dialog_content = "來世……聽你談起來世真是可悲啊。",
  ui_story_5020_50201002_60_dialog_content = "你的人心還能維持多久，藤雲？",
  ui_story_5020_50201002_61_dialog_content = "誰能超度得了……你破敗不堪的靈魂。",
  ui_story_5020_50201002_62_dialog_content = "……",
  ui_story_5020_50201002_63_dialog_content = "我想過我的結局會是這樣。",
  ui_story_5020_50201002_64_dialog_content = "人心？早就隨著她一起死了。",
  ui_story_5020_50201002_65_dialog_content = "不過是墮落為鬼而已，反正身為人時的東西，沒什麼值得我留戀。",
  ui_story_5020_50201002_66_dialog_content = "也對……",
  ui_story_5020_50201002_67_dialog_content = "坐在吹雪閣上壽終正寢……不該是你的結局。",
  ui_story_5020_50201002_68_dialog_content = "你不配那樣平靜的死。",
  ui_story_5020_50201002_69_dialog_content = "我不覺得自己可悲。",
  ui_story_5020_50201002_70_dialog_content = "身為戰士，我戰勝了另一個強大的戰士。",
  ui_story_5020_50201002_71_dialog_content = "可是啊……藤雲……",
  ui_story_5020_50201002_72_dialog_content = "我們的戰場……只屬於十年之前……",
  ui_story_5020_50201002_73_dialog_content = "妳該感謝月，為妳爭取了十年，讓妳苟延殘喘。",
  ui_story_5020_50201002_74_dialog_content = "但你別忘了……這個戰場為何在今日重現……",
  ui_story_5020_50201002_75_dialog_content = "……",
  ui_story_5020_50201002_76_dialog_content = "因為戰場上啊……已經來了新的戰士！",
  ui_story_5020_50201002_77_dialog_content = "<anim type=Shake>哈哈……哈……</anim>",
  ui_story_5020_50201002_78_dialog_content = "<size=45><anim type=Shake>哈哈哈哈！</anim></size>",
  ui_story_5020_50201101_1_dialog_content = "<anim type=Shake>呃啊……</anim>",
  ui_story_5020_50201101_2_dialog_content = "呼……",
  ui_story_5020_50201101_3_dialog_content = "全是鬼武士嗎……",
  ui_story_5020_50201101_4_dialog_content = "藤雲這次是想要趕盡殺絕啊。",
  ui_story_5020_50201101_5_dialog_content = "管他要怎麼樣，來一個打一個就是了！",
  ui_story_5020_50201101_6_dialog_content = "喝啊——！石鎚沉海！",
  ui_story_5020_50201101_7_dialog_content = "<anim type=Shake>咕……</anim>",
  ui_story_5020_50201101_8_dialog_content = "<size=45><anim type=Shake>嘎！！！</anim></size>",
  ui_story_5020_50201101_9_dialog_content = "果......果然……根本沒辦法完全消滅這些鬼！",
  ui_story_5020_50201101_10_dialog_content = "只有凜音才可以做到這種事。",
  ui_story_5020_50201101_11_dialog_content = "<size=45><anim type=Shake>嘎吼！！！</anim></size>",
  ui_story_5020_50201101_12_dialog_content = "呵啊——",
  ui_story_5020_50201101_13_dialog_content = "不管能不能消滅，至少先把它們擊退再說！",
  ui_story_5020_50201101_14_dialog_content = "天人合一，勢如破竹！",
  ui_story_5020_50201101_15_dialog_content = "<anim type=Shake>咕……</anim>",
  ui_story_5020_50201101_16_dialog_content = "可......可是……",
  ui_story_5020_50201101_17_dialog_content = "PlayerName，你快看主城的方向——",
  ui_story_5020_50201101_18_dialog_content = "！！！",
  ui_story_5020_50201101_19_dialog_content = "<size=45><anim type=Shake>吼——！！！</anim></size>",
  ui_story_5020_50201101_20_dialog_content = "怎......怎麼會……！",
  ui_story_5020_50201101_21_dialog_content = "……這些，全都是隨著火勢而逃離主城的鬼武士。",
  ui_story_5020_50201101_22_dialog_content = "僅是一日之間，藤雲就召出了這麼多的妖兵鬼將……",
  ui_story_5020_50201101_23_dialog_content = "他當真要做這種趕盡殺絕的事。",
  ui_story_5020_50201101_24_dialog_content = "忍術——無息！",
  ui_story_5020_50201101_25_dialog_content = "我們快離開界町，擺脫這些東西的糾纏。",
  ui_story_5020_50201101_26_dialog_content = "<color=#e8d9bb>江富城郊，野外，墓園附近</color>",
  ui_story_5020_50201101_27_dialog_content = "喔……！",
  ui_story_5020_50201101_28_dialog_content = "PlayerName，我的記憶又恢復了一些！",
  ui_story_5020_50201101_29_dialog_content = "我好像來過這裡！",
  ui_story_5020_50201101_30_dialog_content = "對妳來說，這確實是一個確切的記憶……",
  ui_story_5020_50201101_31_dialog_content = "我說，這不就是我們和凜音與雨森初次見面的地方嗎！",
  ui_story_5020_50201101_32_dialog_content = "是的。當時我們初來雲島，使巨像迫降......",
  ui_story_5020_50201101_32X_dialog_content = "在前面的竹林中碰到了凜音，以及......",
  ui_story_5020_50201101_33_dialog_content = "不打不相識的雨森～！",
  ui_story_5020_50201101_34_dialog_content = "……",
  ui_story_5020_50201101_35_dialog_content = "哈！對嘛，難怪有種似曾相識的感覺！",
  ui_story_5020_50201101_36_dialog_content = "......「順著稻田村的這條河，往西走到山麓地帶，就能抵達墓園」。",
  ui_story_5020_50201101_37_dialog_content = "按照回憶裡的描述，我們這麼走應該是沒錯的！",
  ui_story_5020_50201101_38_dialog_content = "喂，雨森，妳等一下可不要妨礙我啊。",
  ui_story_5020_50201101_39_dialog_content = "可笑，這話是我向妳說才對。",
  ui_story_5020_50201101_40_dialog_content = "「天雲斬」是斬鬼之刃，是我們能與藤雲的鬼武士們抗衡的利器。",
  ui_story_5020_50201101_41_dialog_content = "在下也不指望妳幫忙，只希望妳不要從中阻撓在下。",
  ui_story_5020_50201101_42_dialog_content = "等一下，妳……妳什麼意思？",
  ui_story_5020_50201101_43_dialog_content = "妳要私自拿走天雲斬？",
  ui_story_5020_50201101_44_dialog_content = "正是。",
  ui_story_5020_50201101_45_dialog_content = "但......但是......那不是妳的劍啊？天雲斬它可是......",
  ui_story_5020_50201101_46_dialog_content = "它可是那個巫女姐姐留下來的東西！",
  ui_story_5020_50201101_47_dialog_content = "關我何事，這事關江富城無辜民眾的安危。",
  ui_story_5020_50201101_48_dialog_content = "哇，這個時候你倒是把口號喊得很響嘛？",
  ui_story_5020_50201101_49_dialog_content = "如果師父並不恨那個巫女，妳還會這麼做嗎？",
  ui_story_5020_50201101_50_dialog_content = "（這一對師姐師妹真是完全相反的兩種個性啊……）",
  ui_story_5020_50201101_51_dialog_content = "妳們……先不要急著吵架啦！",
  ui_story_5020_50201101_52_dialog_content = "……唔？",
  ui_story_5020_50201101_53_dialog_content = "這是……？",
  ui_story_5020_50201101_54_dialog_content = "哇……下雪了嗎？",
  ui_story_5020_50201101_55_dialog_content = "不，這些並不是雪，而是……",
  ui_story_5020_50201101_56_dialog_content = "<color=#FFB400>白色的櫻花</color>？",
  ui_story_5020_50201101_57_dialog_content = "潔白的、細小的花瓣，輕飄飄地降落下來……看上去真的像雪一樣！",
  ui_story_5020_50201101_58_dialog_content = "「雲島人賞櫻，以花瓣豐滿、色澤艷麗、盛放枝頭為美」……",
  ui_story_5020_50201101_59_dialog_content = "咦？這跟手冊上說的也不一樣啊！",
  ui_story_5020_50201101_60_dialog_content = "整個雲島，大概只有這裡會栽種這種櫻花吧——",
  ui_story_5020_50201101_61_dialog_content = "我們已經來到墓園附近了。",
  ui_story_5020_50201101_62_dialog_content = "唔……難怪這裡比沿途都要安靜……",
  ui_story_5020_50201101_63_dialog_content = "<anim type=Shake>咕……</anim>",
  ui_story_5020_50201101_64_dialog_content = "呃……不是吧……",
  ui_story_5020_50201101_65_dialog_content = "<anim type=Shake>咕——！！！</anim>",
  ui_story_5020_50201101_66_dialog_content = "真是殺風景啊！！！",
  ui_story_5020_50201101_67_dialog_content = "不過，在墓園周圍碰到這些東西，倒也正常……",
  ui_story_5020_50201101_68_dialog_content = "別囉囉嗦嗦的，又到本大俠出手的時刻了！",
  ui_story_5020_50201201_1_dialog_content = "速射感知！",
  ui_story_5020_50201201_2_dialog_content = "<anim type=Shake>呃啊……</anim>",
  ui_story_5020_50201201_3_dialog_content = "呼……麻煩！",
  ui_story_5020_50201201_4_dialog_content = "真是拔出蘿蔔帶出泥！",
  ui_story_5020_50201201_5_dialog_content = "……哪裡學的這一套說辭！",
  ui_story_5020_50201201_6_dialog_content = "我義姐教給我的！她這個人說話一套一套的，林家沒人能吵得過她！",
  ui_story_5020_50201201_7_dialog_content = "當然了，也很少有人能打得過她！",
  ui_story_5020_50201201_8_dialog_content = "聽起來是個不得了的角色……",
  ui_story_5020_50201201_9_dialog_content = "原來如此，那就難怪了。",
  ui_story_5020_50201201_10_dialog_content = "啊？難怪啥……難怪我也這麼厲害！",
  ui_story_5020_50201201_11_dialog_content = "難怪把妳教得這麼粗魯。",
  ui_story_5020_50201201_12_dialog_content = "真是耽誤了師父從前的栽培。",
  ui_story_5020_50201201_13_dialog_content = "哈——？妳有本事再說一遍！",
  ui_story_5020_50201201_14_dialog_content = "PlayerName你聽聽，這是一個師姐該說出來的話嗎？",
  ui_story_5020_50201201_15_dialog_content = "好了好了，瑤妳差不多得了。",
  ui_story_5020_50201201_16_dialog_content = "雨森妳也是，幹嘛去招惹妳師妹。",
  ui_story_5020_50201201_17_dialog_content = "哇！什麼叫「招惹」？",
  ui_story_5020_50201201_18_dialog_content = "招惹我怎麼了！",
  ui_story_5020_50201201_19_dialog_content = "招惹我是一件很恐怖的事嗎？！",
  ui_story_5020_50201201_20_dialog_content = "（糟了，說錯話了！）",
  ui_story_5020_50201201_21_dialog_content = "我先提前說好……",
  ui_story_5020_50201201_22_dialog_content = "墓園中的天雲斬，在下必須要拿到。",
  ui_story_5020_50201201_23_dialog_content = "妳可以用其他理由來阻攔我……",
  ui_story_5020_50201201_24_dialog_content = "畢竟妳一開始連師父是誰都忘了，只記得妳那個義姐。",
  ui_story_5020_50201201_25_dialog_content = "但是，我是從小被師父養大的。",
  ui_story_5020_50201201_26_dialog_content = "只要天雲斬能幫助師父除掉藤雲，在下就勢在必得。",
  ui_story_5020_50201201_27_dialog_content = "（即使師父從不開口要求我為她做任何事……）",
  ui_story_5020_50201201_28_dialog_content = "即使師父連放火燒城的計畫也沒有告訴妳嗎？",
  ui_story_5020_50201201_29_dialog_content = "唔……",
  ui_story_5020_50201201_30_dialog_content = "師父自然有她自己的打算！",
  ui_story_5020_50201201_31_dialog_content = "師父當然有她的想法，可是，妳又有多了解師父呢？",
  ui_story_5020_50201201_32_dialog_content = "？！",
  ui_story_5020_50201201_33_dialog_content = "妳……妳到底回想起了什麼我不知道的事情！",
  ui_story_5020_50201201_34_dialog_content = "……我已經把我知道的全說出來了。",
  ui_story_5020_50201201_35_dialog_content = "但是，那把天雲斬的主人，對師父來說一定意義非凡。",
  ui_story_5020_50201201_36_dialog_content = "……",
  ui_story_5020_50201201_37_dialog_content = "是啊......我不明白。",
  ui_story_5020_50201201_37X_dialog_content = "師父那樣愛惜羽毛的人，又何必弄髒自己的雙手......",
  ui_story_5020_50201201_38_dialog_content = "哼，不但如此……",
  ui_story_5020_50201201_39_dialog_content = "我還能感覺到，在我的記憶中，那個巫女姐姐一定也是非常重要的人。",
  ui_story_5020_50201201_40_dialog_content = "何以見得。",
  ui_story_5020_50201201_41_dialog_content = "……直覺！",
  ui_story_5020_50201201_42_dialog_content = "……",
  ui_story_5020_50201201_43_dialog_content = "妳這是什麼表情！我的直覺可是非常有用的！",
  ui_story_5020_50201201_44_dialog_content = "關於這一點……我確實可以作證。",
  ui_story_5020_50201201_45_dialog_content = "管妳信不信，那把天雲斬，反正我一定要帶走。",
  ui_story_5020_50201201_46_dialog_content = "只要我看到了它，一定還能想起更多事情。",
  ui_story_5020_50201201_47_dialog_content = "和師父有關的事情哦～",
  ui_story_5020_50201201_48_dialog_content = "總之！我倒也不指望妳幫忙，只希望妳不要阻撓我！",
  ui_story_5020_50201201_49_dialog_content = "……",
  ui_story_5020_50201201_50_dialog_content = "……唔？",
  ui_story_5020_50201201_51_dialog_content = "<color=#e8d9bb>颯颯——</color>",
  ui_story_5020_50201201_52_dialog_content = "苦無！",
  ui_story_5020_50201201_53_dialog_content = "<anim type=Shake>咕……</anim>",
  ui_story_5020_50201201_54_dialog_content = "想要偷襲在下，你還差了十個瑤的功夫。",
  ui_story_5020_50201201_55_dialog_content = "哼哼～沒錯！",
  ui_story_5020_50201201_55X_dialog_content = "等一下，聽起來好像也不是什麼好話......",
  ui_story_5020_50201201_56_dialog_content = "<anim type=Shake>咕！！</anim>",
  ui_story_5020_50201201_57_dialog_content = "<size=45><anim type=Shake>咕！！！</anim></size>",
  ui_story_5020_50201201_58_dialog_content = "無論要不要互相幫忙，至少現在——",
  ui_story_5020_50201201_59_dialog_content = "呵啊！",
  ui_story_5020_50201201_60_dialog_content = "<anim type=Shake>呃啊……</anim>",
  ui_story_5020_50201201_61_dialog_content = "我們先把這群惡鬼消滅乾淨！",
  ui_story_5020_50201201_62_dialog_content = "呵，這個道理，還需要妳告訴我嗎。",
  ui_story_5020_50201202_1_dialog_content = "<anim type=Shake>咕啊……</anim>",
  ui_story_5020_50201202_2_dialog_content = "哼，簡單解決！",
  ui_story_5020_50201202_3_dialog_content = "諸位小心，進入墓園，必會有更多鬼怪徘徊。",
  ui_story_5020_50201202_4_dialog_content = "我先用潛行來為諸位探查狀況。",
  ui_story_5020_50201202_5_dialog_content = "拜託你了！",
  ui_story_5020_50201202_6_dialog_content = "忍術無息！",
  ui_story_5020_50201202_7_dialog_content = "<color=#e8d9bb>颯颯、颯颯——</color>",
  ui_story_5020_50201202_8_dialog_content = "好不安……這裡真是安靜得嚇人。",
  ui_story_5020_50201202_9_dialog_content = "別怕，沒有什麼是一拳解決不了的！",
  ui_story_5020_50201202_10_dialog_content = "嗯……？",
  ui_story_5020_50201202_11_dialog_content = "……雨森？！",
  ui_story_5020_50201202_12_dialog_content = "不對勁……",
  ui_story_5020_50201202_13_dialog_content = "什麼不對勁？雨森，妳還好嗎？！",
  ui_story_5020_50201202_14_dialog_content = "……諸位，都進來吧。",
  ui_story_5020_50201202_15_dialog_content = "這個墓園裡……竟沒有一隻鬼。",
  ui_story_5020_50201202_16_dialog_content = "什麼……",
  ui_story_5020_50201202_17_dialog_content = "請諸位放心，這裡是絕對安全的地方。",
  ui_story_5020_50201202_18_dialog_content = "無論在下如何凝神屏息……",
  ui_story_5020_50201202_19_dialog_content = "能聽到的，只有櫻花飄落的聲音。",
  ui_story_5020_50201202_20_dialog_content = "它們不像其他花朵那樣，「砰」地一聲就能盛開……",
  ui_story_5020_50201202_21_dialog_content = "而是宛轉地伸展花瓣，忍受著綻放帶來的疼痛與喜悅。",
  ui_story_5020_50201202_22_dialog_content = "就連凋謝之際，也比一般的花更加安靜些。",
  ui_story_5020_50201202_23_dialog_content = "櫻花是隱忍的花，難怪師父會喜歡。",
  ui_story_5020_50201202_24_dialog_content = "噢噢……是旅遊手冊上沒寫過的東西！",
  ui_story_5020_50201202_25_dialog_content = "不知道為什麼，聽起來有些傷感呢……",
  ui_story_5020_50201202_26_dialog_content = "哎？不過……",
  ui_story_5020_50201202_27_dialog_content = "這裡看上去，並不是那麼人跡罕至……",
  ui_story_5020_50201202_28_dialog_content = "PlayerName，你看！",
  ui_story_5020_50201202_29_dialog_content = "啊……",
  ui_story_5020_50201202_30_dialog_content = "落櫻中間，竟然被掃出了一條小路。",
  ui_story_5020_50201202_31_dialog_content = "……有人提前來過這裡？！",
  ui_story_5020_50201202_32_dialog_content = "不好！天雲斬......",
  ui_story_5020_50201202_33_dialog_content = "啊……",
  ui_story_5020_50201202_34_dialog_content = "哇，這就是……",
  ui_story_5020_50201202_35_dialog_content = "不愧是傳說中的斬鬼之刃。",
  ui_story_5020_50201202_36_dialog_content = "流暢的劍身......劍鋒的設計也頗有古韻......",
  ui_story_5020_50201202_37_dialog_content = "歷經多年，竟然還被完好地存放在這裡……",
  ui_story_5020_50201202_38_dialog_content = "不過，這到底是誰幹的啊？",
  ui_story_5020_50201202_39_dialog_content = "這把天雲斬的擺放方式......",
  ui_story_5020_50201202_40_dialog_content = "怎麼看都感覺像是個祭品啊！",
  ui_story_5020_50201202_41_dialog_content = "呀，PlayerName，你看！",
  ui_story_5020_50201202_42_dialog_content = "天雲斬的下面，好像還壓著什麼東西......",
  ui_story_5020_50201202_43_dialog_content = "……讓在下去探查一下。",
  ui_story_5020_50201202_44_dialog_content = "雖然在這裡設置機關的可能性不大，但出於謹慎，最好……",
  ui_story_5020_50201202_45_dialog_content = "哇，妳幹什麼！",
  ui_story_5020_50201202_46_dialog_content = "……？",
  ui_story_5020_50201202_47_dialog_content = "妳憑什麼拿起天雲斬！",
  ui_story_5020_50201202_48_dialog_content = "……請不要在這種時候礙事。",
  ui_story_5020_50201202_49_dialog_content = "我說，PlayerName！",
  ui_story_5020_50201202_50_dialog_content = "哎？！我......我無意加入妳們之間的對峙……",
  ui_story_5020_50201202_51_dialog_content = "你去拿。",
  ui_story_5020_50201202_52_dialog_content = "我……我去？",
  ui_story_5020_50201202_53_dialog_content = "……",
  ui_story_5020_50201202_54_dialog_content = "如果這樣能讓瑤這傢伙安分下來，在下倒無所謂。",
  ui_story_5020_50201202_55_dialog_content = "PlayerName大人，請不要浪費在下的時間。",
  ui_story_5020_50201202_56_dialog_content = "……我知道了。",
  ui_story_5020_50201202_57_dialog_content = "嗯……？",
  ui_story_5020_50201202_58_dialog_content = "這是……",
  ui_story_5020_50201202_59_dialog_content = "和天雲斬一起放在祭台上的是......",
  ui_story_5020_50201202_60_dialog_content = "一本……<color=#FFB400>手札</color>？",
  ui_story_5020_50201202_61_dialog_content = "手札的主人叫……",
  ui_story_5020_50201202_62_dialog_content = "……「<color=#FFB400>月</color>」？",
  ui_story_5020_50201202_63_dialog_content = "？！",
  ui_story_5020_50201202_64_dialog_content = "……是她的名字。",
  ui_story_5020_50201202_65_dialog_content = "這是上一代巫女的手札。",
  ui_story_5020_50201202_66_dialog_content = "手札看起來被人為保存得非常完好，一定不是長時間放在墓園中的東西。",
  ui_story_5020_50201202_67_dialog_content = "很可能是上一個到訪者遺留下來的。",
  ui_story_5020_50201202_68_dialog_content = "在我們之前……到底是誰還來過這裡啊！",
  ui_story_5020_50201202_69_dialog_content = "……",
  ui_story_5020_50201202_70_dialog_content = "在下目前也並不能確定……",
  ui_story_5020_50201202_71_dialog_content = "至少，那個人和上一任巫女之間，一定有著密切的關係。",
  ui_story_5020_50201202_72_dialog_content = "那麼這本手札……",
  ui_story_5020_50201202_73_dialog_content = "當然要看！",
  ui_story_5020_50201202_74_dialog_content = "手札裡一定記錄著和師父有關的過往。",
  ui_story_5020_50201202_75_dialog_content = "這上面寫的東西，肯定有被我忘記的內容！",
  ui_story_5020_50201202_76_dialog_content = "我們就小心地把它打開吧，PlayerName。",
  ui_story_5020_50201202_77_dialog_content = "先看最新一頁，快點快點！從後往前翻！",
  ui_story_5020_50201202_78_dialog_content = "好......好，各位就湊到我旁邊來吧——",
  ui_story_5020_50201301_1_dialog_content = "巫女大人，您準備好了嗎？",
  ui_story_5020_50201301_2_dialog_content = "是的……不過，請等一下。",
  ui_story_5020_50201301_3_dialog_content = "請幫我把它帶給祭典的神官……",
  ui_story_5020_50201301_4_dialog_content = "不用折騰僕從了，月。",
  ui_story_5020_50201301_5_dialog_content = "我親自取走就可以了。",
  ui_story_5020_50201301_6_dialog_content = "啊……公方大人，您還沒有前往「春日祭」嗎？",
  ui_story_5020_50201301_7_dialog_content = "……祭典流程出現了一些問題。",
  ui_story_5020_50201301_8_dialog_content = "我此次回來就是特意來取雲照鏡的。",
  ui_story_5020_50201301_9_dialog_content = "……發生了什麼事？",
  ui_story_5020_50201301_10_dialog_content = "妳無需過問，只要準備好你的儀式。",
  ui_story_5020_50201301_11_dialog_content = "<color=#e8d9bb>咚咚、匡匡——</color>",
  ui_story_5020_50201301_12_dialog_content = "哎呀……",
  ui_story_5020_50201301_13_dialog_content = "外面是什麼聲音？",
  ui_story_5020_50201301_14_dialog_content = "月，你不用——",
  ui_story_5020_50201301_15_dialog_content = "呵……",
  ui_story_5020_50201301_16_dialog_content = "……",
  ui_story_5020_50201301_17_dialog_content = "這不是雲島的叛徒——巫女大人嗎。",
  ui_story_5020_50201301_18_dialog_content = "看妳這盛裝打扮的架勢，老子跟你動手，倒像是要欺負妳。",
  ui_story_5020_50201301_19_dialog_content = "哼……可惜，今年的「春日祭」，老子馬上就會讓它停辦了。",
  ui_story_5020_50201301_20_dialog_content = "請問……你們的訴求是什麼？",
  ui_story_5020_50201301_21_dialog_content = "……月！",
  ui_story_5020_50201301_22_dialog_content = "喔……？",
  ui_story_5020_50201301_23_dialog_content = "這真是直白的問題啊……",
  ui_story_5020_50201301_24_dialog_content = "這一點，妳比藤雲要聰明很多。",
  ui_story_5020_50201301_25_dialog_content = "老子的要求也很簡單，就是——終止「春日祭」。",
  ui_story_5020_50201301_26_dialog_content = "任何助長本島勢力的活動，老子必要加以遏制！",
  ui_story_5020_50201301_27_dialog_content = "不自量力。月，妳不必跟他們……",
  ui_story_5020_50201301_28_dialog_content = "我明白了。",
  ui_story_5020_50201301_29_dialog_content = "你們想要的，其實是阻止本島文化的蔓延。",
  ui_story_5020_50201301_30_dialog_content = "某......某種程度上來說，確實是這樣！",
  ui_story_5020_50201301_31_dialog_content = "從雲島的港口向本島敞開的那一天起，我們就已經進入了一個新的世代。",
  ui_story_5020_50201301_32_dialog_content = "無論是迅速接受這個規則，還是拒不承認這種現狀，都是很正常的想法。",
  ui_story_5020_50201301_33_dialog_content = "如果雲島本身有意識的話，它一定也會感嘆島上的變化之快吧……",
  ui_story_5020_50201301_34_dialog_content = "但是，只要江富城存在一天，你我就是共同生活在這一世代的人。",
  ui_story_5020_50201301_35_dialog_content = "這不是摧毀一個「春日祭」……甚至摧毀一個將軍，就可以改變的事。",
  ui_story_5020_50201301_36_dialog_content = "……",
  ui_story_5020_50201301_37_dialog_content = "比起抱著終止祭典的想法，不如好好考慮一下……",
  ui_story_5020_50201301_38_dialog_content = "怎麼把「春日祭」變成你們想要的樣子？",
  ui_story_5020_50201301_39_dialog_content = "…………",
  ui_story_5020_50201301_40_dialog_content = "巫女大人，那些庶民果然沒有繼續在祭典上鬧事。",
  ui_story_5020_50201301_41_dialog_content = "呵呵，那麼……他們的統領呢？",
  ui_story_5020_50201301_42_dialog_content = "您是說……您是說那個叫薙的女人嗎？",
  ui_story_5020_50201301_43_dialog_content = "暫時還沒有找到她的下落，吾等還在全力搜查中。",
  ui_story_5020_50201301_43X_dialog_content = "必要的話，可以再調遣一撥武力......",
  ui_story_5020_50201301_44_dialog_content = "不。不必，就這樣。",
  ui_story_5020_50201301_45_dialog_content = "要是他們再鬧起來的話，公方大人應該也會很頭痛吧。",
  ui_story_5020_50201301_46_dialog_content = "就讓薙恣意地欣賞一下「春日祭」的櫻花吧。",
  ui_story_5020_50201301_47_dialog_content = "巫女大人……恕在下僭越……",
  ui_story_5020_50201301_48_dialog_content = "您剛才說的那些話，似乎讓公方大人有些不悅。",
  ui_story_5020_50201301_49_dialog_content = "啊......也是呢。",
  ui_story_5020_50201301_49X_dialog_content = "就算我剛剛一言不發地走開，公方大人也會把他們處置乾淨。",
  ui_story_5020_50201301_50_dialog_content = "可能只是因為，我不想在充斥著歡樂氛圍的今天……",
  ui_story_5020_50201301_51_dialog_content = "看到公方大人屠戮人命吧。",
  ui_story_5020_50201301_52_dialog_content = "……屠戮人命？",
  ui_story_5020_50201301_53_dialog_content = "嗯，剛才公方大人回主城取雲照鏡的目的，已經很明顯了……",
  ui_story_5020_50201301_54_dialog_content = "他打算利用雲照鏡馭鬼，以鎮壓那些庶民。",
  ui_story_5020_50201301_55_dialog_content = "這麼依賴雲照鏡，實在不是什麼好事……",
  ui_story_5020_50201301_56_dialog_content = "您擔心什麼？您的手中有天雲斬，它是斬鬼的利刃啊！",
  ui_story_5020_50201301_57_dialog_content = "一切結束之後，您再把鬼斬殺就可以了。",
  ui_story_5020_50201301_58_dialog_content = "……",
  ui_story_5020_50201301_59_dialog_content = "天雲斬和雲照鏡，一則驅鬼，一則馭鬼，都是被神庇佑過的物品......",
  ui_story_5020_50201301_60_dialog_content = "只用作祭典表演倒還好，一旦把它們真正當成了統治的工具……",
  ui_story_5020_50201301_61_dialog_content = "我很擔心它們會釋放出別的力量——普通人無法承受的力量。",
  ui_story_5020_50201301_62_dialog_content = "可是，這不就是您被賦予的使命嗎？",
  ui_story_5020_50201301_63_dialog_content = "手握天雲斬，斬殺一切邪魔妖靈，每一代從本島回來的巫女都是這樣做的。",
  ui_story_5020_50201301_64_dialog_content = "這其實是個以己之矛，攻己之盾的問題。",
  ui_story_5020_50201301_65_dialog_content = "天雲斬可將鬼斬殺，雲照鏡可讓鬼復生......",
  ui_story_5020_50201301_66_dialog_content = "當兩股強大的力量能夠互相平衡時，「使用者的意志」就會變得十分重要。",
  ui_story_5020_50201301_67_dialog_content = "可我……完全沒辦法左右公方大人的想法呢……",
  ui_story_5020_50201301_68_dialog_content = "說到底，我也只不過是幫助雲島走向和平的工具罷了。",
  ui_story_5020_50201301_69_dialog_content = "巫女大人……在下……",
  ui_story_5020_50201301_70_dialog_content = "好像沒有聽懂！",
  ui_story_5020_50201301_71_dialog_content = "<color=#e8d9bb>叮鈴、叮鈴、叮鈴——</color>",
  ui_story_5020_50201301_72_dialog_content = "呵呵～你快看，公方大人坐在系滿鈴鐺的轎子上呢！",
  ui_story_5020_50201301_73_dialog_content = "哎呀……公......公方大人！",
  ui_story_5020_50201301_74_dialog_content = "巫女大人，恕在下失禮，在下要去護衛公方大人的安全了！",
  ui_story_5020_50201301_75_dialog_content = "<color=#e8d9bb>叮鈴、叮鈴、叮鈴——</color>",
  ui_story_5020_50201301_76_dialog_content = "妳們不許追我！妳們不許追！",
  ui_story_5020_50201301_77_dialog_content = "呼......呼……妳這孩子，快把神樂鈴還給月！",
  ui_story_5020_50201301_78_dialog_content = "我要月姐姐追我！追上我我就還！",
  ui_story_5020_50201301_79_dialog_content = "妳……都說了多少次，要叫她月大人！",
  ui_story_5020_50201301_80_dialog_content = "好的，月姐姐！",
  ui_story_5020_50201301_81_dialog_content = "好啦～阿薙，不要跟孩子生氣。",
  ui_story_5020_50201301_82_dialog_content = "瑤這麼稱呼我，說明她喜歡我呀。",
  ui_story_5020_50201301_83_dialog_content = "……妳是我的姐姐，瑤是你收養的小孩。",
  ui_story_5020_50201301_84_dialog_content = "她要是也沒大沒小地喊你姐姐……那我成什麼了！",
  ui_story_5020_50201301_85_dialog_content = "呵呵呵～",
  ui_story_5020_50201301_86_dialog_content = "妳還笑！",
  ui_story_5020_50201301_87_dialog_content = "好啦，瑤是淘氣了一點，但是雨森是個聽話的孩子啊。",
  ui_story_5020_50201301_88_dialog_content = "我託付妳來幫我帶孩子，妳簡直把雨森教得跟你自己一模一樣了。",
  ui_story_5020_50201301_89_dialog_content = "唔……這個孩子確實是個可造之材。",
  ui_story_5020_50201301_90_dialog_content = "我總是忍不住想要教她一些別的東西呢。",
  ui_story_5020_50201301_91_dialog_content = "……阿薙！",
  ui_story_5020_50201301_92_dialog_content = "好啦你放心，沒有妳的允許，我不會擅自讓她們修習那些術式。",
  ui_story_5020_50201301_93_dialog_content = "更何況……雨森這個孩子，看上去背負了很多……",
  ui_story_5020_50201301_94_dialog_content = "小小年紀，就故意作出了不符合年齡的淡薄無情……",
  ui_story_5020_50201301_95_dialog_content = "我卻知道，她還遠遠沒有長到修滅情感的年紀。",
  ui_story_5020_50201301_96_dialog_content = "確實是這樣。",
  ui_story_5020_50201301_97_dialog_content = "從我收養她們以來，我一直把她們當成我自己的孩子。",
  ui_story_5020_50201301_98_dialog_content = "這個孩子卻不怎麼和我親近，也不喜歡和瑤一起玩……",
  ui_story_5020_50201301_99_dialog_content = "但是，她卻很喜歡妳呢，阿薙。",
  ui_story_5020_50201301_100_dialog_content = "喜歡……我？",
  ui_story_5020_50201301_101_dialog_content = "是呀，她雖然不怎麼說話，但總是跟著妳，觀察著妳的舉動……",
  ui_story_5020_50201301_102_dialog_content = "妳看，現在她連喜歡的花都跟妳一模一樣。",
  ui_story_5020_50201301_103_dialog_content = "這麼小的孩子，卻懂得欣賞櫻花飄落的美呢。",
  ui_story_5020_50201301_104_dialog_content = "咦？",
  ui_story_5020_50201301_105_dialog_content = "啊，已經到了櫻花凋謝的季節了。",
  ui_story_5020_50201301_106_dialog_content = "<size=33>……時間過得真快啊，我也快要啟程前往本島了。</size>",
  ui_story_5020_50201301_107_dialog_content = "什麼，姐姐？",
  ui_story_5020_50201301_108_dialog_content = "不……沒什麼。",
  ui_story_5020_50201301_109_dialog_content = "阿薙，我馬上需要離開雲島一段時間。",
  ui_story_5020_50201301_110_dialog_content = "等我再回來時，妳應該已經成為真正的本土統領了。",
  ui_story_5020_50201301_111_dialog_content = "妳要……去哪裡？去做什麼？為什麼不提前告訴我？",
  ui_story_5020_50201301_112_dialog_content = "……把雨森和瑤託付給我，也是因為這個嗎？",
  ui_story_5020_50201301_113_dialog_content = "呵呵～她們倆確實把妳折磨得灰頭土臉……",
  ui_story_5020_50201301_114_dialog_content = "但妳也一定沒有因此恨我，對嗎？",
  ui_story_5020_50201301_115_dialog_content = "……當然沒有！",
  ui_story_5020_50201301_116_dialog_content = "這樣真是太好了……",
  ui_story_5020_50201301_117_dialog_content = "希望妳以後也不會有這樣的想法……",
  ui_story_5020_50201301_118_dialog_content = "姐姐？！妳到底在說什麼，我怎麼可能……",
  ui_story_5020_50201301_119_dialog_content = "好啦～",
  ui_story_5020_50201301_120_dialog_content = "我現在無法明確告訴妳，自然有我的原因。",
  ui_story_5020_50201301_121_dialog_content = "在我離開的日子裡，就把我們小時候唱的歌教給孩子們吧。",
  ui_story_5020_50201301_122_dialog_content = "愣著幹什麼，妳不會忘了吧？",
  ui_story_5020_50201301_123_dialog_content = "當......當然沒忘！",
  ui_story_5020_50201301_124_dialog_content = "這首歌……確實也很適合現在的季節啊。",
  ui_story_5020_50201301_125_dialog_content = "「手折紅花贈伊人」……♪",
  ui_story_5020_50201301_126_dialog_content = "「眉前花落玉上雪」……♪",
  ui_story_5020_50201301_127_dialog_content = "阿薙，妳的眉上真的接住了一瓣櫻花呢～",
  ui_story_5020_50201301_128_dialog_content = "呀，快幫我弄掉，姐姐……",
  ui_story_5020_50201301_129_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5020_50201301_130_dialog_content = "<color=#e8d9bb>…………</color>",
  ui_story_5020_50201401_1_dialog_content = "……",
  ui_story_5020_50201401_2_dialog_content = "……",
  ui_story_5020_50201401_3_dialog_content = "巫女姐姐記錄的……竟然是這樣一個故事。",
  ui_story_5020_50201401_4_dialog_content = "難怪我第一次見到凜音的時候，就覺得非常親切……",
  ui_story_5020_50201401_5_dialog_content = "原來如此，這樣一切就說得通了。",
  ui_story_5020_50201401_6_dialog_content = "似曾相識的巫女、迴盪在記憶裡的鈴鐺聲……",
  ui_story_5020_50201401_7_dialog_content = "過去的這些時光，就是瑤丟失的全部記憶了！",
  ui_story_5020_50201401_8_dialog_content = "可是，我……",
  ui_story_5020_50201401_9_dialog_content = "……瑤？",
  ui_story_5020_50201401_10_dialog_content = "為什麼我的心裡很難受……",
  ui_story_5020_50201401_11_dialog_content = "找回記憶不應該是一件讓人開心的事嗎？",
  ui_story_5020_50201401_12_dialog_content = "我還是……沒辦法理解師父的做法。",
  ui_story_5020_50201401_13_dialog_content = "但，如果把我換成師父，我又會怎麼做呢……",
  ui_story_5020_50201401_14_dialog_content = "從本島歸來的巫女，是不可饒恕的雲島叛徒——",
  ui_story_5020_50201401_15_dialog_content = "這本來是最簡單的善惡選擇！可是……",
  ui_story_5020_50201401_16_dialog_content = "為什麼，我比那時候提著刀的師父還要難過……",
  ui_story_5020_50201401_17_dialog_content = "……也許，這個世界上，本身就充滿了這種黑白難辨的選擇。",
  ui_story_5020_50201401_18_dialog_content = "不管是在艾斯特拉大陸，還是在遠東的雲島……",
  ui_story_5020_50201401_19_dialog_content = "大家都各有各的立場與堅持，也同樣會經歷各自的無奈。",
  ui_story_5020_50201401_20_dialog_content = "……是這樣嗎。",
  ui_story_5020_50201401_21_dialog_content = "還有，在最後看到的那篇手札裡……",
  ui_story_5020_50201401_22_dialog_content = "我看看......大概就在......",
  ui_story_5020_50201401_22X_dialog_content = "哇？",
  ui_story_5020_50201401_23_dialog_content = "扉頁的縫隙裡有一封<color=#FFB400>信</color>！",
  ui_story_5020_50201401_24_dialog_content = "哎呀，竟然還從來沒有被拆開過。",
  ui_story_5020_50201401_25_dialog_content = "「拜、啟、下、一、任、巫、女」……",
  ui_story_5020_50201401_26_dialog_content = "哇，這是……巫女姐姐給凜音的信！",
  ui_story_5020_50201401_27_dialog_content = "PlayerName，我們一會把它帶給凜音吧。",
  ui_story_5020_50201401_28_dialog_content = "唔……你們看，我要找的段落就在手札開頭這裡！",
  ui_story_5020_50201401_29_dialog_content = "巫女姐姐離開雲島之前，和師父告別的時候……她到底是什麼意思？",
  ui_story_5020_50201401_30_dialog_content = "她在那個時候，就預想到了成為巫女的未來嗎？",
  ui_story_5020_50201401_31_dialog_content = "那個必然被師父和雲島人怨恨的未來……",
  ui_story_5020_50201401_32_dialog_content = "畢竟……這也是她自己的選擇嘛。",
  ui_story_5020_50201401_33_dialog_content = "自己的選擇……嗎？",
  ui_story_5020_50201401_34_dialog_content = "說到這個——哼哼……",
  ui_story_5020_50201401_35_dialog_content = "怎麼樣雨森！我就說吧，巫女姐姐絕對不是什麼惡人！",
  ui_story_5020_50201401_36_dialog_content = "她是一個為了雲島和平考慮的大俠！",
  ui_story_5020_50201401_37_dialog_content = "……雨森？",
  ui_story_5020_50201401_38_dialog_content = "雨森，妳……妳在哭嗎？",
  ui_story_5020_50201401_39_dialog_content = "沒有。",
  ui_story_5020_50201401_40_dialog_content = "（不要大大咧咧地拆穿她啊！）",
  ui_story_5020_50201401_41_dialog_content = "在下只是……第一次從另一個視角認識師父……",
  ui_story_5020_50201401_42_dialog_content = "也是第一次聽到了……師父在別人面前對我的評價。",
  ui_story_5020_50201401_43_dialog_content = "曾經我以為，我是和師父一模一樣的人。",
  ui_story_5020_50201401_44_dialog_content = "連手下的燭幽軍，也都是這麼議論我的。",
  ui_story_5020_50201401_45_dialog_content = "但究竟像不像師父，只有師父自己知道。",
  ui_story_5020_50201401_46_dialog_content = "師父修身這些年，她的身心變得比藤雲還要硬……",
  ui_story_5020_50201401_47_dialog_content = "硬到可以承受任何蠻力，承受藤雲當年的一記老拳……",
  ui_story_5020_50201401_48_dialog_content = "承受一切來自外界的擊打、追捧，和各種閒言碎語……",
  ui_story_5020_50201401_49_dialog_content = "卻沒能承受住——月在氣數已盡時，將她打入封印之地的輕輕一擊。",
  ui_story_5020_50201401_50_dialog_content = "相隔十年，師父重新見到我時，對我說的第一句話……",
  ui_story_5020_50201401_51_dialog_content = "妳有時刻意裝出一副無情的樣子，有時又多了不該有的惻隱和懦弱。",
  ui_story_5020_50201401_52_dialog_content = "其實活在這個世界上，最好忘卻「情感」這回事。",
  ui_story_5020_50201401_53_dialog_content = "也許也是在規勸她自己吧。",
  ui_story_5020_50201401_54_dialog_content = "……妳在說什麼？妳當然和師父不一樣啊。",
  ui_story_5020_50201401_55_dialog_content = "這一點，我在第一次見到師父的時候就知道了。",
  ui_story_5020_50201401_56_dialog_content = "什麼……？",
  ui_story_5020_50201401_57_dialog_content = "這我可要好好地說一說了，咳咳……",
  ui_story_5020_50201401_58_dialog_content = "師父是一個很明白自己想要做什麼的人。",
  ui_story_5020_50201401_59_dialog_content = "不僅是師父，巫女姐姐也是這樣……",
  ui_story_5020_50201401_60_dialog_content = "她們都很明白，當下她們想做的事情是什麼。",
  ui_story_5020_50201401_61_dialog_content = "然而雨森，拋掉師父對妳的影響，不去想那些妳強加給自己的意願……",
  ui_story_5020_50201401_62_dialog_content = "<color=#FFB400>妳自己的選擇</color>，又是什麼呢？",
  ui_story_5020_50201401_63_dialog_content = "……？！",
  ui_story_5020_50201401_64_dialog_content = "可是，如果拋開這些的話，我根本……",
  ui_story_5020_50201401_65_dialog_content = "我根本不知道……",
  ui_story_5020_50201401_66_dialog_content = "<color=#e8d9bb>咚——！</color>",
  ui_story_5020_50201401_67_dialog_content = "<color=#e8d9bb>咚、咚咚、咚——！</color>",
  ui_story_5020_50201401_68_dialog_content = "哇，這個聲音是……",
  ui_story_5020_50201401_69_dialog_content = "<color=#FFB400>太鼓聲</color>，這是阿桃和阿杏敲響的太鼓！",
  ui_story_5020_50201401_70_dialog_content = "可是，為什麼……江富城那邊明明已經那麼混亂了……",
  ui_story_5020_50201401_71_dialog_content = "是他們和我們約定的信號！凜音他們有麻煩！",
  ui_story_5020_50201401_72_dialog_content = "凜音……！",
  ui_story_5020_50201401_73_dialog_content = "她現在在什麼地方？！",
  ui_story_5020_50201401_74_dialog_content = "……我立刻通知燭幽軍前來支援！",
  ui_story_5020_50201401_75_dialog_content = "這個倒是不用了！",
  ui_story_5020_50201401_75X_dialog_content = "凜音和我們分開之後，她就一直和燭幽軍一起行動著。",
  ui_story_5020_50201401_76_dialog_content = "現在，他們應該已經投入了新的戰鬥。",
  ui_story_5020_50201401_77_dialog_content = "一起行動？！怎麼會這樣……",
  ui_story_5020_50201401_78_dialog_content = "雨森……很多情況下，沒有選擇也是一種選擇。",
  ui_story_5020_50201401_79_dialog_content = "但至少在這種緊急時刻，妳一定清楚你想要去做什麼了！",
  ui_story_5020_50201401_80_dialog_content = "……",
  ui_story_5020_50201401_81_dialog_content = "是港口的方向。",
  ui_story_5020_50201401_82_dialog_content = "瑤，把妳的手伸過來。",
  ui_story_5020_50201401_83_dialog_content = "既然它承載著十年之前的回憶，我們就用它為當年的事情做了結。",
  ui_story_5020_50201401_84_dialog_content = "哼，英雄所見略同！",
  ui_story_5020_50201401_85_dialog_content = "走吧！我們順著這個鼓聲——出發，去<color=#FFB400>港口</color>！",
  ui_story_5020_50201401_86_dialog_content = "<color=#e8d9bb>江富城城下町，街道上</color>",
  ui_story_5020_50201401_87_dialog_content = "快——各位快跟上！",
  ui_story_5020_50201401_88_dialog_content = "順著界町這條河的下游走，前面就是港口了。",
  ui_story_5020_50201401_89_dialog_content = "都快點都快點，聽從指揮，迅速撤退！",
  ui_story_5020_50201401_90_dialog_content = "到了港口就有人安排你們乘船出海避難了。",
  ui_story_5020_50201401_91_dialog_content = "跑得離這個江富城主城越遠越好！",
  ui_story_5020_50201401_92_dialog_content = "真是亂了套了……",
  ui_story_5020_50201401_93_dialog_content = "舊統領的部下，竟然跟將軍的巫女混在一起！",
  ui_story_5020_50201401_93X_dialog_content = "......唔喔？！",
  ui_story_5020_50201401_94_dialog_content = "我......我的屁股！",
  ui_story_5020_50201401_95_dialog_content = "少廢話，不然下一次再捅你的就不是刀柄了！",
  ui_story_5020_50201401_96_dialog_content = "爸爸……我們快跟著那個巫女姐姐走吧，別人都在看我們……",
  ui_story_5020_50201401_97_dialog_content = "火還在燒……我好怕死啊……",
  ui_story_5020_50201401_98_dialog_content = "我們......我們憑什麼跟著她走！",
  ui_story_5020_50201401_99_dialog_content = "跟著這個叛徒走，讓她把我們騙到船上……我們就會被拐到本島！",
  ui_story_5020_50201401_100_dialog_content = "到時候，有一百個藤雲等著我們！",
  ui_story_5020_50201401_100X_dialog_content = "......啊——！！！",
  ui_story_5020_50201401_101_dialog_content = "好痛……呃啊啊啊啊啊！我的肩膀......我的肩膀——",
  ui_story_5020_50201401_102_dialog_content = "爸......爸爸！",
  ui_story_5020_50201401_103_dialog_content = "你們這群帶刀的狗腿，到底是想疏散雲島人，還是想害死雲島——",
  ui_story_5020_50201401_104_dialog_content = "呃？",
  ui_story_5020_50201401_105_dialog_content = "<anim type=Shake>咕……咕——！！！</anim>",
  ui_story_5020_50201401_106_dialog_content = "鬼......鬼……界町上有鬼啊——",
  ui_story_5020_50201401_107_dialog_content = "都跟上疏散隊伍，不要亂！",
  ui_story_5020_50201401_108_dialog_content = "巫女，你帶好隊伍，老子斷後！",
  ui_story_5020_50201401_109_dialog_content = "<anim type=Shake>咕！</anim>",
  ui_story_5020_50201401_110_dialog_content = "<size=45><anim type=Shake>咕！！</anim></size>",
  ui_story_5020_50201401_111_dialog_content = "<size=50><anim type=Shake>咕！！！</anim></size>",
  ui_story_5020_50201401_112_dialog_content = "兄弟們，都把刀拔出來！",
  ui_story_5020_50201401_113_dialog_content = "把這群東西的魂魄都切乾淨！",
  ui_story_5020_50201401_114_dialog_content = "呵啊——！",
  ui_story_5020_50201501_1_dialog_content = "<color=#e8d9bb>江富城港口，碼頭附近</color>",
  ui_story_5020_50201501_2_dialog_content = "<color=#e8d9bb>咚、咚咚、咚——！</color>",
  ui_story_5020_50201501_3_dialog_content = "好多人啊……這要去哪裡才能找到凜音！",
  ui_story_5020_50201501_4_dialog_content = "算了，不管了——",
  ui_story_5020_50201501_5_dialog_content = "凜音——！",
  ui_story_5020_50201501_6_dialog_content = "凜音？凜音——妳在這裡嗎？",
  ui_story_5020_50201501_7_dialog_content = "……小瑤？",
  ui_story_5020_50201501_8_dialog_content = "小瑤！！",
  ui_story_5020_50201501_9_dialog_content = "啊，還有雨森、薇絲、PlayerName大人！",
  ui_story_5020_50201501_10_dialog_content = "你們……真的聽到了太鼓的聲音！",
  ui_story_5020_50201501_11_dialog_content = "還好PlayerName反應迅速！我們立刻就趕過來了。",
  ui_story_5020_50201501_12_dialog_content = "妳這邊怎麼樣，妳有沒有受傷？",
  ui_story_5020_50201501_13_dialog_content = "沒問題，江富城附近的民眾都轉移得差不多了。",
  ui_story_5020_50201501_14_dialog_content = "燭幽軍已經帶著一部分人乘船避難了……",
  ui_story_5020_50201501_15_dialog_content = "那妳呢？妳還好嗎，那群人……他們有沒有為難妳？",
  ui_story_5020_50201501_16_dialog_content = "呵呵～小瑤在關心我呢～",
  ui_story_5020_50201501_17_dialog_content = "不用擔心我，我這不是好好的嘛。倒是你們大家，都沒事吧？",
  ui_story_5020_50201501_18_dialog_content = "我們這一大群人能有什麼事！PlayerName，快，把<color=#FFB400>那個</color>拿出來啊！",
  ui_story_5020_50201501_19_dialog_content = "唔？",
  ui_story_5020_50201501_20_dialog_content = "那......那個？啊……我知道了。",
  ui_story_5020_50201501_21_dialog_content = "凜音，請收下這個。",
  ui_story_5020_50201501_22_dialog_content = "哎呀，這是……夾在手札中的一封信？",
  ui_story_5020_50201501_23_dialog_content = "專門寫給我的嗎？可是……信的署名我並不認識……",
  ui_story_5020_50201501_24_dialog_content = "「月」，是江富城上一任巫女的名字。",
  ui_story_5020_50201501_25_dialog_content = "……我懂了。",
  ui_story_5020_50201501_26_dialog_content = "「拜啟：下一任巫女……」",
  ui_story_5020_50201501_27_dialog_content = "我決定在等待她的時候寫點什麼。",
  ui_story_5020_50201501_28_dialog_content = "對於那個我即將看不到的未來，多少還是會感到不安……",
  ui_story_5020_50201501_29_dialog_content = "想來想去，最不放心的就是有朝一日繼任的妳。",
  ui_story_5020_50201501_30_dialog_content = "得不到前輩指引是不公平的。",
  ui_story_5020_50201501_31_dialog_content = "雖然說……身為「巫女」，注定要對抗許多來自這一身分的諸多不公。",
  ui_story_5020_50201501_32_dialog_content = "不知道妳打開信的時候，雲島正逢什麼樣的季節呢……",
  ui_story_5020_50201501_33_dialog_content = "雲島向來盛產櫻花，它們盛開的時候就像燃燒的紅雲——",
  ui_story_5020_50201501_33X_dialog_content = "凋謝的時候像雪一樣飄落——",
  ui_story_5020_50201501_34_dialog_content = "——可能在眾多雲島人的眼中，巫女也只能留下這樣美麗而短暫的印象吧。",
  ui_story_5020_50201501_35_dialog_content = "但是我覺得，雲島的巫女要像太陽，孤獨燦爛地護佑這裡……",
  ui_story_5020_50201501_36_dialog_content = "我們可以和夜色中的黑暗分庭抗禮，但不要被本島的雲所遮蔽。",
  ui_story_5020_50201501_37_dialog_content = "然而，妳要是了解了這段過往，我也許該對同樣身為巫女的妳做出一點辯解。",
  ui_story_5020_50201501_38_dialog_content = "公方大人絕非遮蔽天空的烏雲，至少在我眼裡，絕不是。",
  ui_story_5020_50201501_39_dialog_content = "他沒有烏雲那麼高遠，只是撐在頭頂的一把傘。",
  ui_story_5020_50201501_40_dialog_content = "他不是個好人，也沒做過什麼好事。他給這座城帶來了許多不幸……",
  ui_story_5020_50201501_41_dialog_content = "但是，這已經是他能為江富城搏來的，最好的未來了。",
  ui_story_5020_50201501_42_dialog_content = "「最後，請原諒我把這封信寫給了跟我素未謀面的妳。」",
  ui_story_5020_50201501_43_dialog_content = "「寫下拜啟兩字後，我在收信人的填寫處猶豫了很久……」",
  ui_story_5020_50201501_44_dialog_content = "「畢竟，在這樣的時刻，它似乎難免變成一封傷感的離別信。」",
  ui_story_5020_50201501_45_dialog_content = "「所以我還是決定，讓它在未來的某個時間再被開啟。」",
  ui_story_5020_50201501_46_dialog_content = "「請帶著我的囑託，像太陽一樣活下去。」",
  ui_story_5020_50201501_47_dialog_content = "「妳的前輩，敬上。」",
  ui_story_5020_50201501_48_dialog_content = "……",
  ui_story_5020_50201501_49_dialog_content = "真是奇妙啊……",
  ui_story_5020_50201501_50_dialog_content = "對於江富城來說，巫女是一個注定與孤獨為伴的身分。",
  ui_story_5020_50201501_51_dialog_content = "但是我卻能感覺到，我從前輩的身上獲得了力量……",
  ui_story_5020_50201501_52_dialog_content = "對於歷史上的江富城巫女來說，可能確實是這樣……",
  ui_story_5020_50201501_53_dialog_content = "但是，凜音，妳已經改變了這個現狀，妳難道還沒發覺嗎？",
  ui_story_5020_50201501_54_dialog_content = "我……？",
  ui_story_5020_50201501_55_dialog_content = "巫......巫女大人……在我們上船之前，請您收下這個吧……",
  ui_story_5020_50201501_56_dialog_content = "這滿滿一袋，全部......全部都送給姐姐！",
  ui_story_5020_50201501_57_dialog_content = "這是……驅邪納福的<color=#FFB400>福豆</color>？",
  ui_story_5020_50201501_58_dialog_content = "這些是大家所有的豆子了，大家納來的福運，全都匯集在這個袋子裡喔！",
  ui_story_5020_50201501_59_dialog_content = "姐姐，快用這些豆子，把那些壞傢伙狠狠地砸一頓吧！",
  ui_story_5020_50201501_60_dialog_content = "希望我們的福運能給您帶來庇佑……",
  ui_story_5020_50201501_61_dialog_content = "巫女大人，請帶著這些豆子去戰鬥吧。",
  ui_story_5020_50201501_62_dialog_content = "各位……",
  ui_story_5020_50201501_63_dialog_content = "各位……請相信我吧！",
  ui_story_5020_50201501_64_dialog_content = "巫女，新的船已經安排好了，剩下的這批人全都可以上船了。",
  ui_story_5020_50201501_65_dialog_content = "有勞了，請帶著這些人上去吧。",
  ui_story_5020_50201501_66_dialog_content = "哼哼，雨森，妳怎麼這麼半天都不說話？",
  ui_story_5020_50201501_67_dialog_content = "再不行動起來，燭幽軍可能要再認一個新老大了哦～",
  ui_story_5020_50201501_68_dialog_content = "……我跟凜音之間又沒什麼好說的。",
  ui_story_5020_50201501_69_dialog_content = "哎呀，好狠的心啊～",
  ui_story_5020_50201501_70_dialog_content = "小雨森，這麼久不見，沒有想我嗎？",
  ui_story_5020_50201501_71_dialog_content = "也......也沒有很久啊。",
  ui_story_5020_50201501_72_dialog_content = "請不要在這種緊張時刻和在下敘舊！",
  ui_story_5020_50201501_73_dialog_content = "呀，這不是統領嗎？！",
  ui_story_5020_50201501_74_dialog_content = "<size=45>雨——森——大——人！</size>",
  ui_story_5020_50201501_75_dialog_content = "都說了，不要叫我統領。",
  ui_story_5020_50201501_76_dialog_content = "雨·森·統·領，你平時對燭幽軍管教有方喔～",
  ui_story_5020_50201501_77_dialog_content = "他們和我配合得很順利呢～",
  ui_story_5020_50201501_78_dialog_content = "哇，來了來了！凜音、雨森，妳們兩個堂堂正正打一架吧！",
  ui_story_5020_50201501_79_dialog_content = "「以絕對力量攫取燭幽軍的統領權」賽，開始——",
  ui_story_5020_50201501_80_dialog_content = "呃！痛痛痛……我的腦袋！",
  ui_story_5020_50201501_81_dialog_content = "開什麼玩笑！",
  ui_story_5020_50201501_82_dialog_content = "好啦，閒話完畢——",
  ui_story_5020_50201501_83_dialog_content = "那些鬼怪移動的速度很快，他們馬上就會追到港口來。",
  ui_story_5020_50201501_84_dialog_content = "在那之前，PlayerName大人，我們分頭做好準備吧。",
  ui_story_5020_50201501_85_dialog_content = "好，那麼……",
  ui_story_5020_50201501_86_dialog_content = "雨森帶著瑤，率領燭幽軍，去守護界町通向碼頭的隘口。",
  ui_story_5020_50201501_87_dialog_content = "薇絲、PlayerName大人，請留在這裡清除突破隘口的漏網之魚。",
  ui_story_5020_50201501_88_dialog_content = "我則去碼頭，迎戰那些包抄過來的武士！",
  ui_story_5020_50201501_89_dialog_content = "妳……一個人沒問題嗎？",
  ui_story_5020_50201501_90_dialog_content = "這種時候還要懷疑我嗎～PlayerName大人？",
  ui_story_5020_50201501_91_dialog_content = "（凜音……真的和初次見面的時候不一樣了……！）",
  ui_story_5020_50201501_92_dialog_content = "那麼，我們立刻開始行動吧！",
  ui_story_5020_50201501_93_dialog_content = "嗯！",
  ui_story_5020_50201501_94_dialog_content = "<anim type=Shake>咕……</anim>",
  ui_story_5020_50201501_95_dialog_content = "它們已經逐漸殺過來了。",
  ui_story_5020_50201501_96_dialog_content = "哼，我的拳頭已經發癢了！",
  ui_story_5020_50201501_97_dialog_content = "看來我也要立刻前往碼頭了。",
  ui_story_5020_50201501_98_dialog_content = "各位，請務必平安無虞地結束這場戰鬥！",
  ui_story_5020_50201601_1_dialog_content = "<color=#e8d9bb>江富城港口，入口處</color>",
  ui_story_5020_50201601_2_dialog_content = "<color=#e8d9bb>刺啦……刺啦……</color>",
  ui_story_5020_50201601_3_dialog_content = "呼……呼……",
  ui_story_5020_50201601_4_dialog_content = "唔……咳咳！",
  ui_story_5020_50201601_5_dialog_content = "雨森大人！",
  ui_story_5020_50201601_6_dialog_content = "大人受傷了，快帶著大人撤退！",
  ui_story_5020_50201601_7_dialog_content = "不必。你們繼續向界町的方向進軍……",
  ui_story_5020_50201601_8_dialog_content = "一直在原地防守，才是最失敗的戰略。",
  ui_story_5020_50201601_9_dialog_content = "注意穩固兵力，面對雜魚不要心慈手軟。",
  ui_story_5020_50201601_10_dialog_content = "要是碰到難纏的東西，就儘管放進來……",
  ui_story_5020_50201601_11_dialog_content = "交給我們手裡的天雲斬來解決乾淨！",
  ui_story_5020_50201601_12_dialog_content = "可是大人，您已經……",
  ui_story_5020_50201601_13_dialog_content = "你們——聽不明白嗎？！",
  ui_story_5020_50201601_14_dialog_content = "是……！",
  ui_story_5020_50201601_15_dialog_content = "<color=#e8d9bb>喀嗒喀嗒喀嗒……</color>",
  ui_story_5020_50201601_16_dialog_content = "呼……呼……",
  ui_story_5020_50201601_17_dialog_content = "當心！雨森——",
  ui_story_5020_50201601_18_dialog_content = "<anim type=Shake>咕！！！</anim>",
  ui_story_5020_50201601_19_dialog_content = "忍術無息——呃啊……",
  ui_story_5020_50201601_20_dialog_content = "雨森！！！",
  ui_story_5020_50201601_21_dialog_content = "我的疏忽……是我沒有顧及到。",
  ui_story_5020_50201601_22_dialog_content = "瑤……站到我的背後來。",
  ui_story_5020_50201601_23_dialog_content = "好......好的……！只是，為什麼要……",
  ui_story_5020_50201601_24_dialog_content = "啊，原來如此……",
  ui_story_5020_50201601_25_dialog_content = "在我從小在林家受到的教導中，真正的戰士只能正面迎敵。",
  ui_story_5020_50201601_26_dialog_content = "原來，忍術之流也流傳著這樣的戰略嗎？",
  ui_story_5020_50201601_27_dialog_content = "把背後交給敵人，是戰鬥的大忌。",
  ui_story_5020_50201601_28_dialog_content = "忍術從來不畏懼來自任何方向的偷襲。",
  ui_story_5020_50201601_29_dialog_content = "只是，在這種力不從心的時刻……",
  ui_story_5020_50201601_30_dialog_content = "在下可以放心把背後交給妳嗎？",
  ui_story_5020_50201601_31_dialog_content = "哼哼，這還用問嗎？",
  ui_story_5020_50201601_32_dialog_content = "哪怕妳沒有受傷，哪怕我們沒有被「斥鬼凌人」連結在一起……",
  ui_story_5020_50201601_33_dialog_content = "只要妳是和本大俠共同戰鬥的夥伴——",
  ui_story_5020_50201601_34_dialog_content = "本大俠就沒有不幫的道理！",
  ui_story_5020_50201601_35_dialog_content = "呵呵……漂亮話就不用多說了。",
  ui_story_5020_50201601_36_dialog_content = "下一撥敵人馬上就要衝過來了……",
  ui_story_5020_50201601_37_dialog_content = "準備好了嗎，<color=#FFB400>師妹</color>？",
  ui_story_5020_50201601_38_dialog_content = "當然，我的力量還綽綽有餘！",
  ui_story_5020_50201601_39_dialog_content = "呵啊——",
  ui_story_5020_50201601_40_dialog_content = "哈啊……哈……",
  ui_story_5020_50201601_41_dialog_content = "雨森，妳可要堅持住啊……",
  ui_story_5020_50201601_42_dialog_content = "呼……這是當然……",
  ui_story_5020_50201601_43_dialog_content = "......瑤，把天雲斬拿好！",
  ui_story_5020_50201601_44_dialog_content = "周圍的氣息不對勁……",
  ui_story_5020_50201601_45_dialog_content = "好！",
  ui_story_5020_50201601_46_dialog_content = "什麼不對勁……然後我們該怎麼做？",
  ui_story_5020_50201601_47_dialog_content = "……我們先往界町的方向挪動，為碼頭的凜音和民眾留出安全空間。",
  ui_story_5020_50201601_48_dialog_content = "時刻留意好身邊的響動……",
  ui_story_5020_50201601_49_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5020_50201601_50_dialog_content = "<color=#e8d9bb>…………</color>",
  ui_story_5020_50201601_51_dialog_content = "（兩點鐘方向是燭幽軍在和鬼怪雜碎廝殺……）",
  ui_story_5020_50201601_52_dialog_content = "（十點鐘方向是人的腳步聲……）",
  ui_story_5020_50201601_53_dialog_content = "（七點鐘方向的樹林裡……有六隻鳥剛剛拍著翅膀起飛……）",
  ui_story_5020_50201601_54_dialog_content = "（奇怪，竟然什麼異響都聽不到！怎麼回事……）",
  ui_story_5020_50201601_55_dialog_content = "……",
  ui_story_5020_50201601_56_dialog_content = "哇？雨森妳快看那邊！",
  ui_story_5020_50201601_57_dialog_content = "那個人影……",
  ui_story_5020_50201601_58_dialog_content = "是遺漏的江富居民嗎？",
  ui_story_5020_50201601_59_dialog_content = "但是，怎麼會有人遺留在城裡……",
  ui_story_5020_50201601_60_dialog_content = "……瑤！小心！",
  ui_story_5020_50201601_61_dialog_content = "什、什麼？！",
  ui_story_5020_50201601_62_dialog_content = "<anim type=Shake>……咕呃……</anim>",
  ui_story_5020_50201601_63_dialog_content = "他……他說什麼……？",
  ui_story_5020_50201601_64_dialog_content = "<anim type=Shake>咕……</anim>",
  ui_story_5020_50201601_65_dialog_content = "<size=50><anim type=Shake>吼——！！！</anim></size>",
  ui_story_5020_50201601_66_dialog_content = "是……是藤雲？！！",
  ui_story_5020_50201601_67_dialog_content = "……糟了！",
  ui_story_5020_50201601_68_dialog_content = "（藤雲怎麼會在師父的手下全身而退來到港口……）",
  ui_story_5020_50201601_69_dialog_content = "（難道......難道師父她……）",
  ui_story_5020_50201601_70_dialog_content = "這......這是什麼怪物？！",
  ui_story_5020_50201601_71_dialog_content = "<anim type=Shake>放下……</anim>",
  ui_story_5020_50201601_72_dialog_content = "<anim type=Shake>放下它……</anim>",
  ui_story_5020_50201601_73_dialog_content = "瑤，握好天雲斬......",
  ui_story_5020_50201601_74_dialog_content = "現在跟他交戰，我們沒有獲勝的把握……",
  ui_story_5020_50201601_75_dialog_content = "但天雲斬不能落入他手！",
  ui_story_5020_50201601_76_dialog_content = "混帳！！！我的師父呢？！",
  ui_story_5020_50201601_77_dialog_content = "<anim type=Shake>殺……</anim>",
  ui_story_5020_50201601_78_dialog_content = "<anim type=Shake>殺…………</anim>",
  ui_story_5020_50201601_79_dialog_content = "什……？！",
  ui_story_5020_50201601_80_dialog_content = "…………",
  ui_story_5020_50201601_81_dialog_content = "我跟你拼了！！！忍術無……",
  ui_story_5020_50201601_82_dialog_content = "呃啊！咳咳咳……",
  ui_story_5020_50201601_83_dialog_content = "（怎麼辦……已經……到極限了……）",
  ui_story_5020_50201601_84_dialog_content = "<color=#e8d9bb>颯——啪！</color>",
  ui_story_5020_50201601_85_dialog_content = "速射感知！",
  ui_story_5020_50201601_86_dialog_content = "結界——展開！",
  ui_story_5020_50201601_87_dialog_content = "大家……？！",
  ui_story_5020_50201601_88_dialog_content = "二位，辛苦了！",
  ui_story_5020_50201601_89_dialog_content = "我們各自的區域已經清理乾淨了，大家來全力守住隘口吧！",
  ui_story_5020_50201601_90_dialog_content = "你們快先躲進結界，等著我來……",
  ui_story_5020_50201601_91_dialog_content = "啊……",
  ui_story_5020_50201601_92_dialog_content = "這、這是……",
  ui_story_5020_50201601_93_dialog_content = "<size=45><anim type=Shake>吼！！！</anim></size>",
  ui_story_5020_50201601_94_dialog_content = "<anim type=Shake>凜音………………</anim>",
  ui_story_5020_50201601_95_dialog_content = "<anim type=Shake>妳……竟然…………</anim>",
  ui_story_5020_50201601_96_dialog_content = "<size=50><anim type=Shake>吼——！！！</anim></size>",
  ui_story_5020_50201601_97_dialog_content = "連藤雲將軍他自己也……變成了這幅樣子？！",
  ui_story_5020_50201601_98_dialog_content = "咳......咳……不要管他變成什麼樣子了！",
  ui_story_5020_50201601_99_dialog_content = "快點......用天雲斬把他殺掉......",
  ui_story_5020_50201601_100_dialog_content = "凜音！接著！",
  ui_story_5020_50201601_101_dialog_content = "是……！",
  ui_story_5020_50201601_102_dialog_content = "（這就是……由巫女們代代流傳下來的神物嗎……）",
  ui_story_5020_50201601_103_dialog_content = "（這個本該屬於巫女，卻被將軍藏起來的斬鬼之刃……）",
  ui_story_5020_50201601_104_dialog_content = "<color=#e8d9bb>踏……踏……踏……</color>",
  ui_story_5020_50201601_105_dialog_content = "（啊……將軍、公方大人……或許，我該最後叫您一聲父親嗎……）",
  ui_story_5020_50201601_106_dialog_content = "（握著這把天雲斬，我的手都忍不住顫抖起來了......）",
  ui_story_5020_50201601_107_dialog_content = "（這種由恐懼、緊張、興奮交織在一起的心情……）",
  ui_story_5020_50201601_108_dialog_content = "（您可是……從來都沒有教過我啊……）",
  ui_story_5020_50201601_109_dialog_content = "<size=50><anim type=Shake>吼——！！！</anim></size>",
  ui_story_5020_50201601_110_dialog_content = "父親大人……",
  ui_story_5020_50201601_111_dialog_content = "請——接招吧！！！",
  ui_story_5020_50201602_1_dialog_content = "<anim type=Shake>嘎……</anim>",
  ui_story_5020_50201602_2_dialog_content = "哈啊……哈啊……",
  ui_story_5020_50201602_3_dialog_content = "凜音，快趁現在！",
  ui_story_5020_50201602_4_dialog_content = "呵啊——！！！",
  ui_story_5020_50201602_5_dialog_content = "<size=50><anim type=Shake>呃啊啊啊啊啊啊啊啊啊啊！！！</anim></size>",
  ui_story_5020_50201602_6_dialog_content = "<anim type=Shake>嘶——</anim>",
  ui_story_5020_50201602_7_dialog_content = "<anim type=Shake>嗬……嗬……嗬……</anim>",
  ui_story_5020_50201602_8_dialog_content = "將……將軍？",
  ui_story_5020_50201602_9_dialog_content = "成功了！",
  ui_story_5020_50201602_10_dialog_content = "斬滅鬼的形態，使他們重新變成人……",
  ui_story_5020_50201602_11_dialog_content = "這就是天雲斬的力量嗎？",
  ui_story_5020_50201602_12_dialog_content = "凜音......妳們......果然帶走了天雲斬......",
  ui_story_5020_50201602_13_dialog_content = "妳……做得很好……",
  ui_story_5020_50201602_14_dialog_content = "到我這邊來……",
  ui_story_5020_50201602_15_dialog_content = "將軍，您……",
  ui_story_5020_50201602_16_dialog_content = "您做了太多我不能饒恕的事情……",
  ui_story_5020_50201602_17_dialog_content = "即使您有您的無奈，但這份無奈……也不該成為您苦心孤詣追求力量的理由。",
  ui_story_5020_50201602_18_dialog_content = "江富城的火勢已經熄了。",
  ui_story_5020_50201602_19_dialog_content = "……您也該停下來休息了。",
  ui_story_5020_50201602_20_dialog_content = "無奈？哈哈……",
  ui_story_5020_50201602_21_dialog_content = "妳……還是看到那封信了。",
  ui_story_5020_50201602_22_dialog_content = "在妳看得到的這份無奈之外，還有更多妳不理解的事情。",
  ui_story_5020_50201602_23_dialog_content = "但「無奈」這個詞，本來不該從孩子的嘴裡說出來。",
  ui_story_5020_50201602_24_dialog_content = "凜音……你長大了。",
  ui_story_5020_50201602_25_dialog_content = "可你甚至……不再叫我一聲「公方大人」了嗎？",
  ui_story_5020_50201602_26_dialog_content = "……",
  ui_story_5020_50201602_27_dialog_content = "哼，你根本不配這個稱呼！",
  ui_story_5020_50201602_28_dialog_content = "藤雲，你大勢已去了。",
  ui_story_5020_50201602_29_dialog_content = "看看你周圍吧。",
  ui_story_5020_50201602_30_dialog_content = "嗬，啐！真是報應。",
  ui_story_5020_50201602_31_dialog_content = "跪低點……對對對，再跪低點……哈哈哈！藤雲大將軍也有今天！",
  ui_story_5020_50201602_32_dialog_content = "廢什麼話？乾脆點，上啊兄弟們，一刀斬了他，給春日祭助助興！",
  ui_story_5020_50201602_33_dialog_content = "沒錯——上！上！上！上……",
  ui_story_5020_50201602_34_dialog_content = "哈哈……哈哈哈哈哈哈哈……",
  ui_story_5020_50201602_35_dialog_content = "大膽！",
  ui_story_5020_50201602_36_dialog_content = "刁民退散！誰敢斬殺公方大人，就是跟整個本島作對！",
  ui_story_5020_50201602_37_dialog_content = "呸，本島算是什麼東西！",
  ui_story_5020_50201602_38_dialog_content = "看看你身後還剩幾個人模人樣的武士？藤雲，你這是活該啊！",
  ui_story_5020_50201602_39_dialog_content = "兄弟們，都給老子上！",
  ui_story_5020_50201602_40_dialog_content = "<color=#e8d9bb>刺啦——</color>",
  ui_story_5020_50201602_41_dialog_content = "誰敢！",
  ui_story_5020_50201602_42_dialog_content = "退下……咳咳咳……給我退下……",
  ui_story_5020_50201602_43_dialog_content = "藤雲將軍死了，雲島就會變得更好嗎？！",
  ui_story_5020_50201602_44_dialog_content = "…………",
  ui_story_5020_50201602_45_dialog_content = "縱使你們斬殺了現任將軍……",
  ui_story_5020_50201602_46_dialog_content = "不出半月，本島就會立刻派來新的將軍接手雲島。",
  ui_story_5020_50201602_47_dialog_content = "到時候，你們的仇恨又該對準誰呢？！",
  ui_story_5020_50201602_48_dialog_content = "在你們這群逆賊的眼中，公方大人是被你們唾棄的外來勢力。",
  ui_story_5020_50201602_49_dialog_content = "但公方大人又何嘗不是被外來勢力操控的傀儡！",
  ui_story_5020_50201602_50_dialog_content = "來人……來人！把這個說話的……拿下……",
  ui_story_5020_50201602_51_dialog_content = "（藤雲……好像掙扎著有話要說……）",
  ui_story_5020_50201602_52_dialog_content = "不，請您讓我說下去！",
  ui_story_5020_50201602_53_dialog_content = "……公方大人在本島和雲島勢力之間，所做的權衡之計……",
  ui_story_5020_50201602_54_dialog_content = "以及他為了雲島和平而做出的一切努力……又哪是你們能理解的！",
  ui_story_5020_50201602_55_dialog_content = "就算你們說他的手段扭曲……就算他的心態也是扭曲的……",
  ui_story_5020_50201602_56_dialog_content = "但他所追求的結果，真的是錯誤的嗎？！！",
  ui_story_5020_50201602_57_dialog_content = "…………",
  ui_story_5020_50201602_58_dialog_content = "雖然他話說得不對……",
  ui_story_5020_50201602_59_dialog_content = "但道理好像確實是這個道理……",
  ui_story_5020_50201602_60_dialog_content = "我之前一直都這麼覺得，可惜周圍人的眼界太低，看不懂這種高層局勢……",
  ui_story_5020_50201602_61_dialog_content = "要是讓我來管雲島，肯定還要比這個藤雲好百倍！",
  ui_story_5020_50201602_62_dialog_content = "啥意思？他放幾句屁你們都覺得是香的？！",
  ui_story_5020_50201602_63_dialog_content = "要投敵先跟我打兩下，我生平最看不慣這種叛徒！",
  ui_story_5020_50201602_64_dialog_content = "<color=#e8d9bb>嘰嘰喳喳……嘰嘰喳喳……</color>",
  ui_story_5020_50201602_65_dialog_content = "呵……公方大人需要你們這種遲來的理解嗎？",
  ui_story_5020_50201602_66_dialog_content = "你們的認同，對公方大人就是一種侮辱！",
  ui_story_5020_50201602_67_dialog_content = "閉嘴……",
  ui_story_5020_50201602_68_dialog_content = "是的，都給我閉嘴！",
  ui_story_5020_50201602_69_dialog_content = "能夠理解公方大人的，注定只能是少數人……",
  ui_story_5020_50201602_70_dialog_content = "公方大人，屬下是這個世界上最懂您的啊！",
  ui_story_5020_50201602_71_dialog_content = "夠了！",
  ui_story_5020_50201602_72_dialog_content = "閉上你這張無知的嘴。",
  ui_story_5020_50201602_73_dialog_content = "何……何人無禮？！",
  ui_story_5020_50201602_74_dialog_content = "……",
  ui_story_5020_50201602_75_dialog_content = "妳來了……",
  ui_story_5020_50201701_1_dialog_content = "這......這個女人是……",
  ui_story_5020_50201701_2_dialog_content = "她怎麼還活著？",
  ui_story_5020_50201701_3_dialog_content = "爸爸……她是誰啊——",
  ui_story_5020_50201701_4_dialog_content = "噓！",
  ui_story_5020_50201701_5_dialog_content = "別亂問，把嘴閉好！",
  ui_story_5020_50201701_6_dialog_content = "（師父？！）",
  ui_story_5020_50201701_7_dialog_content = "呵……",
  ui_story_5020_50201701_8_dialog_content = "好感人的演說。",
  ui_story_5020_50201701_9_dialog_content = "作為一個屬下，你很會侮辱這個將軍。",
  ui_story_5020_50201701_10_dialog_content = "你說什……",
  ui_story_5020_50201701_11_dialog_content = "呃！",
  ui_story_5020_50201701_12_dialog_content = "不要礙事。",
  ui_story_5020_50201701_13_dialog_content = "……",
  ui_story_5020_50201701_14_dialog_content = "藤雲，你期待這一刻已經很久了吧。",
  ui_story_5020_50201701_15_dialog_content = "妳還是來了。",
  ui_story_5020_50201701_16_dialog_content = "我來早了。",
  ui_story_5020_50201701_17_dialog_content = "讓這個武士再多折磨你一會，也不是一件壞事。",
  ui_story_5020_50201701_18_dialog_content = "你當下最想要的，絕對不是認可，而是一場即將到來的死亡。",
  ui_story_5020_50201701_19_dialog_content = "我說得不錯吧？",
  ui_story_5020_50201701_20_dialog_content = "……呵呵。",
  ui_story_5020_50201701_21_dialog_content = "死於戰場對我來說向來都不是悲劇……而是英雄的歸宿。",
  ui_story_5020_50201701_22_dialog_content = "快了結我吧……",
  ui_story_5020_50201701_23_dialog_content = "如果殺死我的人是妳的話。",
  ui_story_5020_50201701_24_dialog_content = "藤雲，你一生做盡齷齪之事……",
  ui_story_5020_50201701_25_dialog_content = "到了這個時候，反倒開始尋求體面了。",
  ui_story_5020_50201701_26_dialog_content = "哈哈哈哈……咳咳咳……",
  ui_story_5020_50201701_27_dialog_content = "薙，妳的劍法一向乾淨利落……",
  ui_story_5020_50201701_28_dialog_content = "只求妳揮劍時不要遲疑，免得糟蹋了妳自己。",
  ui_story_5020_50201701_29_dialog_content = "呵，你多慮了。",
  ui_story_5020_50201701_30_dialog_content = "<color=#e8d9bb>刺啦——</color>",
  ui_story_5020_50201701_31_dialog_content = "……",
  ui_story_5020_50201701_32_dialog_content = "在這之前，你還可以留下最後一句話。",
  ui_story_5020_50201701_33_dialog_content = "……",
  ui_story_5020_50201701_34_dialog_content = "月……",
  ui_story_5020_50201701_35_dialog_content = "現在的江富城，是你想看到的樣子嗎？",
  ui_story_5020_50201701_36_dialog_content = "…………",
  ui_story_5020_50201701_37_dialog_content = "…………",
  ui_story_5020_50201701_38_dialog_content = "他……死、死了嗎……？",
  ui_story_5020_50201701_39_dialog_content = "死了吧？",
  ui_story_5020_50201701_40_dialog_content = "好像是沒氣了……",
  ui_story_5020_50201701_41_dialog_content = "死了！死了……真的死了！",
  ui_story_5020_50201701_42_dialog_content = "藤雲死了！雲島沒有將軍了！！！",
  ui_story_5020_50201701_43_dialog_content = "<size=50><anim type=Shake>噢噢噢噢噢噢——！！！</anim></size>",
  ui_story_5020_50201701_44_dialog_content = "<size=50><anim type=Shake>將軍已死——！！！</anim></size>",
  ui_story_5020_50201701_45_dialog_content = "<size=50><anim type=Shake>雲島萬歲——！！！</anim></size>",
  ui_story_5020_50201701_46_dialog_content = "<anim type=Shake>噢噢噢噢……</anim>",
  ui_story_5020_50201701_47_dialog_content = "…………",
  ui_story_5020_50201701_48_dialog_content = "統……統領大人！",
  ui_story_5020_50201701_49_dialog_content = "您......您還活著？！",
  ui_story_5020_50201701_50_dialog_content = "您真的是薙大人嗎？",
  ui_story_5020_50201701_51_dialog_content = "統領大人？啊，統領大人……您要去哪裡！",
  ui_story_5020_50201701_52_dialog_content = "請等一下！",
  ui_story_5020_50201701_53_dialog_content = "……？",
  ui_story_5020_50201701_54_dialog_content = "是你們啊。",
  ui_story_5020_50201701_55_dialog_content = "如果一定要告別的話，麻煩快一點。",
  ui_story_5020_50201701_56_dialog_content = "師父留步！",
  ui_story_5020_50201701_57_dialog_content = "瑤，在此……抱拳了！",
  ui_story_5020_50201701_58_dialog_content = "妳……妳這是幹什麼？",
  ui_story_5020_50201701_59_dialog_content = "瑤此次雲島之行，經歷各種困難，還多虧了師父！",
  ui_story_5020_50201701_60_dialog_content = "（怎麼聽起來不像什麼好話啊！）",
  ui_story_5020_50201701_61_dialog_content = "多虧了師父，我才能一路體驗妳們上一代人經歷過的種種立場紛爭。",
  ui_story_5020_50201701_62_dialog_content = "這些……都是我過往的人生經驗中不曾見過的東西。",
  ui_story_5020_50201701_63_dialog_content = "只憑這一點，就讓我再叫您一聲師父吧。",
  ui_story_5020_50201701_64_dialog_content = "此後，師父要是碰到什麼困難，直接聯繫艾斯特拉大陸影鎮林家商會！",
  ui_story_5020_50201701_65_dialog_content = "瑤無論身在何處，絕對會來到師父身邊出手相助！",
  ui_story_5020_50201701_66_dialog_content = "呵呵……謝謝妳，瑤。",
  ui_story_5020_50201701_67_dialog_content = "只是接下來的路，我務必要自己一個人走了。",
  ui_story_5020_50201701_68_dialog_content = "我只有親手終結本島對雲島的統治，才能徹底將這些恩怨勾銷。",
  ui_story_5020_50201701_69_dialog_content = "您……接下來要前往本島？",
  ui_story_5020_50201701_70_dialog_content = "師父，請您……",
  ui_story_5020_50201701_71_dialog_content = "保重自己，為雲島開闢出新的世界吧。",
  ui_story_5020_50201701_72_dialog_content = "在下和燭幽軍眾兵，永遠是您的後備力量。",
  ui_story_5020_50201701_73_dialog_content = "喔？雨森……",
  ui_story_5020_50201701_74_dialog_content = "妳終於也成長了。",
  ui_story_5020_50201701_75_dialog_content = "與我相比，妳現在對燭幽軍統領得更加自如了吧。",
  ui_story_5020_50201701_76_dialog_content = "請薙大人多加保重，得勝凱旋！",
  ui_story_5020_50201701_77_dialog_content = "……",
  ui_story_5020_50201701_78_dialog_content = "那麼，再會吧。",
  ui_story_5020_50201701_79_dialog_content = "啊！等等，還有那個東西……",
  ui_story_5020_50201701_80_dialog_content = "PlayerName，我們把那個交給她吧。",
  ui_story_5020_50201701_81_dialog_content = "說......說的也是！",
  ui_story_5020_50201701_82_dialog_content = "嗯？",
  ui_story_5020_50201701_83_dialog_content = "薙，請收下這本手札吧。",
  ui_story_5020_50201701_84_dialog_content = "雖然她從來沒有寫下過相關的交代……",
  ui_story_5020_50201701_85_dialog_content = "但她的遺留之物，對您來說也許很重要。",
  ui_story_5020_50201701_86_dialog_content = "這個東西果然還是應該交由您保管。",
  ui_story_5020_50201701_87_dialog_content = "月……竟然有寫日誌的習慣……",
  ui_story_5020_50201701_88_dialog_content = "我從來沒有注意過……",
  ui_story_5020_50201701_89_dialog_content = "但是，我已經決定不顧一切地前往本島了。",
  ui_story_5020_50201701_90_dialog_content = "請你們代我拿著吧。",
  ui_story_5020_50201701_91_dialog_content = "您真的……不打算再看看了嗎？",
  ui_story_5020_50201701_92_dialog_content = "拋卻過去的前提是釋懷，而不是逃避。",
  ui_story_5020_50201701_93_dialog_content = "看了之後，您心裡的一些疑惑和怨責，應該會得到解答。",
  ui_story_5020_50201701_94_dialog_content = "……",
  ui_story_5020_50201701_95_dialog_content = "好。",
  ui_story_5020_50201701_96_dialog_content = "……",
  ui_story_5020_50201701_97_dialog_content = "…………",
  ui_story_5020_50201701_98_dialog_content = "<size=30>姐姐……</size>",
  ui_story_5020_50201701_99_dialog_content = "姐姐…………",
  ui_story_5020_50201701_100_dialog_content = "<color=#e8d9bb>江富城城下町，街道上</color>",
  ui_story_5020_50201701_101_dialog_content = "哎呀，真是和諧的景象呢～",
  ui_story_5020_50201701_102_dialog_content = "飄著彩幡的舞台、準備就緒的太鼓、櫻花樹下撈金魚的人們……",
  ui_story_5020_50201701_103_dialog_content = "還有乖乖坐在我旁邊、沒有從中搗亂的忍者大人～",
  ui_story_5020_50201701_104_dialog_content = "請不要用這種名字稱呼在下。",
  ui_story_5020_50201701_105_dialog_content = "不要辜負阿桃和阿杏的期待，面前的茶非常好喝喔。",
  ui_story_5020_50201701_106_dialog_content = "……我討厭味道濃厚的事物，我不會在這家店吃下任何東西。",
  ui_story_5020_50201701_107_dialog_content = "（咕……）",
  ui_story_5020_50201701_108_dialog_content = "唔……！",
  ui_story_5020_50201701_109_dialog_content = "來囉～客人們久等了！",
  ui_story_5020_50201701_110_dialog_content = "來試試本店得意新作——蟹家流水素面吧！",
  ui_story_5020_50201701_111_dialog_content = "這是經過了瑤大俠的無數次無畏試吃，而甄選出的獨家配方！",
  ui_story_5020_50201701_112_dialog_content = "嗝……好滿足……",
  ui_story_5020_50201701_113_dialog_content = "（瑤……已經完全倒下了！）",
  ui_story_5020_50201701_114_dialog_content = "既……既然如此……",
  ui_story_5020_50201701_115_dialog_content = "在下吃兩口倒是也無妨。",
  ui_story_5020_50201701_116_dialog_content = "隨著新品的推出，新的配套傳說也要趕快編寫了！",
  ui_story_5020_50201701_117_dialog_content = "講過太多遍的故事可沒辦法留住新的顧客呢！",
  ui_story_5020_50201701_118_dialog_content = "PlayerName大人，您覺得什麼樣的故事比較合適呢？",
  ui_story_5020_50201701_119_dialog_content = "哎？！問我嗎？",
  ui_story_5020_50201701_120_dialog_content = "以我的審美來看的話……",
  ui_story_5020_50201701_121_option_content = "不如就講一講「三個故人」的故事吧",
  ui_story_5020_50201701_122_dialog_content = "三個糾葛一生的故人，用他們自己的方式，護佑著一方土地。",
  ui_story_5020_50201701_123_dialog_content = "那對注定分道揚鑣的姐妹，屬於她們的歌謠卻仍在這個地方流傳。",
  ui_story_5020_50201701_124_dialog_content = "那對不被理解的巫女和將軍，在立場分明的身分下，卻彼此交換了一部分信任。",
  ui_story_5020_50201701_125_dialog_content = "那對注定為敵的戰士，戰鬥到最終一刻，卻用互相理解對方的方式，做了最後的告別。",
  ui_story_5020_50201701_126_dialog_content = "在每個人的預想中，這方土地都按照他們的想法邁向了和平……",
  ui_story_5020_50201701_127_dialog_content = "這種故事……真的適合在吃飯的時候聽嗎！",
  ui_story_5020_50201701_128_option_content = "不如就講一講「三個孩子」的故事吧",
  ui_story_5020_50201701_129_dialog_content = "三個不尋常的孩子，因為各不相同的理由，踏上了討伐邪惡妖怪之路……",
  ui_story_5020_50201701_130_dialog_content = "但是在這個旅程中，他們每個人都獲得了比勝利更珍貴的東西。",
  ui_story_5020_50201701_131_dialog_content = "戴著堅硬面具的鐵皮人，得到了「被友情填滿的心臟」。",
  ui_story_5020_50201701_132_dialog_content = "被海水浸泡過的稻草人，得到了「充滿回憶的大腦」。",
  ui_story_5020_50201701_133_dialog_content = "披著表演外套的小獅子，得到了「與命運對抗的勇氣」……",
  ui_story_5020_50201701_134_dialog_content = "不要照搬北境孩子的睡前故事啊！太突兀了吧！",
  ui_story_5020_50201701_135_dialog_content = "唔……聽起來好像是個不錯的想法呢～",
  ui_story_5020_50201701_136_dialog_content = "那麼我們就照著PlayerName大人說的寫吧！",
  ui_story_5020_50201701_137_dialog_content = "不過在這之前，要為上一段雲島傳說收尾才行……",
  ui_story_5020_50201701_138_dialog_content = "收尾？……迄今為止，還有什麼事情是我們不知道的嗎？",
  ui_story_5020_50201701_139_dialog_content = "哼哼哼……這可是我們剛從打工的那裡收集到的資訊哦！",
  ui_story_5020_50201701_140_dialog_content = "你們要是想听嘛，也很簡單～只需要……",
  ui_story_5020_50201701_141_dialog_content = "再來一碗。",
  ui_story_5020_50201701_142_dialog_content = "客人，您很上道嘛！那麼，上回的故事說到——",
  ui_story_5020_50201701_143_dialog_content = "「據說藤雲是個刀槍不入、鐵石心腸的傢伙」，雲島上下沒人能知道他的弱點。除了……",
  ui_story_5020_50201701_144_dialog_content = "鏘鏘——除了我們柏乃！",
  ui_story_5020_50201701_145_dialog_content = "哎？好……好突然！在......在叫我嗎……",
  ui_story_5020_50201701_146_dialog_content = "來吧，打工的～跟PlayerName大人說一說，妳曠工的那天看到了什麼。",
  ui_story_5020_50201701_147_dialog_content = "我……我那天也只是去了一趟城郊的<color=#FFB400>墓園</color>賞櫻……現在正好是白櫻花飄落的季節……",
  ui_story_5020_50201701_148_dialog_content = "剛走到門口……卻看到已經有人在裡面了……",
  ui_story_5020_50201701_149_dialog_content = "？！",
  ui_story_5020_50201701_150_dialog_content = "（是趕在我們之前到達墓園的那個人！）",
  ui_story_5020_50201701_151_dialog_content = "請問……那個人究竟是誰呢！！！",
  ui_story_5020_50201701_152_dialog_content = "啊啊……PlayerName大人……好兇......好急切……",
  ui_story_5020_50201701_153_dialog_content = "對......對不起……",
  ui_story_5020_50201701_154_dialog_content = "雖然他並沒有發現我，但我卻看得很清楚……",
  ui_story_5020_50201701_155_dialog_content = "那個人就是……<color=#FFB400>藤雲將軍</color>……",
  ui_story_5020_50201701_156_dialog_content = "……",
  ui_story_5020_50201701_157_dialog_content = "他在不知道是誰的墓前，只是安靜地站著……身後也沒有跟著一個武士……",
  ui_story_5020_50201701_158_dialog_content = "我以為他會把墓前的那把金色的佩劍拿走......但是他也沒有做這種事......",
  ui_story_5020_50201701_159_dialog_content = "反而是在臨走前……鄭重地留下了一本什麼東西……",
  ui_story_5020_50201701_160_dialog_content = "然……然後他差點就看見我了……嚇得我立刻逃走了……",
  ui_story_5020_50201701_161_dialog_content = "……",
  ui_story_5020_50201701_162_dialog_content = "果然是藤雲嗎……",
  ui_story_5020_50201701_163_dialog_content = "正是如此！無情無義的前一代將軍，卻在無人的角落裡偷偷祭奠過去的故人……",
  ui_story_5020_50201701_164_dialog_content = "哼哼，如果這樣流傳下去……還可以再賺來一群新的客人呢！",
  ui_story_5020_50201701_165_dialog_content = "喂，可是這件事……",
  ui_story_5020_50201701_166_dialog_content = "算啦，PlayerName大人。",
  ui_story_5020_50201701_167_dialog_content = "如果這件事……可以成為將軍和上一代巫女留給雲島最後的印象……",
  ui_story_5020_50201701_168_dialog_content = "那就用它來為雲島的過往畫上句號吧。",
  ui_story_5020_50201701_169_dialog_content = "畢竟，新的時代……",
  ui_story_5020_50201701_170_dialog_content = "已經要開始了啊——",
  ui_story_5020_50201701_171_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5020_50201701_172_dialog_content = "讓開讓開，別在這裡擺攤了，把通向主城的路讓出來。",
  ui_story_5020_50201701_173_dialog_content = "主城？哪還有什麼主城啊，你哪來的外鄉人？",
  ui_story_5020_50201701_174_dialog_content = "……",
  ui_story_5020_50201701_175_dialog_content = "看，本島已經開始行動了，那些人身上的穿戴，是本島的紋樣呢。",
  ui_story_5020_50201701_176_dialog_content = "果然，他們並不會放棄對雲島的管轄權。",
  ui_story_5020_50201701_177_dialog_content = "凜音，妳……要繼續留在這裡嗎？",
  ui_story_5020_50201701_178_dialog_content = "呵呵～我已經有了我自己的打算了。倒是你們……",
  ui_story_5020_50201701_179_dialog_content = "想過要怎麼回去嗎？",
  ui_story_5020_50201701_180_dialog_content = "不用擔心，我們駕駛巨像，按照原路返回就可以了。",
  ui_story_5020_50201701_181_dialog_content = "說到這個……要好好把臨空者號修整一下……",
  ui_story_5020_50201701_182_dialog_content = "巨像？……臨空者號？",
  ui_story_5020_50201701_183_dialog_content = "哎呀～是一些從來沒有聽過的詞……",
  ui_story_5020_50201701_184_dialog_content = "果然還是應該多去外面的世界看看呢～",
  ui_story_5020_50201701_185_dialog_content = "<color=#e8d9bb>江富城港口，碼頭</color>",
  ui_story_5020_50201701_186_dialog_content = "行啦行啦，大家就送到這裡吧！",
  ui_story_5020_50201701_187_dialog_content = "接我的船差不多也要趕到啦。",
  ui_story_5020_50201701_188_dialog_content = "哼。",
  ui_story_5020_50201701_189_dialog_content = "倒不是說一定要為妳送行……",
  ui_story_5020_50201701_190_dialog_content = "在下不過是遵循雲島的待客之道罷了。",
  ui_story_5020_50201701_191_dialog_content = "雨......雨森……",
  ui_story_5020_50201701_192_dialog_content = "我……",
  ui_story_5020_50201701_193_dialog_content = "<size=45>嗚嗚嗚嗚哇——！</size>",
  ui_story_5020_50201701_194_dialog_content = "妳！妳......妳……妳突然做什麼！",
  ui_story_5020_50201701_195_dialog_content = "嗚嗚嗚嗚嗚……原來雨森也很捨不得我！我……",
  ui_story_5020_50201701_196_dialog_content = "<size=50><anim type=Shake>我超級捨不得大家哇——</anim></size>",
  ui_story_5020_50201701_197_dialog_content = "好啦小瑤～乖孩子，不要哭啦～",
  ui_story_5020_50201701_198_dialog_content = "我們以後還有再見的機會呢。",
  ui_story_5020_50201701_199_dialog_content = "哇，什……什麼？",
  ui_story_5020_50201701_200_dialog_content = "凜音……妳……",
  ui_story_5020_50201701_201_dialog_content = "<size=50><anim type=Shake>嗚哇哇哇哇哇！妳竟然不跟我一起走嗎？！</anim></size>",
  ui_story_5020_50201701_202_dialog_content = "<size=55><anim type=Shake>嗚哇哇哇哇哇哇哇哇哇……</anim></size>",
  ui_story_5020_50201701_203_dialog_content = "哎呀哎呀……糟糕……",
  ui_story_5020_50201701_204_dialog_content = "小瑤，聽我說——",
  ui_story_5020_50201701_205_dialog_content = "雲島還有很多需要我去做的事……",
  ui_story_5020_50201701_206_dialog_content = "本島的勢力已經開始出動了，不能沒有人留在這裡制衡他們。",
  ui_story_5020_50201701_207_dialog_content = "雲照鏡和天雲斬......已經被我妥善收起來了。",
  ui_story_5020_50201701_208_dialog_content = "今後，我將用我自己的力量，為雲島帶來和平。",
  ui_story_5020_50201701_209_dialog_content = "當然了……雨森會帶著燭幽軍幫我的，對吧？",
  ui_story_5020_50201701_210_dialog_content = "這是自然。",
  ui_story_5020_50201701_211_dialog_content = "就算沒有你這句話，對抗本島也一向是燭幽軍的使命。",
  ui_story_5020_50201701_212_dialog_content = "所以說……小瑤，我還要為雲島帶來很多改變。",
  ui_story_5020_50201701_213_dialog_content = "妳可以相信我嗎？",
  ui_story_5020_50201701_214_dialog_content = "嗚啊啊……我當然覺得凜音絕對沒問題的……",
  ui_story_5020_50201701_215_dialog_content = "那麼……凜音、雨森……還有柏乃和阿桃阿杏……",
  ui_story_5020_50201701_216_dialog_content = "大家可要多多保重啊！！！",
  ui_story_5020_50201701_217_dialog_content = "以及……PlayerName和薇絲！",
  ui_story_5020_50201701_218_dialog_content = "是......是的？",
  ui_story_5020_50201701_219_dialog_content = "謝謝你們，不辭辛苦地接受這個委託，帶我來到了這裡。",
  ui_story_5020_50201701_220_dialog_content = "以及，我們還一起結識了這些和記憶同等珍貴的朋友……",
  ui_story_5020_50201701_221_dialog_content = "我在這座島得到的所有，果然是能夠讓我珍視一生的東西。",
  ui_story_5020_50201701_222_dialog_content = "嗚……",
  ui_story_5020_50201701_223_dialog_content = "（糟了……應該趕快安慰她……）",
  ui_story_5020_50201701_224_dialog_content = "所以——",
  ui_story_5020_50201701_225_dialog_content = "一筆遠超七位數的巨款將在我返回林家後打進你的帳戶！！！",
  ui_story_5020_50201701_226_dialog_content = "哎？！！！",
  ui_story_5020_50201701_227_dialog_content = "……不行嗎！我......我也只能想到用這種方式表達感謝了！",
  ui_story_5020_50201701_228_dialog_content = "已……已經太多了！",
  ui_story_5020_50201701_229_dialog_content = "啊……要好好算算該怎麼規劃這一筆收入了，無論如何首先要修復巨像，然後再……",
  ui_story_5020_50201701_230_dialog_content = "（已經這麼迫不及待了嗎！）",
  ui_story_5020_50201701_231_dialog_content = "哦呀，那個緩緩駛過來的是……",
  ui_story_5020_50201701_232_dialog_content = "<color=#e8d9bb>嘟嘟——嗚——</color>",
  ui_story_5020_50201701_233_dialog_content = "唔唔……嘔——",
  ui_story_5020_50201701_234_dialog_content = "這就是……這就是大海的力量嗎……",
  ui_story_5020_50201701_235_dialog_content = "哇，義......義姐，你別這樣啊……我都有點害怕了！",
  ui_story_5020_50201701_236_dialog_content = "千萬不要讓別人知道，林家大名鼎鼎的瑛……她的弱點是坐船啊！",
  ui_story_5020_50201701_237_dialog_content = "不……嘔……不要喊了……",
  ui_story_5020_50201701_238_dialog_content = "嗚嗚嗚嗚嗚——",
  ui_story_5020_50201701_239_dialog_content = "貴客……我的一頓七碗麵貴客……",
  ui_story_5020_50201701_240_dialog_content = "請一定要再來雲島做客……",
  ui_story_5020_50201701_241_dialog_content = "再來蟹家拉麵店啊！",
  ui_story_5020_50201701_242_dialog_content = "嗚嗚嗚嗚嗚嗚嗚嗚……",
  ui_story_5020_50201701_243_dialog_content = "唔……老......老闆們……",
  ui_story_5020_50201701_244_dialog_content = "瑤大俠試出的新產品……一......一定會大賣的……",
  ui_story_5020_50201701_245_dialog_content = "不要難過了啊……",
  ui_story_5020_50201701_246_dialog_content = "說的也是！",
  ui_story_5020_50201701_247_dialog_content = "小瑤——",
  ui_story_5020_50201701_248_dialog_content = "一路保重啊——",
  ui_story_5020_50201701_249_dialog_content = "下次見面，可不要丟我的臉。",
  ui_story_5020_50201701_250_dialog_content = "啊……",
  ui_story_5020_50201701_251_dialog_content = "大家……",
  ui_story_5020_50201701_252_dialog_content = "再會了——！",
  ui_story_5020_50201701_253_dialog_content = "瑤走上了船，凜音揮著手告別，雨森則站在其後，遠遠地望著。",
  ui_story_5020_50201701_254_dialog_content = "小船駛出地平線之前的這段時光，她們會特別珍惜吧。",
  ui_story_5020_50201701_255_dialog_content = "十年前，一個人的死拆散了三個女孩。",
  ui_story_5020_50201701_256_dialog_content = "十年後，又是另一人的死讓她們分離。",
  ui_story_5020_50201701_257_dialog_content = "粉白色的雪在雲島上花開十載，見證著女孩們從聚到散。",
  ui_story_5020_50201701_258_dialog_content = "也見證著已故之人，縱是久隔生死，終於又走到了一起。",
  ui_story_5020_50201701_259_dialog_content = "<color=#e8d9bb>終</color>"
}
return config
